-- GENERATED by `wfj generate` from data/quest/quest-0006.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("quest", {
  [6001] = { "Corpo e cuore", "Usa la ⟦Cenarion Moondust=Polvere di Luna Cenariana⟧ sulla Moonkin Stone di Auberdine per far comparire ⟦Lunaclaw=Lunagrinfia⟧. A quel punto dovrai affrontare ⟦Lunaclaw=Lunagrinfia⟧ e conquistare la forza del corpo e del cuore che possiede.\n\nQuando hai finito, parla con ⟦Mathrengyl Bearwalker=Mathrengyl Domaorsi⟧ a Darnassus.", "Subito a est di Auberdine si trovano molte grotte dei lunagufi. Quella più vicina ad Auberdine custodisce una Moonkin Stone. ⟦Lunaclaw=Lunagrinfia⟧, il difensore della pietra, ti affronterà solo quando vi verrà applicata della ⟦Cenarion Moondust=Polvere di Luna Cenariana⟧. ⟦Lunaclaw=Lunagrinfia⟧ racchiude in sé una forza che tu, come membro dell'Artiglio, devi usare.\n\nTi sei guadagnat<o/a> il diritto di usare questa ⟦Cenarion Moondust=Polvere di Luna Cenariana⟧, {name}... ora dimostrami di esserti guadagnat<o/a> il diritto di possedere la forza del corpo e la forza del cuore necessarie a un druido!", "Quando avrai affrontato la prova che ti attende, la tua comprensione della forza del corpo e della forza del cuore sarà completa. Fino ad allora, non posso aiutarti oltre.", "Hai finalmente compiuto il tuo grande passo in un mondo molto più vasto, {name}. Sento in te l'insegnamento del ⟦Great Bear Spirit=Grande Spirito Orso⟧, e sento che hai ricevuto la forza che possedeva ⟦Lunaclaw=Lunagrinfia⟧.\n\nNon ci sono più ostacoli sul tuo cammino... lascia che ora ti insegni cosa significa essere <un/una> <Druido/Druida> dell'Artiglio!", 0x9109866f, 0xe7d92ce2, 0xd25471ff, 0xf431a09c, 0x5233b46d, "....." },
  [6002] = { "Corpo e cuore", "Usa la ⟦Cenarion Lunardust=Polvere Lunare Cenariana⟧ sulla Moonkin Stone tra Mulgore e le ⟦Barrens=Savane⟧ per far comparire ⟦Lunaclaw=Lunagrinfia⟧. A quel punto dovrai affrontare ⟦Lunaclaw=Lunagrinfia⟧ e conquistare la forza del corpo e del cuore che possiede.\n\nQuando hai finito, parla con ⟦Turak Runetotem=Turak Totem Runico⟧ a ⟦Thunder Bluff=Picco del Tuono⟧.", "Nelle terre a ovest di Taurajo, nelle ⟦Barrens=Savane⟧, appena prima che lascino il posto a Mulgore, si trova una Moonkin Stone. I lunagufi sono bestie speciali, non originarie di queste parti. ⟦Lunaclaw=Lunagrinfia⟧, il difensore della pietra, ti affronterà quando vi verrà applicata della ⟦Cenarion Lunardust=Polvere Lunare Cenariana⟧. ⟦Lunaclaw=Lunagrinfia⟧ racchiude in sé una forza che tu, come membro dell'Artiglio, devi usare.\n\nTi sei guadagnat<o/a> il diritto di usare questa ⟦Cenarion Lunardust=Polvere Lunare Cenariana⟧, {name}... ora dimostrami di esserti guadagnat<o/a> il diritto di possedere la forza del corpo e la forza del cuore necessarie a un druido!", "Quando avrai affrontato la prova che ti attende, la tua comprensione della forza del corpo e della forza del cuore sarà completa. Fino ad allora, non posso aiutarti oltre.", "Hai finalmente compiuto il tuo grande passo in un mondo molto più vasto, {name}. Sento in te l'insegnamento del ⟦Great Bear Spirit=Grande Spirito Orso⟧, e sento che hai ricevuto la forza che possedeva ⟦Lunaclaw=Lunagrinfia⟧.\n\nNon ci sono più ostacoli sul tuo cammino... lascia che ora ti insegni cosa significa essere <un/una> <Druido/Druida> dell'Artiglio!", 0x9109866f, 0xd7388bf3, 0x130e04b9, 0xf431a09c, 0x5233b46d, "....." },
  [6004] = { "Questioni in sospeso", "Uccidi 2 Scarlet Medic, 2 Scarlet Hunter, 2 Scarlet Magi e 2 Scarlet Knight, poi torna da ⟦Kirsta Deepshadow=Kirsta Ombrafonda⟧ nelle ⟦Western Plaguelands=Terre Infette Occidentali⟧.", "Mi hanno mandata in avanscoperta a fare qualche danno e a saggiare la forza delle difese di Valsalda. Alcuni nell'⟦Alliance=Alleanza⟧ pensano che quella cittadina abbia un'importanza più che storica. Non spetta a me chiedermi quale sia quest'importanza ma, in ogni caso, non sono in condizione di continuare finché non mi sarò riposata.\n\nSe te la senti, pagherei bene per un po' d'aiuto. Comincia a sud di qui, dal loro accampamento vicino al piccolo baluardo che hanno eretto. Se ti dimostri abbastanza forte, forse potrei chiederti aiuto per il mio obiettivo principale.", "Come va, {name}? Sono più forti di quanto pensavi? Spero di no. Se devo andare fino in fondo, servirà molta più forza di quella che ti ho già chiesto.", "Ben fatto, {name}. Mi stupisce che te ne sia occupat<o/a> così in fretta. Grazie.\n\nNon ho ancora conosciuto nessuno che approvi la ⟦Scarlet Crusade=Crociata Scarlatta⟧ e i suoi metodi. Credo nella Luce quanto chiunque altro a ⟦Stormwind=Roccavento⟧, ma loro hanno dimostrato di voler solo uccidere chiunque non sia fedele al loro movimento... persino gli innocenti.", 0xe0ec1241, 0xa4c7cfa2, 0x6771ee99, 0x38343473, 0x672f1da6, "....." },
  [6021] = { "⟦Zaeldarr the Outcast=Zaeldarr l'Errante⟧", "Porta la ⟦Zaeldarr's Head=Testa di Zaeldarr⟧ al curato Alen, alla ⟦Light's Hope Chapel=Cappella della Luce⟧.", "Ci credi che, con tutti i guai che abbiamo nelle Terre Infette... dobbiamo preoccuparci anche dei ladri? E non semplici ladri: ladri troll.\n\nE non semplici ladri troll. Ladri troll morti!\n\nLi guida un grosso troll morto di nome ⟦Zaeldarr the Outcast=Zaeldarr l'Errante⟧. Vengono qui di notte, rubano i corpi dalla fossa qui sotto e poi li portano nel loro malvagio covo da troll morti: la Cripta di Zaeldarr, a ovest.\n\nVa' laggiù ed elimina Zaeldarr, {name}. Ne ho fin sopra i capelli dei suoi misfatti!", "Hai trovato il covo, {name}? Ti sei <occupato/occupata> di Zaeldarr?", "Ottimo, l'hai preso! E spero che tu abbia dato una lezione anche alla sua banda!", 0x4f22991f, 0x5866d194, 0x3e70ba0d, 0x929d2bce, 0x3752d70b, "....." },
  [6022] = { "Uccidere con uno scopo", "Raggiungi il ⟦Corin's Crossing=Crocevia di Corin⟧, a est, e fai strage del Flagello che infesta la cittadina. Raccogli 7 pezzi di ⟦Living Rot=Putridume Vivo⟧ in meno di 10 minuti. Usa il ⟦Mortar and Pestle=Mortaio e Pestello⟧ per macinare il ⟦Living Rot=Putridume Vivo⟧ e ottenere il ⟦Coagulated Rot=Putridume Coagulato⟧.", "Finché resti nella mia tenuta, uccidi con uno scopo.\n\nIl tuo primo compito è sfamare i miei segugi.\n\nPrendi questo mortaio e pestello e va' al ⟦Corin's Crossing=Crocevia di Corin⟧. Lì troverai un'ampia scelta di creature del Flagello da massacrare. Dalle loro carcasse fresche mi serve del putridume vivo. Prendi il putridume vivo e macinalo nel mortaio, poi lascialo riposare finché non coagula. Riportami qui il putridume coagulato.\n\nE, imbecille, renditi conto che il putridume vivo dei non morti non resta 'vivo' a lungo. Devi uccidere in fretta!", "Stai piangendo? Se per te è troppo 'noioso', '<eroe/eroina>', ti consiglio di tornare dalla Dama Oscura e informarla dei terribili maltrattamenti che hai subito nella mia fattoria.\n\nOra levati dalla mia vista!", "Deludente. Speravo di dover dare in pasto te ai miei segugi.\n\n<Nathanos sospira.>\n\nBe', almeno avranno qualcosa da mangiare.", 0x7a12f351, 0x9e1cfc74, 0x719c0fa7, 0x7acc712f, 0xd1ebac5f, "....." },
  [6023] = { "Questioni in sospeso", "Uccidi ⟦Huntsman Radley=Predatrice Radley⟧ e ⟦Cavalier Durgen=Cavaliere Durgen⟧, poi torna da ⟦Kirsta Deepshadow=Kirsta Ombrafonda⟧ nelle ⟦Western Plaguelands=Terre Infette Occidentali⟧.", "La mia vera missione era indebolire le forze periferiche della Crociata Scarlatta e poi infiltrarmi a ⟦Hearthglen=Valsalda⟧ per stimarne il numero. Non sono ancora in condizione di farlo da sola, quindi posso chiederti di nuovo il tuo aiuto, {name}? Da quel che ho scoperto prima di essere smascherata, la Crociata ha due membri importanti che sono la spina dorsale delle sue forze fuori dalla città: la predatrice Radley e il cavaliere Durgen. Uccidili e faremo progressi. Dovrebbero trovarsi lungo il passo di ⟦Hearthglen=Valsalda⟧, fuori dalla città vera e propria.", "Li hai trovati, {name}? Una volta sistemati quei due, potrò entrare a ⟦Hearthglen=Valsalda⟧ e dare un'occhiata più da vicino alla loro organizzazione. Non posso farlo senza il tuo aiuto. Ti prego, trova Radley e Durgen per me.", "Grazie, {name}. Mi hai aiutata più di quanto potessi sperare. L'aria qui sembra prosciugarmi la volontà. Sono stanca, e sento che più resto qui, meno miglioro.\n\nNon so bene come farò a infiltrarmi a ⟦Hearthglen=Valsalda⟧ e a riferire quanto sia forte la presenza della Crociata Scarlatta.\n\nMa questa è un'altra faccenda. Prima che tu vada, ecco, prendi questo... come compenso per il tuo aiuto. Grazie ancora.", 0xe0ec1241, 0xbafd5572, 0xcd59769d, 0xe1d07dbf, 0x5f278f17, "....." },
  [6024] = { "La supplica di Hameya", "Uccidi ⟦Infiltrator Hameya=Infiltrato Hameya⟧. Usa la sua chiave sul cumulo di terra dietro la Cripta di Zaeldarr.", "Uccidimi. Prima che sia troppo tardi.\n\nIo sono Hameya. Mentre andavamo a ⟦Zul'Mashar=Zul'mashar⟧, io e i miei fratelli abbiamo mangiato della carne guasta... e siamo cambiati. Siamo infetti.\n\nOra sento le parole del lich, che mi spingono a raggiungere ⟦Zul'Mashar=Zul'mashar⟧ e a infettare altri della mia gente. Non riesco a resistere, perciò ho scritto questa pergamena prima che la mia volontà mi abbandonasse.\n\nHo sepolto un forziere nella terra accanto a un carro, dietro questa cripta, ma solo la mia chiave può aprirlo. La chiave ce l'ho io. Se vuoi il mio tesoro, trovami.\n\nUccidimi. Prima che sia troppo tardi.", "Il forziere sepolto qui è chiuso saldamente.", "Il forziere di Hameya è aperto!!", 0xee455833, 0x60125197, 0xa2b42b67, 0x524048c5, 0x349f4764, "....." },
  [6025] = { "Questioni in sospeso", "Entra a ⟦Hearthglen=Valsalda⟧ e trova un punto sopraelevato da cui osservare la cittadina e stimare le forze della Crociata Scarlatta, poi torna da ⟦Kirsta Deepshadow=Kirsta Ombrafonda⟧ nelle ⟦Western Plaguelands=Terre Infette Occidentali⟧.", "Cosa? Davvero? Vuoi saperne di più? Ma hai già fatto così tanto per me, {name}. Non potrei mai chiederti di entrare a ⟦Hearthglen=Valsalda⟧ al posto mio.\n\nNe sei sicur<o/a>, {name}? ⟦Hearthglen=Valsalda⟧ è molto più pericolosa del Passo: non posso darti alcuna protezione, e nemmeno informazioni su ciò che potresti trovarti davanti.\n\nBe', se vuoi davvero aiutarmi, entra nella cittadina e trova un punto elevato da cui averne una buona visuale. Da lì potrai stimare il loro numero e riferirmelo. Ma fa' attenzione...", "È un compito pericoloso, {name}. Invidio il tuo coraggio.", "Ce l'hai fatta, {name}! Grazie!\n\nTornerò da Elling... cioè, a ⟦Stormwind=Roccavento⟧ appena possibile. Ecco, prendi queste monete: è il minimo che possa fare per te. Fai onore alla tua gente, {name}. Grazie e buona fortuna.", 0xe0ec1241, 0xfa067beb, 0x16a8c395, 0xb6a2f182, 0x696280bf, "....." },
  [6026] = { "È chiedere molto", "Smokey LaRue vuole che tu gli procuri 2 Lingotto di Torio, 1 ⟦Golden Rod=Verga d'Oro⟧, 8 Bomba ad Alto Potenziale e 8 Attivatore Instabile.\n\nPer questi oggetti dovrai trovare un fabbro e un ingegnere.", "Questa gente dell'⟦Argent Dawn=Alba d'Argento⟧ ha incaricato il vecchio Smokey di fare qualche lavoretto di demolizione. La mamma di Smokey mica ha cresciuto un fesso. Quando sul tavolo si sbattono monete d'oro, i servizi di Smokey sono disponibili. Questo è il mio motto!\n\nOra, sarei disposto a dividere il compenso con te, se te la senti di fare un po' di strada. Ecco l'accordo: io vado a ⟦Plaguewood=Malaselva⟧ e segno gli edifici da distruggere. Tu raccogli i componenti per le bombe. Ci ritroviamo qui quando hai tutto. Affare fatto?", "Fidati del vecchio Smokey, {race}. La ricompensa ne varrà la pena. Questa gente dell'⟦Argent Dawn=Alba d'Argento⟧ non scherza quando si tratta di pagare.", "Posso pagarti metà in anticipo e metà a lavoro finito.", 0x5d72aed6, 0xced858e1, 0xe8eab7ef, 0xda3f6ed0, 0xfc620627, "....." },
  [6027] = { "Il ⟦Book of the Ancients=Libro degli Antichi⟧", "Prendi il ⟦Book of the Ancients=Libro degli Antichi⟧ e riportalo ad Azore Aldamort, alla torre di Ethel Rethor.", "{name}, ti affido la ⟦Gem of the Serpent=Gemma del Serpente⟧. Posala sulla mano della statua del serpente sull'⟦Ranazjar Isle=Isola di Ranazjar⟧, un'isoletta a nord-ovest di qui. Posandola evocherai colui che protegge il ⟦Book of the Ancients=Libro degli Antichi⟧. Questo libro contiene i segreti dei naga, segreti custoditi per secoli. Portami il libro, e scopriremo molte cose sui nostri nemici squamati!", "Ah, {name}! Che piacere rivederti. Hai il ⟦Book of the Ancients=Libro degli Antichi⟧?", "Il ⟦Book of the Ancients=Libro degli Antichi⟧, perduto da tanto tempo! Mi assicurerò che venga consegnato all'alto consiglio. Oggi hai fatto un ottimo lavoro, e per questo meriti un ringraziamento... come si ringrazia un eroe!", 0x506094ee, 0x9ded0f2e, 0x0b6c3f2d, 0xb011a969, 0xf911986b, "....." },
  [6028] = { "Il ⟦Everlook Report=Rapporto di Lungavista⟧", "Consegna il ⟦Everlook Report=Rapporto di Lungavista⟧ all'ufficiale d'argento Cuorpuro all'⟦Chillwind Camp=Accampamento di Ventofreddo⟧, nelle ⟦Western Plaguelands=Terre Infette Occidentali⟧.", "Cerco una persona responsabile che mi aiuti in una faccenda piccola, ma comunque importante. Sono qui per rappresentare gli interessi dell'Alba d'Argento presso il governo locale di ⟦Everlook=Lungavista⟧. Devo far arrivare un rapporto sui progressi all'ufficiale d'argento Cuorpuro, all'⟦Chillwind Camp=Accampamento di Ventofreddo⟧; è piuttosto lontano da qui, lungo il margine meridionale delle ⟦Western Plaguelands=Terre Infette Occidentali⟧.\n\nSe posso permettermi, sarebbe un modo perfetto per presentarti alla mia superiore e magari ottenere un po' di lavoro da lei!", "Salute, {class}. A nome dell'⟦Argent Dawn=Alba d'Argento⟧, ti offro sicurezza e riparo finché resti qui all'⟦Chillwind Camp=Accampamento di Ventofreddo⟧. Potrei anche avere del lavoro per te...", "Gregor è davvero pieno di risorse. Tratta con il ⟦Steamwheedle Cartel=Cartello degli Spargifumo⟧ da tempo ormai, ed è diventato un esperto nell'«arte» delle trattative con i goblin. Anche se è vero che la lealtà dei goblin va anzitutto a chi ha le borse più piene, conoscono e rispettano anche il valore della diplomazia. Se non altro, procura loro clienti abituali...\n\nComunque, l'⟦Argent Dawn=Alba d'Argento⟧ ti riconosce il tuo impegno. Prendi questo, con i nostri ringraziamenti.", 0x0f48e274, 0x7c814620, 0x5ed36bac, 0x5219e014, 0xf4da6363, "....." },
  [6029] = { "Il ⟦Everlook Report=Rapporto di Lungavista⟧", "Consegna il ⟦Everlook Report=Rapporto di Lungavista⟧ all'ufficiale d'argento Garush alla Granbarricata, nelle ⟦Western Plaguelands=Terre Infette Occidentali⟧.", "Cerco una persona responsabile che mi aiuti in una faccenda piccola, ma comunque importante. Sono qui per rappresentare gli interessi dell'Alba d'Argento presso il governo locale di ⟦Everlook=Lungavista⟧. Devo far arrivare un rapporto sui progressi all'ufficiale argenteo Garush, alla Granbarricata; è piuttosto lontano da qui, lungo il margine occidentale delle ⟦Western Plaguelands=Terre Infette Occidentali⟧, a est delle ⟦Tirisfal Glades=Radure di Tirisfal⟧.\n\nSe posso permettermi, sarebbe un modo perfetto per presentarti al mio superiore e magari ottenere un po' di lavoro da lui!", "Salute, {class}. A nome dell'⟦Argent Dawn=Alba d'Argento⟧, ti offro sicurezza e riparo finché resti qui alla Granbarricata. Potrei anche offrirti la possibilità di combattere per una causa per cui vale la pena combattere!", "Per essere un umano, Gregor è pieno di risorse. Tratta con il ⟦Steamwheedle Cartel=Cartello degli Spargifumo⟧ da tempo ormai, ed è diventato un esperto nell'«arte» delle trattative con i goblin. Anche se è vero che la lealtà dei goblin va anzitutto a chi ha le borse più piene, conoscono e rispettano anche il valore della diplomazia. Se non altro, procura loro clienti abituali...\n\nComunque, l'⟦Argent Dawn=Alba d'Argento⟧ ti riconosce il tuo impegno. Prendi questo, con i nostri ringraziamenti.", 0x0f48e274, 0xa257e321, 0x14dacde8, 0x13244858, 0x79c7d3ac, "....." },
  [6030] = { "Il duca Nicholas Zverenhoff", "Consegna il libro \"⟦Studies in Spirit Speaking=Studi sull'Invocazione degli Spiriti⟧\" al duca Nicholas Zverenhoff alla ⟦Light's Hope Chapel=Cappella della Luce⟧, nelle ⟦Eastern Plaguelands=Terre Infette Orientali⟧.", "Un medium solitario di queste parti, un certo Umbranse, ha fornito all'⟦Argent Dawn=Alba d'Argento⟧ un vero capolavoro letterario... che equivale forse alla più grande raccolta di farneticazioni che io abbia mai visto messa per iscritto.\n\nUno dei capi più rispettati dell'Alba, il duca Nicholas Zverenhoff, è un linguista brillante. Potresti portarglielo da parte mia, in cambio di una ricompensa, s'intende? Alla ⟦Light's Hope Chapel=Cappella della Luce⟧: è lì che si trova ora, nell'estremo est delle ⟦Eastern Plaguelands=Terre Infette Orientali⟧.", "Che la Luce ti guidi in questi tempi difficili, {class}. Cosa ti porta in questo faro di speranza nel mezzo dell'oscurità e della disperazione?", "Questo... questo che mi hai portato è un libro davvero speciale. Vorrei poterti dire che \"speciale\", in questo caso, significa \"unico e forse persino illuminante\", ma resta da vedere.\n\n\"Ooooooo?\" Chi, sano di mente, può partorire una cosa del genere?\n\nBe', ho sentito parlare di questo Umbranse di cui parlava Gregor, quindi la cosa non è priva di valore. Farò del mio meglio per decifrarlo. Quanto a te... ti prego, prendi questo, per gentile concessione dell'⟦Argent Dawn=Alba d'Argento⟧. Già che sei qui, forse ci sono altre cose in cui puoi aiutarci.", 0x5cc33030, 0x06c37253, 0x462ef41a, 0x8979a1af, 0x24397ac7, "....." },
  [6031] = { "Telarunica", "Porta 30 Runecloth a Meilosh al ⟦Timbermaw Hold=Rifugio dei Mordilegno⟧.", "Tra i Mordilegno viviamo contenti. Non amiamo gli estranei. Questo è un bene per noi, ma è un male per i commerci.\n\nNon molto tempo fa, una rara amica elfa della notte è venuta dai Mordilegno e indossava un mantello di telarunica. La telarunica è rara tra noi, ma il mantello era così bello che il mio popolo vuole che io faccia altri abiti di telarunica.\n\nMi porterai della telarunica? Se me ne porterai abbastanza, ti darò qualcosa in cambio.", "Hai la telarunica? Il mio popolo non vede l'ora di avere altri oggetti di telarunica!", "Ah, hai portato la stoffa. Che materiale pregiato!\n\nGrazie, {name}. Sei <un/una> <vero/vera> <amico/amica>. Accetta questo in cambio, ti prego.", 0x444397b6, 0xe7dafac5, 0x6b70b9c1, 0x6bdbfa90, 0xa3d5c17a, "....." },
  [6032] = { "La stoffa sacra", "Porta 2 Mooncloth a Meilosh al ⟦Timbermaw Hold=Rifugio dei Mordilegno⟧.", "Anche se il popolo dei Mordilegno adora la sensazione della telarunica, per noi non è sacra. La telaluna invece è sacra.\n\nPortami una piccola scorta di questa stoffa sacra e ti insegnerò una tecnica segreta di confezione.", "Hai portato la telaluna, {name}?", "Ah, molto bene. Questa telaluna servirà per abiti sacri al nostro popolo. Grazie, {name}. Ora ti addestrerò.", 0x880d6d08, 0x538dba9c, 0x24f5a2c1, 0x92295359, 0x1ecc185c, "....." },
  [6041] = { "Quando Smokey canta, divento violento", "Raggiungi ⟦Plaguewood=Malaselva⟧, a nord-ovest della Cappella della Luce. Distruggi 8 strutture del Flagello usando la ⟦Smokey's Special Compound=Miscela Speciale di Smokey⟧ sul ⟦Mark of Detonation=Marchio di Detonazione⟧ piazzato all'interno di ogni edificio. Smokey ha fatto marcare gli ziggurat e i mattatoi.\n\nUna volta piazzata la bomba, esci dall'edificio e ammira la tua opera.\n\nA proposito, la ⟦Smokey's Special Compound=Miscela Speciale di Smokey⟧ è piuttosto... instabile.", "Mentre raccoglievi il materiale, ho fatto segnare ad alcuni dei miei gli edifici del Flagello da demolire.\n\nEcco il piano: ti darò dieci candelotti della mia miscela speciale. Li porterai a ⟦Plaguewood=Malaselva⟧ e li piazzerai dentro le strutture del Flagello che ho fatto marcare per la detonazione.\n\n<Smokey schiocca le dita.>\n\nBing! Facile come bere un bicchier d'acqua.", "Mi è avanzato del materiale per fare qualche altro candelotto di miscela speciale. Fa' sapere al vecchio Smokey se te ne servono altri.", "Sei molto più scur<o/a> di come ti ricordavo. Hai proprio quell'aria; l'aria di chi dice: 'Sono <stato/stata> <carbonizzato/carbonizzata> da una bomba ad alto potenziale.'\n\n<Smokey ride.>\n\nComunque! Ecco la tua parte del bottino. Ci ho aggiunto un piccolo extra per lenire le ustioni.", 0x10218999, 0x3e0f9596, 0x287b84cb, 0x193414ea, 0x4b93f9f8, "....." },
  [6042] = { "Le piccole seccature della non-vita", "Uccidi 20 Noxious Plaguebat e 10 Monstrous Plaguebat. Quando hai finito, torna da ⟦Nathanos Blightcaller=Nathanos Selvamorta⟧.", "Non puoi fare due passi fuori da questa fattoria senza imbatterti in uno di quei pipistrelli molesti. Voglio poter portare fuori i segugi a massacrare il Flagello senza essere assalito da quei dannati, sudici pipistrelli. Ovviamente ho di meglio da fare con il mio tempo che uccidere pipistrelli senza pensare, giorno dopo giorno. Tu, invece, no.\n\nCosa? Il tuo addestramento? Questo è il tuo addestramento! Ora levati dalla mia vista e non tornare finché non avrai ucciso un bel po' di quei demoni alati. Non deludermi.", "Poteva andarti peggio. Avrei potuto farti raccogliere guano di pipistrello.\n\n<Nathanos ti fissa, pensieroso.>\n\nUhm... Ehi! Aspetta un attimo. Dove vai?", "È incredibile cosa si riesca a ottenere con un po' di collera e di furia.", 0x7e356812, 0x6dc14c7b, 0x73cb40be, 0xfdc24c18, 0xc1f870dd, "....." },
  [6061] = { "Addomesticare la bestia", "Usa il ⟦Taming Rod=Bastone per Addomesticare⟧ per domare un ⟦Adult Plainstrider=Zampalunga delle Pianure Adulto⟧. Metti alla prova le tue abilità, poi riporta il ⟦Taming Rod=Bastone per Addomesticare⟧ a ⟦Yaw Sharpmane=Yaw Chioma Rasa⟧ nel ⟦Bloodhoof Village=Villaggio di Zoccolo Sanguinario⟧.", "Per un tauren è importante seguire le tradizioni dei nostri antenati combattendo creature possenti. Sconfiggendo queste creature possiamo accoglierne gli spiriti, e questo ci avvicina alla Madre Terra.\n\nAllo stesso modo, addomesticare una bestia che combatta al nostro fianco ci aiuta a diventare un tutt'uno con la natura che ci circonda. Col tempo imparerai ad addomesticare una bestia a tua scelta. Ma tutto richiede pratica, e hai molto da imparare. Comincia prendendo questo Bastone per Addomesticare: devi addomesticare un Adult Plainstrider.", "Metti alla prova le tue abilità, {name}. Addomestica l'Adult Plainstrider.", "La Madre Terra mi ha mandato dei segni: hai fatto un buon lavoro.", 0xecd97a9a, 0x7e3b8d01, 0x02e5038d, 0xaa8943a4, 0xe57154b4, "....." },
  [6062] = { "Addomesticare la bestia", "Usa il ⟦Taming Rod=Bastone per Addomesticare⟧ per domare un ⟦Dire Mottled Boar=Cinghiale Chiazzato Feroce⟧. Metti alla prova le tue abilità, poi riporta il ⟦Taming Rod=Bastone per Addomesticare⟧ a Thotar a ⟦Razor Hill=Tranciacolle⟧.", "Saper imporre la propria autorità sulla natura è un'abilità ammirevole. Come <cacciatore/cacciatrice>, devi sforzarti di imparare a usare la forza e il potere insiti in qualsiasi creatura tu scelga.\n\nOttenere il controllo di un animale non è un'impresa facile; è un compito da affrontare con grande determinazione.\n\nCome primo incarico, prendi questo Bastone per Addomesticare e usalo per addomesticare un Dire Mottled Boar. Ne troverai parecchi vicino a ⟦Razor Hill=Tranciacolle⟧. Metti alla prova le tue abilità in battaglia con il cinghiale al tuo fianco, poi torna da me.", "Buona fortuna, giovane <cacciatore/cacciatrice>.", "Hai fatto un buon lavoro, {name}. Credo che tu sia <pronto/pronta> per il prossimo compito.", 0xecd97a9a, 0xbdba9086, 0x62c476e9, 0xd07d6bc7, 0xac1c2d65, "....." },
  [6063] = { "Addomesticare la bestia", "Usa il ⟦Taming Rod=Bastone per Addomesticare⟧ per domare un ⟦Webwood Lurker=Ragno Guardingo Telalegno⟧. Metti alla prova le tue abilità, poi riporta il ⟦Taming Rod=Bastone per Addomesticare⟧ a Dazalar a Dolanaar.", "Come <cacciatore/cacciatrice>, è importante ricordare la responsabilità che tieni tra le mani. La natura non è un potere che si possa piegare ai nostri desideri; va rispettata e riconosciuta come qualcosa di più forte della tua stessa esistenza.\n\n{name}, devi dimostrare di averlo compreso prima di ottenere la capacità di addomesticare un animale come tuo compagno.\n\nIl tuo primo compito è prendere questo Bastone per Addomesticare. Con esso potrai addomesticare un Webwood Lurker. Addomesticalo e metti alla prova le tue abilità di <cacciatore/cacciatrice>.", "Imparerai, {name}, e un giorno sarai <un/una> grande <cacciatore/cacciatrice>.", "Eccellente, {name}! Impari davvero in fretta.", 0xecd97a9a, 0x72db5042, 0x39ad25e9, 0x407acae4, 0x7f1a8496, "....." },
  [6064] = { "Addomesticare la bestia", "Usa il ⟦Taming Rod=Bastone per Addomesticare⟧ per domare un ⟦Large Crag Boar=Grande Cinghiale delle Rupi⟧. Metti alla prova le tue abilità, poi riporta il ⟦Taming Rod=Bastone per Addomesticare⟧ a ⟦Grif Wildheart=Grif Cuorselvaggio⟧ a Kharanos.", "Salve, <ragazzo/ragazza>! Allora, vorresti sapere come avere un famiglio tutto tuo?\n\nBe', cominciamo. Non c'è niente di più importante dell'equipaggiamento quando si va a caccia, ma del mio nuovo ⟦Shrapnel Blaster=Fulminatore a Schegge⟧ possiamo parlare un'altra volta. Per ora concentriamoci su qualcosa che di sicuro t'interessa parecchio: un famiglio!\n\nIl modo migliore per imparare è provare diverse creature come compagni e vedere cosa ti piace. Quindi trova un Large Crag Boar e usa il Bastone per Addomesticare per domarlo.", "Non preoccuparti, <ragazzo/ragazza>! Potrai provarne qualcuno prima di doverne scegliere uno solo.", "Lo so, lo so: ti stai chiedendo cosa viene dopo, eh?!", 0xecd97a9a, 0x19250c04, 0x4bb3619f, 0x2a062314, 0x7fe27a35, ".....", nil, nil, 0x1065c71d, nil, nil },
  [6065] = { "La via del cacciatore", "Parla con ⟦Yaw Sharpmane=Yaw Chioma Rasa⟧ nel ⟦Bloodhoof Village=Villaggio di Zoccolo Sanguinario⟧.", "Salve, giovane <cacciatore/cacciatrice>. Mi sembri abbastanza abile da gestire una bestia e addestrarla come tua compagna.\n\nDevi andare da ⟦Yaw Sharpmane=Yaw Chioma Rasa⟧ al ⟦Bloodhoof Village=Villaggio di Zoccolo Sanguinario⟧. Può avviarti sulla strada per ottenere un famiglio tutto tuo.", nil, "Sì, credo proprio che tu sia <pronto/pronta>...", 0xe59cef47, 0x44416cc1, 0xcdcddc29, nil, 0x97654cb4, "...m." },
  [6066] = { "La via del cacciatore", "Parla con ⟦Yaw Sharpmane=Yaw Chioma Rasa⟧ nel ⟦Bloodhoof Village=Villaggio di Zoccolo Sanguinario⟧.", "Salve, giovane <cacciatore/cacciatrice>. Mi sembri abbastanza abile da gestire una bestia e addestrarla come tua compagna.\n\nDevi andare da ⟦Yaw Sharpmane=Yaw Chioma Rasa⟧ al ⟦Bloodhoof Village=Villaggio di Zoccolo Sanguinario⟧. Può avviarti sulla strada per ottenere un famiglio tutto tuo.", nil, "Sì, credo proprio che tu sia <pronto/pronta>...", 0xe59cef47, 0x44416cc1, 0xcdcddc29, nil, 0x97654cb4, "...m." },
  [6067] = { "La via del cacciatore", "Parla con ⟦Yaw Sharpmane=Yaw Chioma Rasa⟧ nel ⟦Bloodhoof Village=Villaggio di Zoccolo Sanguinario⟧.", "Salve, giovane <cacciatore/cacciatrice>. Mi sembri abbastanza abile da gestire una bestia e addestrarla come tua compagna.\n\nDevi andare da ⟦Yaw Sharpmane=Yaw Chioma Rasa⟧ al ⟦Bloodhoof Village=Villaggio di Zoccolo Sanguinario⟧. Può avviarti sulla strada per ottenere un famiglio tutto tuo.", nil, "Sì, credo proprio che tu sia <pronto/pronta>...", 0xe59cef47, 0x44416cc1, 0xcdcddc29, nil, 0x97654cb4, "...m." },
  [6068] = { "La via del cacciatore", "Parla con Thotar a ⟦Razor Hill=Tranciacolle⟧.", "Salve, giovane <cacciatore/cacciatrice>. Mi sembri abbastanza abile da gestire una bestia e addestrarla come tua compagna.\n\nDevi andare da Thotar a ⟦Razor Hill=Tranciacolle⟧. Può avviarti sulla strada per ottenere un famiglio tutto tuo.", nil, "Sì, è ora che tu cominci il tuo addestramento.", 0xe59cef47, 0xccc0cc0b, 0xa19701ce, nil, 0x2462bb57, "...m." },
  [6069] = { "La via del cacciatore", "Parla con Thotar a ⟦Razor Hill=Tranciacolle⟧.", "Salve, giovane <cacciatore/cacciatrice>. Mi sembri abbastanza abile da gestire una bestia e addestrarla come tua compagna.\n\nDevi andare da Thotar a ⟦Razor Hill=Tranciacolle⟧. Può avviarti sulla strada per ottenere un famiglio tutto tuo.", nil, "Sì, credo che tu sia <pronto/pronta> per essere <addestrato/addestrata>...", 0xe59cef47, 0xccc0cc0b, 0xa19701ce, nil, 0x136d5bec, "...m." },
  [6070] = { "La via del cacciatore", "Parla con Thotar a ⟦Razor Hill=Tranciacolle⟧.", "Salve, giovane <cacciatore/cacciatrice>. Mi sembri abbastanza abile da gestire una bestia e addestrarla come tua compagna.\n\nDevi andare da Thotar a ⟦Razor Hill=Tranciacolle⟧. Può avviarti sulla strada per ottenere un famiglio tutto tuo.", nil, "Sì, è ora che tu cominci il tuo addestramento.", 0xe59cef47, 0xccc0cc0b, 0xa19701ce, nil, 0x2462bb57, "...m." },
  [6071] = { "La via del cacciatore", "Parla con Dazalar a Dolanaar.", "Salve, giovane <cacciatore/cacciatrice>. Mi sembri abbastanza abile da gestire una bestia e addestrarla come tua compagna.\n\nDevi andare da Dazalar a Dolanaar. Può avviarti sulla strada per ottenere un famiglio tutto tuo.", nil, "Sì, è il momento, {class}.", 0xe59cef47, 0xacb77771, 0x57c4b6af, nil, 0xca92f25f, "...m." },
  [6072] = { "La via del cacciatore", "Parla con Dazalar a Dolanaar.", "Salve, giovane <cacciatore/cacciatrice>. Mi sembri abbastanza abile da gestire una bestia e addestrarla come tua compagna.\n\nDevi andare da Dazalar a Dolanaar. Può avviarti sulla strada per ottenere un famiglio tutto tuo.", nil, "Sì, credo che sia il momento...", 0xe59cef47, 0xacb77771, 0x57c4b6af, nil, 0x467a6a72, "...m." },
  [6073] = { "La via del cacciatore", "Parla con Dazalar a Dolanaar.", "Salve, giovane <cacciatore/cacciatrice>. Mi sembri abbastanza abile da gestire una bestia e addestrarla come tua compagna.\n\nDevi andare da Dazalar a Dolanaar. Può avviarti sulla strada per ottenere un famiglio tutto tuo.", nil, "Sì, è il momento, {class}.", 0xe59cef47, 0xacb77771, 0x57c4b6af, nil, 0xca92f25f, "...m." },
  [6074] = { "La via del cacciatore", "Parla con ⟦Grif Wildheart=Grif Cuorselvaggio⟧ a Kharanos.", "Salve, giovane <cacciatore/cacciatrice>. Mi sembri abbastanza abile da gestire una bestia e addestrarla come tua compagna.\n\nDevi andare da ⟦Grif Wildheart=Grif Cuorselvaggio⟧ a Kharanos. Può metterti sulla strada per ottenere un famiglio tutto tuo.", nil, "Sì, credo proprio che anche tu sia pront<o/a>...", 0xe59cef47, 0x7378e497, 0x892ec4fe, nil, 0xc84c7dad, "...m." },
  [6075] = { "La via del cacciatore", "Parla con ⟦Grif Wildheart=Grif Cuorselvaggio⟧ a Kharanos.", "Salve, giovane <cacciatore/cacciatrice>. Mi sembri abbastanza abile da gestire una bestia e addestrarla come tua compagna.\n\nDevi andare da ⟦Grif Wildheart=Grif Cuorselvaggio⟧ a Kharanos. Può metterti sulla strada per ottenere un famiglio tutto tuo.", nil, "Sì, credo proprio che anche tu sia pront<o/a>...", 0xe59cef47, 0x7378e497, 0x892ec4fe, nil, 0xc84c7dad, "...m." },
  [6076] = { "La via del cacciatore", "Parla con ⟦Grif Wildheart=Grif Cuorselvaggio⟧ a Kharanos.", "Salve, giovane <cacciatore/cacciatrice>. Mi sembri abbastanza abile da gestire una bestia e addestrarla come tua compagna.\n\nDevi andare da ⟦Grif Wildheart=Grif Cuorselvaggio⟧ a Kharanos. Può metterti sulla strada per ottenere un famiglio tutto tuo.", nil, "Sì, credo proprio che anche tu sia pront<o/a>...", 0xe59cef47, 0x7378e497, 0x892ec4fe, nil, 0xc84c7dad, "...m." },
  [6081] = { "Addestrare la bestia", "Parla con ⟦Ormak Grimshot=Ormak Colpotetro⟧ a Orgrimmar.", "Ora hai il potere di addomesticare un famiglio, ma devi anche acquisire le abilità per addestrarlo.\n\nRecati a Orgrimmar. Lì dovrai parlare con uno dei nostri cacciatori più venerati, ⟦Ormak Grimshot=Ormak Colpotetro⟧. Ti darà la capacità di addestrare il tuo nuovo famiglio. Lo troverai vicino alla Hall of the Brave.\n\nBuona fortuna, {name}.", nil, "Vedo che sei <un/una> giovane <cacciatore/cacciatrice>. Sì, ti concederò le abilità necessarie per addestrare e guidare il tuo famiglio. Non solo potrai insegnargli nuove abilità, ma ora potrai anche nutrirlo e rianimarlo, se dovesse cadere in battaglia.\n\nOra va', <cacciatore/cacciatrice>. Ci parleremo di nuovo più avanti.", 0xdbeedc0e, 0x2fb3c65d, 0x4f2112ec, nil, 0x455cd3ee, "...m." },
  [6082] = { "Addomesticare la bestia", "Addomestica uno ⟦Scorpid=Scorpide⟧, l'⟦Armored Scorpid=Scorpide Corazzato⟧, con il ⟦Taming Rod=Bastone per Addomesticare⟧. Metti in pratica le tue abilità, poi torna da Thotar a ⟦Razor Hill=Tranciacolle⟧.", "L'ultima creatura che devi addomesticare è una che dovresti sforzarti di emulare: l'Armored Scorpid. Colpisce in modo rapido e sicuro; controllare una forza come questa è il tuo destino di <cacciatore/cacciatrice>.\n\nAl tuo ritorno ti conferirò le abilità necessarie per addomesticare un animale a tua scelta; quella creatura sarà ai tuoi ordini. Sotto il tuo controllo, il famiglio acquisirà esperienza insieme a te. Ti mostrerò anche come richiamarlo e congedarlo a tuo piacimento.", "Sei riuscit<o/a> ad addomesticare lo scorpide?", "Hai imparato tutto ciò che posso insegnarti, {name}. È tempo che tu metta a frutto ciò che hai imparato qui e scelga un famiglio tutto tuo.\n\nEcco a te, {name}. Ora ti darò il potere di addomesticare una bestia, e di richiamarla e congedarla come meglio credi. Usa le tue nuove abilità con orgoglio: te le sei guadagnate.", 0xecd97a9a, 0x2768b0fc, 0x861877c1, 0x5354bf2d, 0xf50c040e, "....." },
  [6083] = { "Addomesticare la bestia", "Addomestica un ⟦Surf Crawler=Crostaceo delle Onde⟧ con il ⟦Taming Rod=Bastone per Addomesticare⟧. Metti in pratica le tue abilità, poi riporta il ⟦Taming Rod=Bastone per Addomesticare⟧ a Thotar a ⟦Razor Hill=Tranciacolle⟧.", "Il vantaggio che un famiglio ti offre contro i tuoi rivali è ben noto, {name}. Quando ottieni il controllo su un'altra creatura, aggiungi forza alla tua. Il tuo famiglio deve diventare un'estensione di te stess<o/a>.\n\nIl prossimo compito ti chiede di lasciare la terraferma: troverai la prossima creatura nelle acque al largo della costa. Di fronte al ⟦Sen'jin Village=Villaggio di Sen'jin⟧, vicino alle ⟦Echo Isles=Isole dell'Eco⟧, cerca un granchio vivace chiamato Surf Crawler. Usa il Bastone per Addomesticare per domarlo, poi metti in pratica le tue abilità.", "Devi fare pratica per acquisire le abilità necessarie a controllare bene il tuo famiglio. Hai addomesticato un Surf Crawler?", "Impari in fretta, {name}. Hai fatto un buon lavoro.", 0xecd97a9a, 0x79ae328f, 0x2fe7f794, 0x317634b5, 0x65d417ae, "....." },
  [6084] = { "Addomesticare la bestia", "Addomestica uno ⟦Snow Leopard=Leopardo delle Nevi⟧ con il ⟦Taming Rod=Bastone per Addomesticare⟧. Metti in pratica le tue abilità, poi torna da ⟦Grif Wildheart=Grif Cuorselvaggio⟧ a Kharanos.", "Quei Crag Boar son belli robusti; magari vorresti qualcosa con un po' più di finezza? Va bene, allora, ho proprio quel che fa per te. A sud-est di qui troverai dei grossi felini bianchi chiamati Snow Leopard. Proprio come un fucile intagliato con eleganza, dietro il loro bell'aspetto si nasconde un combattente potente, capace di fare danni enormi. Vedrai che sono molto più agili e svelti del cinghiale che hai addomesticato.\n\nPrendi questo Bastone per Addomesticare e vedi come ti trovi con lo Snow Leopard.", "Che ne pensi dello Snow Leopard, {name}?", "Quando sentirò che hai imparato abbastanza, ti concederò la capacità di scegliere qualsiasi famiglio tu preferisca.", 0xecd97a9a, 0x71c04a53, 0x18410c9d, 0x00a7c273, 0xa900ecfd, "....." },
  [6085] = { "Addomesticare la bestia", "Addomestica un ⟦Ice Claw Bear=Orso dalle Zampe di Ghiaccio⟧ con il ⟦Taming Rod=Bastone per Addomesticare⟧. Metti in pratica le tue abilità, poi riporta il ⟦Taming Rod=Bastone per Addomesticare⟧ a ⟦Grif Wildheart=Grif Cuorselvaggio⟧ a Kharanos.", "Forse ti piacerebbe una creatura che ha poco più della forza bruta. L'Ice Claw Bear è un compagno eccellente per chi è alle prime armi come te, e lo trovi a est di Kharanos. Ecco il Bastone per Addomesticare; prova questo animale come famiglio e vedi se ti piace!\n\nQuando torni, ti darò le abilità che ti servono per addomesticare un animale a tua scelta; quella creatura affronterà le sfide che affronti tu e acquisirà esperienza insieme a te. Ti mostrerò anche come richiamarlo e congedarlo come ti pare.", "Hai già addomesticato l'Ice Claw Bear?", "Ecco a te, {name}. Ora ti darò il potere di addomesticare una bestia, e di richiamarla e congedarla come ti pare.\n\nTrovati un famiglio buono e leale, e goditi la caccia!", 0xecd97a9a, 0xe2aae2d4, 0x732759ee, 0x687f27e9, 0x427d0b77, "....." },
  [6086] = { "Addestrare la bestia", "Parla con ⟦Belia Thundergranite=Belia Tuonabestie⟧ a ⟦Ironforge=Forgiardente⟧.", "{name}, ora hai il potere di addomesticare un famiglio, ma devi anche imparare ad addestrarlo.\n\nVa' a ⟦Ironforge=Forgiardente⟧ e cerca il Salone delle Armi. Lì devi parlare con una delle nostre addestratrici di animali più stimate, ⟦Belia Thundergranite=Belia Tuonabestie⟧. Ti darà il potere di addestrare il tuo nuovo famiglio, quindi muoviti, <ragazzo/ragazza>!\n\nBelia è una tipa alla mano; non avrai problemi a guadagnarti la sua approvazione. Buona fortuna, {name}.", nil, "Una nuova recluta, eh? Vedo che sei sulla buona strada per diventare <un/una> grande {class}.\n\nSì, posso conferirti le abilità necessarie per addestrare e guidare il tuo famiglio. Non solo potrai insegnargli nuove abilità, ma ora potrai anche nutrirlo e rianimarlo, se dovesse cadere in battaglia.\n\nRicorda che il segreto per ottenere il massimo dal tuo nuovo famiglio è rispettarlo e trattarlo bene. In cambio, il tuo famiglio sarà il tuo amico più leale.", 0xdbeedc0e, 0x4c05bef3, 0x77988ad7, nil, 0x760bb7bd, "...m.", nil, nil, 0xf137678c, nil, nil },
  [6087] = { "Addomesticare la bestia", "Addomestica un ⟦Prairie Stalker=Inseguitore delle Praterie⟧ con il ⟦Taming Rod=Bastone per Addomesticare⟧. Metti in pratica le tue abilità, poi riporta il ⟦Taming Rod=Bastone per Addomesticare⟧ a ⟦Yaw Sharpmane=Yaw Chioma Rasa⟧ nel ⟦Bloodhoof Village=Villaggio di Zoccolo Sanguinario⟧.", "Hai uno spirito ardente, <cacciatore/cacciatrice>, sempre pronto alla prossima sfida.\n\nIl tuo prossimo compito è conquistare la compagnia di un lupo noto come Prairie Stalker. Questa creatura è rapida e impavida; prendendo questa bestia come famiglio, dovrai fare tue anche queste qualità.\n\nIn battaglia imparerai come tu e il tuo famiglio diventerete una squadra. Alla fine dovrete agire come uno solo, muscolo con muscolo.\n\nEcco il Bastone per Addomesticare, {name}. Addomestica un Prairie Stalker e metti in pratica le tue abilità.", "Hai trovato un Prairie Stalker?", "Sì... La Madre Terra ritiene che tu sia pront<o/a> per la prossima lezione.", 0xecd97a9a, 0x4c6a673d, 0xcbcfeb92, 0xf06164c3, 0x0370a830, "....." },
  [6088] = { "Addomesticare la bestia", "Addomestica uno Swoop con il ⟦Taming Rod=Bastone per Addomesticare⟧. Metti in pratica le tue abilità, poi riporta il ⟦Taming Rod=Bastone per Addomesticare⟧ a ⟦Yaw Sharpmane=Yaw Chioma Rasa⟧ nel ⟦Bloodhoof Village=Villaggio di Zoccolo Sanguinario⟧.", "L'ultimo compito che ho per te richiede di addomesticare una creatura che abita il cielo. Lo Swoop è un avversario difficile, ma come alleato ti darà i suoi attacchi affilati e la sua presenza minacciosa.\n\nPer volere della Madre Terra, al tuo ritorno ti conferirò le abilità necessarie per addomesticare un animale a tua scelta come compagno; questa creatura affronterà le sfide che affronti tu e acquisirà esperienza insieme a te. Ti mostrerò anche come richiamarlo e congedarlo a tuo piacimento.", "Presto sarai pront<o/a>, {name}.", "Hai imparato tutto ciò che posso insegnarti, {name}. Che le benedizioni della Madre Terra ti guidino nella scelta di un famiglio.\n\nEcco a te, {name}. Ora ti darò il potere di addomesticare una bestia, e di richiamarla e congedarla come meglio credi. Usa le tue nuove abilità con orgoglio e onora la Madre Terra.", 0xecd97a9a, 0x64c2eb6a, 0x3d7058f9, 0x3bda1794, 0x834b33ff, "....." },
  [6089] = { "Addestrare la bestia", "Parla con ⟦Holt Thunderhorn=Holt Corno Tonante⟧ sull'⟦Hunter Rise=Altura dei Cacciatori⟧ a ⟦Thunder Bluff=Picco del Tuono⟧.", "Ora hai il potere di addomesticare un famiglio, ma devi anche acquisire le abilità per addestrarlo.\n\nRecati a ⟦Thunder Bluff=Picco del Tuono⟧. Lì dovrai parlare con uno dei nostri cacciatori più venerati, ⟦Holt Thunderhorn=Holt Corno Tonante⟧. Se ti riterrà degn<o/a>, ti darà la capacità di addestrare il tuo nuovo famiglio.\n\nHolt ha sconfitto le bestie più potenti e temute di Azeroth, e comanda molte creature possenti. Il suo legame con la Madre Terra è forte, e puoi imparare molto da lui. Buona fortuna, {name}.", nil, "Vedo che sei <un/una> giovane {class}. Sì, posso conferirti le abilità necessarie per addestrare e guidare il tuo famiglio. Non solo potrai insegnargli nuove abilità, ma ora potrai anche nutrirlo e rianimarlo, se dovesse cadere in battaglia.\n\nOra va'. Che la Madre Terra ti guidi sul tuo cammino. Ci parleremo di nuovo più avanti.", 0xdbeedc0e, 0x9f1dae7e, 0xc78eab1d, nil, 0x104e785e, "...m." },
  [6101] = { "Addomesticare la bestia", "Addomestica un ⟦Nightsaber Stalker=Fiera della Notte Inseguitrice⟧ con il ⟦Taming Rod=Bastone per Addomesticare⟧. Metti in pratica le tue abilità, poi riporta il ⟦Taming Rod=Bastone per Addomesticare⟧ a Dazalar a Dolanaar.", "La varietà della natura è qualcosa su cui si può contare, {name}. È prevedibile nel senso che non resta mai uguale: cambia sempre.\n\nI compiti che ti affiderò ti aiuteranno a vedere e apprezzare le enormi differenze tra le creature che potresti scegliere come compagne.\n\nPrendi questo Bastone per Addomesticare e usalo per addomesticare un Nightsaber Stalker, che trovi a sud. Metti in pratica le tue abilità di <cacciatore/cacciatrice>. Allora inizierai a comprendere le somiglianze e le differenze della natura.", "Comprendere l'equilibrio tra la natura e se stessi è uno stile di vita per ogni Elfo della Notte.", "Vedo il tuo impegno, e vedo che hai compreso ciò che ti ho insegnato, {name}.", 0xecd97a9a, 0xd54ea322, 0x4cf39634, 0x2bb052d9, 0xe3639023, "....." },
  [6102] = { "Addomesticare la bestia", "Addomestica uno ⟦Strigid Screecher=Strigido Stridente⟧ con il ⟦Taming Rod=Bastone per Addomesticare⟧. Metti in pratica le tue abilità, poi riporta il ⟦Taming Rod=Bastone per Addomesticare⟧ a Dazalar a Dolanaar.", "Hai addomesticato due creature che abitano la terra; ora devi addomesticarne una che solca i cieli. Usa il Bastone per Addomesticare per domare uno Strigid Screecher, che trovi a ovest di qui. Metti in pratica le tue abilità con questo possente gufo al tuo fianco.\n\nAl tuo ritorno ti conferirò le abilità necessarie per addomesticare un animale a tua scelta come compagno; questa creatura affronterà le sfide che affronti tu e acquisirà esperienza insieme a te. Ti mostrerò anche come richiamarlo e congedarlo a tuo piacimento.", "Sono fiero dei tuoi successi, {name}. Hai portato a termine l'ultimo compito che ti ho affidato?", "Hai imparato tutto ciò che posso insegnarti, {name}. Permettimi di darti un ultimo consiglio: scegli con giudizio il tuo primo famiglio. Sceglierai una creatura della terra, dell'acqua o del cielo? Qualunque sia, senza dubbio il tuo famiglio starà con te per molto tempo.\n\nEcco a te, {name}. Ora ti darò il potere di addomesticare una bestia, e di richiamarla e congedarla come meglio credi. Usa le tue nuove abilità con orgoglio: te le sei guadagnate.", 0xecd97a9a, 0xe53bb451, 0x3445b668, 0xc9470946, 0xdeb475c1, "....." },
  [6103] = { "Addestrare la bestia", "Parla con Jocaste nell'⟦Cenarion Enclave=Enclave Cenariana⟧, a Darnassus.", "Ora hai il potere di addomesticare un famiglio, ma devi anche acquisire le abilità per addestrarlo.\n\nRecati a Darnassus. Lì dovrai parlare con una delle nostre cacciatrici più venerate, Jocaste. Ti darà la capacità di addestrare il tuo nuovo famiglio, quindi affrettati.\n\nAnche se Jocaste può sembrare severa, è sempre lieta di vedere un altro cacciatore salire di grado. Trattala con rispetto e lei farà altrettanto. Buona fortuna, {name}.", nil, "Vedo che sei <un/una> <cacciatore/cacciatrice> alle prime armi. Sì, posso conferirti le abilità necessarie per addestrare e guidare il tuo famiglio. Non solo potrai insegnargli nuove abilità, ma ora potrai anche nutrirlo e rianimarlo, se dovesse cadere in battaglia.\n\nRicorda, {name}, rispetta sempre l'equilibrio e guarda con meraviglia la natura che ti circonda. Ora va'. Ci parleremo di nuovo più avanti.", 0xdbeedc0e, 0x6e901431, 0x3d135ae6, nil, 0xce7253c1, "...m." },
  [6121] = { "Nuove lezioni", "Va' a ⟦Moonglade=Radaluna⟧ e parla con ⟦Dendrite Starblaze=Dendrite Ardistella⟧ nel villaggio di ⟦Nighthaven=Nottequieta⟧.", "Ora sei pront<o/a> a conoscere i veleni e il potere che noi druidi abbiamo su di essi, {name}. Cenarius ci ha concesso la capacità di purificare anche i veleni più immondi con un semplice incantesimo. Questo dono non va preso alla leggera... e per assicurarmi che tu impari la lezione, lavorerai per contrastare gli effetti degli avvelenamenti come farebbe un profano.\n\nVa' a ⟦Moonglade=Radaluna⟧ e parla con ⟦Dendrite Starblaze=Dendrite Ardistella⟧; attende il tuo arrivo per cominciare la lezione.", nil, "Salute, giovane druid<o/a>, sono lieto di vederti pront<o/a> e desideros<o/a> di imparare a curare i veleni.\n\nMentre in passato la maggior parte dei druidi veniva sottoposta a prove prestabilite, il tuo lavoro non avrà niente del genere. Ad Auberdine c'è stata un'ondata di avvelenamenti tra gli animali, e il villaggio non è riuscito a curarli. Per questo un loro rappresentante ha chiesto aiuto a ⟦Moonglade=Radaluna⟧, e noi ti mandiamo laggiù ad aiutarli. Non è un'esercitazione: il lavoro che farai è del tutto reale. Tienilo a mente.", 0xe3814355, 0xb25e3d68, 0x738324f8, nil, 0xe3b1d128, "...m." },
  [6122] = { "La fonte principale", "Usa il ⟦Empty Cliffspring Falls Sampler=Campione delle Cascate di Altafonte Vuoto⟧ per prelevare un campione d'acqua all'imbocco della grotta vicino alle cascate.\n\nConsegna il ⟦Filled Cliffspring Falls Sampler=Campione delle Cascate di Altafonte Pieno⟧ ad ⟦Alanndarian Nightsong=Alanndarian Cantanotte⟧, ad Auberdine, a ⟦Darkshore=Rivafosca⟧.", "Le ⟦Cliffspring Falls=Cascate di Altafonte⟧, a ⟦Darkshore=Rivafosca⟧, sono la fonte principale di acqua potabile della regione, e ora sospetto che siano anche la fonte principale del veleno che colpisce la fauna locale, in particolare i cervi. Usa questo campionatore per prelevare un po' d'acqua all'imbocco della grotta; fa' attenzione, perché ora in una grotta vicino alle cascate vivono dei naga pericolosi.\n\nUna volta riempito, consegnalo ad ⟦Alanndarian Nightsong=Alanndarian Cantanotte⟧, ad Auberdine. È lei che ha chiesto il nostro aiuto, e lavorerai con lei per curare questo male.", "Ti manda il ⟦Cenarion Circle=Circolo Cenariano⟧ di ⟦Moonglade=Radaluna⟧? Magnifico! Qui abbiamo una vera crisi con quei poveri cervi, e siamo felici di ricevere tutto l'aiuto possibile.\n\nHai il campione d'acqua che ⟦Dendrite Starblaze=Dendrite Ardistella⟧ ha detto che avresti portato? Mi ha avvisata che ne avresti prelevato uno, così da poter lavorare insieme a una cura...", "Per Elune, quest'acqua è disgustosa! Non c'è da stupirsi che i cervi siano malati.\n\nQualcosa sta inquinando l'acqua e, di conseguenza, corrompe l'intera falda di Rivafosca. Si sono visti cervi malati in tutta la zona, e non solo vicino al fiume. Anche se quest'acqua è con ogni probabilità una delle fonti principali del male che si diffonde, qui c'è all'opera qualcos'altro.\n\nChe tu ci creda o no, quest'acqua ci aiuterà a preparare una cura. Mentre la studio, mi servono alcuni ingredienti per formulare la cura...", 0xfe91905d, 0xed0bc128, 0xe6b38f20, 0x7f300676, 0xc7a9f8eb, "....." },
  [6123] = { "Gli ingredienti della cura", "Porta 5 Earthroot e 12 Fungo Lunare ad ⟦Alanndarian Nightsong=Alanndarian Cantanotte⟧, ad Auberdine, perché possa preparare un balsamo curativo.", "L'acqua farà da base per il balsamo curativo che preparerò per i cervi. Per le proprietà curative mi serve un po' di Earthroot. Gli erboristi sanno come trovarla, quindi, se siamo sfortunati e tu non lo sei, dovrai trovarne uno che ci aiuti.\n\nInfine, per renderlo efficace, mi serve un po' di Lunar Fungus. Trovarne le fioriture è abbastanza facile: sono dappertutto nelle grotte appena a est di qui. Nelle grotte vivono dei lunagufi, e ultimamente sono irritabili, quindi fa' attenzione.", "Hai i reagenti che mi servono per preparare il balsamo? I cervi non migliorano da soli, quindi è meglio sbrigarsi ad aiutarli!", "Questo va bene, {name}, tanto che dovrebbe bastare a preparare diverse dosi di balsamo, almeno quante ne servono per cominciare a fare la differenza.\n\nPreparare una cura per i veleni a volte può essere molto difficile, perché spesso ognuno richiede un antidoto molto specifico per contrastarlo. Immagina di poter curare un veleno a piacimento senza doverti preoccupare degli ingredienti esatti dell'antidoto!\n\nOra lasciami mettere al lavoro!", 0xc0a4b4dc, 0x14a92d63, 0xd43adcc8, 0xd5399fb4, 0x0d585714, "....." },
  [6124] = { "Curare i malati", "Usa il ⟦Curative Animal Salve=Balsamo Curativo Animale⟧ su 10 ⟦Sickly Deer=Capriolo Malato⟧ sparsi per ⟦Darkshore=Rivafosca⟧: dovrebbe guarirli. I ⟦Sickly Deer=Capriolo Malato⟧ sono stati segnalati a partire da sud del ⟦Cliffspring River=Fiume Altafonte⟧, a nord di Auberdine, fino alla parte meridionale di ⟦Darkshore=Rivafosca⟧, dove comincia ⟦Ashenvale=Valtetra⟧.", "Con i reagenti che mi hai portato ho preparato abbastanza balsamo per dieci dosi, {name}. Mentre lavoro con il villaggio per prepararne ancora, vorrei che tu ci aiutassi a portarci avanti. In tutta ⟦Darkshore=Rivafosca⟧ ci sono cervi malati; usa il balsamo su di loro e guariscili dal loro male.\n\nSono sicura che Dendrite Starblaze, a ⟦Moonglade=Radaluna⟧, vorrà parlarti quando avrai finito. Ti prego, porta i ringraziamenti di Auberdine al ⟦Cenarion Circle=Circolo Cenariano⟧ laggiù... e lascia che ti ringrazi io stessa, di persona, per l'aiuto che ci hai dato!", "Hai portato a termine ciò che ti ha chiesto ⟦Alanndarian Nightsong=Alanndarian Cantanotte⟧ di Auberdine? Il tuo lavoro non è completo finché non lo farai.", "Hai fatto bene a curare i cervi malati di ⟦Darkshore=Rivafosca⟧; sono vittime inconsapevoli di una contaminazione e di una corruzione più grandi che si stanno diffondendo in tutta la terra. A Darnassus c'è chi sceglie di riconoscere questa minaccia... e c'è chi ignora i segni sempre più evidenti. Spero che tu non sia tra quelli che chiudono gli occhi davanti ai fatti, {name}.\n\nIn ogni caso, hai dimostrato il tuo valore come amic<o/a> della natura e del Circolo: prendi questo come simbolo.", 0x0116fddd, 0x20fba3fe, 0xbc2e713b, 0xb12ec810, 0x848c8bee, "....." },
  [6125] = { "Potere sul veleno", "Torna da ⟦Mathrengyl Bearwalker=Mathrengyl Domaorsi⟧, nell'⟦Cenarion Enclave=Enclave Cenariana⟧, a Darnassus.", "Hai imparato cosa significa curare un veleno senza il beneficio dell'aiuto spirituale. Ricorda ciò che gli altri devono sopportare nel combattere le afflizioni velenose, ora che stai per abbracciare il tuo nuovo potere sul veleno.\n\nOra dovresti tornare da ⟦Mathrengyl Bearwalker=Mathrengyl Domaorsi⟧, a Darnassus, {name}. Senza dubbio ha un incantesimo molto importante da insegnarti, ora che hai compreso la lezione che ti è stata impartita.\n\nAddio, giovane druid<o/a>. Ci parleremo ancora.", nil, "Bentornat<o/a>. Ho seguito i tuoi progressi in questa lezione da quando sei partit<o/a>, e devo ammettere che mi ha sorpreso sapere della situazione ad Auberdine. La faccenda merita ulteriori indagini, perché l'introduzione di simili veleni nell'ambiente turba profondamente l'equilibrio.\n\nHai mantenuto grazia e sangue freddo sotto pressione. Per questo, non trovo modo migliore per ricompensarti che con un potere permanente sul veleno. Usalo bene, {name}... usalo bene.", 0xfaefb521, 0x6562a80b, 0xe76f8205, nil, 0x02ded2c7, "...m.", nil, nil, 0xe5d51b88, nil, nil },
  [6126] = { "Nuove lezioni", "Va' a ⟦Moonglade=Radaluna⟧ e parla con ⟦Dendrite Starblaze=Dendrite Ardistella⟧ nel villaggio di ⟦Nighthaven=Nottequieta⟧.", "Ora sei pront<o/a> a conoscere i veleni e il potere che noi druidi abbiamo su di essi, {name}. Cenarius ci ha concesso la capacità di purificare anche i veleni più immondi con un semplice incantesimo. Questo dono non va preso alla leggera... e per assicurarmi che tu impari la lezione, lavorerai per contrastare gli effetti degli avvelenamenti come farebbe un profano.\n\nVa' a ⟦Moonglade=Radaluna⟧ e parla con ⟦Dendrite Starblaze=Dendrite Ardistella⟧; attende il tuo arrivo per cominciare la lezione.", nil, "Salute, giovane druid<o/a>, sono lieto di vederti pront<o/a> e desideros<o/a> di imparare a curare i veleni.\n\nMentre in passato la maggior parte dei druidi veniva sottoposta a prove prestabilite, il tuo lavoro non avrà niente del genere. Al ⟦Crossroads=Crocevia⟧, nelle ⟦Barrens=Savane⟧, c'è stata un'ondata di avvelenamenti tra gli animali, e non riescono a tenerla sotto controllo. Qualcuno laggiù ha chiesto aiuto a ⟦Moonglade=Radaluna⟧, quindi ti mandiamo da loro ad aiutarli. Non è un'esercitazione: il lavoro che farai è del tutto reale. Tienilo a mente.", 0xe3814355, 0xb25e3d68, 0x738324f8, nil, 0x0d09f282, "...m." },
  [6127] = { "La fonte principale", "Usa il ⟦Empty Dreadmist Peak Sampler=Campione del Picco di Brumafunesta Vuoto⟧ per prelevare un campione d'acqua da una pozza in cima al picco.\n\nConsegna il ⟦Filled Dreadmist Peak Sampler=Campione del Picco di Brumafunesta Pieno⟧ a ⟦Tonga Runetotem=Tonga Totem Runico⟧, al ⟦Crossroads=Crocevia⟧, nelle ⟦Barrens=Savane⟧.", "Il ⟦Dreadmist Peak=Picco di Brumafunesta⟧, a nord-ovest del ⟦Crossroads=Crocevia⟧, è con ogni probabilità il primo candidato come origine del veleno che si sta diffondendo. Sulle sue cime ventose ci sono pozze d'acqua che influenzano il clima. Sospetto che ora l'acqua sia contaminata dalle ⟦Burning Blade=Lame Ardenti⟧, adoratrici dei demoni.\n\nUsa questo campionatore per prelevare l'acqua dalla pozza in cima al picco. Una volta riempito, consegnalo a ⟦Tonga Runetotem=Tonga Totem Runico⟧, al ⟦Crossroads=Crocevia⟧. È lui che ha chiesto il nostro aiuto, e lavorerai con lui per curare questo male.", "Ti manda il ⟦Cenarion Circle=Circolo Cenariano⟧ di ⟦Moonglade=Radaluna⟧, vero? È davvero provvidenziale per noi! I nostri sforzi per riportare l'equilibrio tra le gazzelle malate che vagano nella parte settentrionale delle ⟦Barrens=Savane⟧ sono in stallo; siamo felici di ricevere tutto l'aiuto possibile.\n\nHai il campione d'acqua che ⟦Dendrite Starblaze=Dendrite Ardistella⟧ ha detto che avresti portato? Mi ha avvisato che ne avresti prelevato uno, così da poter lavorare insieme a una cura...", "Per i miei antenati, quest'acqua è disgustosa! Non c'è da stupirsi che le gazzelle siano malate.\n\nQualcosa sta inquinando l'acqua e, di conseguenza, comincia a devastare l'ecosistema della parte settentrionale delle ⟦Barrens=Savane⟧. Sono state avvistate gazzelle malate ovunque a nord della strada est-ovest qui vicino. Anche se quest'acqua è con ogni probabilità una delle fonti principali del male che si diffonde, qui c'è all'opera qualcos'altro.\n\nChe tu ci creda o no, quest'acqua ci aiuterà a preparare una cura. Mentre la studio, mi servono alcuni ingredienti per formulare la cura...", 0xfe91905d, 0xc7e4ec6f, 0x35e50bed, 0x7afc3fe5, 0xa5296c0c, "....." },
  [6128] = { "Gli ingredienti della cura", "Porta 5 Earthroot e 5 Corno di Kodo a ⟦Tonga Runetotem=Tonga Totem Runico⟧, al ⟦Crossroads=Crocevia⟧, perché possa preparare un balsamo curativo.", "L'acqua farà da base per il balsamo curativo che preparerò per le gazzelle. Per le proprietà curative mi serve un po' di Earthroot. Gli erboristi sanno come trovarla, quindi, se non conosci quest'arte, dovrai trovarne uno che ci aiuti.\n\nInfine, per renderlo efficace, mi servono corna di kodo: semplici schegge e frammenti non basteranno. I kodo che sei in grado di affrontare vagano nella parte settentrionale delle ⟦Barrens=Savane⟧; abbattine qualcuno per il bene superiore dell'equilibrio, {name}, e portami le corna.", "Hai i reagenti che mi servono per preparare il balsamo? Le gazzelle non migliorano da sole, quindi non dobbiamo indugiare nei nostri sforzi per salvarle!", "Questo va bene, {name}, tanto che dovrebbe bastare a preparare diverse dosi di balsamo, almeno quante ne servono per cominciare a fare la differenza.\n\nPreparare una cura per i veleni a volte può essere molto difficile, perché spesso ognuno richiede un antidoto molto specifico per contrastarlo. Immagina di poter curare un veleno a piacimento senza doverti preoccupare degli ingredienti esatti dell'antidoto!\n\nOra lasciami mettere al lavoro!", 0xc0a4b4dc, 0xc7410c2b, 0x8faf0ffa, 0x38c77760, 0x0d585714, "....." },
  [6129] = { "Curare i malati", "Usa il ⟦Curative Animal Salve=Balsamo Curativo Animale⟧ su 10 Sickly Gazelle sparse per la parte settentrionale delle ⟦Barrens=Savane⟧: dovrebbe guarirle. Le Sickly Gazelle sono state segnalate a nord della strada est-ovest che attraversa il ⟦Crossroads=Crocevia⟧.", "Sono riuscito a preparare abbastanza balsamo per dieci dosi di cura, {name}. Mentre lavoro con le autorità locali per prepararne ancora, vorrei che tu ci aiutassi a portarci avanti. In tutta la parte settentrionale delle ⟦Barrens=Savane⟧ ci sono gazzelle malate; usa il balsamo su di loro e guariscile dal loro male.\n\nSono sicuro che Dendrite Starblaze, a ⟦Moonglade=Radaluna⟧, vorrà parlarti quando avrai finito. Ti prego, porta i nostri ringraziamenti al ⟦Cenarion Circle=Circolo Cenariano⟧ laggiù... e lascia che ti ringrazi io stesso, di persona, per l'aiuto che ci hai dato!", "Hai portato a termine ciò che ti ha chiesto ⟦Tonga Runetotem=Tonga Totem Runico⟧ al ⟦Crossroads=Crocevia⟧? Il tuo lavoro non è completo finché non lo farai.", "Hai fatto bene a curare le gazzelle malate delle ⟦Barrens=Savane⟧; sono vittime inconsapevoli di una contaminazione e di una corruzione più grandi che si stanno diffondendo in tutta la terra. Voi tauren siete i più desiderosi di comprendere le vie di Cenarius; tu, come i tuoi anziani a ⟦Thunder Bluff=Picco del Tuono⟧, dimostri che il bisogno di equilibrio trascende le barriere artificiali tra le razze.\n\n{name}, hai dimostrato il tuo valore come amic<o/a> della natura e del Circolo: prendi questo come simbolo.", 0x0116fddd, 0xeeed1d31, 0x6c76cb22, 0x8899d0db, 0x384368d9, "....." },
  [6130] = { "Potere sul veleno", "Torna da ⟦Turak Runetotem=Turak Totem Runico⟧, sull'⟦Elder Rise=Altura degli Anziani⟧, a ⟦Thunder Bluff=Picco del Tuono⟧.", "Hai imparato cosa significa curare un veleno senza il beneficio dell'aiuto spirituale. Ricorda ciò che gli altri devono sopportare nel combattere le afflizioni velenose, ora che stai per abbracciare il tuo nuovo potere sul veleno.\n\nOra dovresti tornare da ⟦Turak Runetotem=Turak Totem Runico⟧, a ⟦Thunder Bluff=Picco del Tuono⟧, {name}. Senza dubbio ha un incantesimo molto importante da insegnarti, ora che hai compreso la lezione che ti è stata impartita.\n\nAddio, giovane druid<o/a>. Ci parleremo ancora.", nil, "Bentornat<o/a>. Ho seguito i tuoi progressi in questa lezione da quando sei partit<o/a>, e devo ammettere che mi ha sorpreso sapere della situazione al ⟦Crossroads=Crocevia⟧. La faccenda merita ulteriori indagini, perché l'introduzione di simili veleni nell'ambiente turba profondamente l'equilibrio.\n\nHai mantenuto grazia e sangue freddo sotto pressione. Per questo, non trovo modo migliore per ricompensarti che con un potere permanente sul veleno. Usalo bene, {name}... usalo bene.", 0xfaefb521, 0xeb5d1d3a, 0x2d5f79f7, nil, 0x0b177411, "...m.", nil, nil, 0x2bc5137a, nil, nil },
  [6132] = { "Tirami fuori di qui!", "Scorta ⟦Melizza Brimbuzzle=Melizza Scoppiachiavi⟧, poi parla con ⟦Hornizz Brimbuzzle=Hornizz Scoppiachiavi⟧ al ⟦Kodo Graveyard=Cimitero dei Kodo⟧, a ⟦Desolace=Desolanda⟧.", "Tirami fuori di qui!\n\nSono salita alla ⟦Valley of Spears=Valle delle Lance⟧ per parlare con i Maraudon. Pensavo di poter fare qualche affaruccio con loro... ma non vogliono parlare! Credo che vogliano mangiarmi!\n\nTirami fuori di qui e mio fratello Hornizz ti pagherà alla grande! È al nostro accampamento vicino al Cimitero dei Kodo, a est.\n\nSbrighiamoci, {name}. Neanche due minuti fa ho sentito dei centauri parlare di andare a prendere legna per il pentolone...", "Hai visto mia sorella Melizza? Non sta mai ferma, e per questo si caccia sempre nei guai.", "Mia sorella Melizza aveva detto che saresti <venuto/venuta>. Grazie mille per averla tirata fuori dal pasticcio in cui si era cacciata; peccato che probabilmente si sia già cacciata in un altro!", 0x6d185bdb, 0x31688590, 0x4440fa0b, 0x7e758e1f, 0xc3f8b2ba, "....." },
  [6133] = { "L'ordine del signore dei ranger", "Raggiungi i confini settentrionali delle ⟦Eastern Plaguelands=Terre Infette Orientali⟧ e recupera il ⟦Quel'Thalas Registry=Registro di Quel'Thalas⟧. L'oggetto si trova da qualche parte nel Padiglione Quel'Lithien.\n\nDevi anche uccidere 8 Ranger, 8 Pathstrider e 8 Woodsman.", "Gli alti elfi del Padiglione Quel'Lithien possiedono una cosa che mi appartiene, {class}: un documento che descrive la mia vita da mortale.\n\nPrima che tu lo chieda: no, non hai assolutamente il diritto di conoscere queste informazioni. Fa' solo ciò che ti dico, verme: recupera il registro.\n\nE, imbecille, assicurati di lasciarti alle spalle quanto più conflitto e dolore possibile. Lasciali a soffrire...", "Non farmi aspettare, {class}.", "Confido che tu non abbia letto il registro. Nemmeno tu faresti qualcosa di così idiota...", 0x5fffe202, 0xa7bc315c, 0xc6a90b80, 0xd7dab34e, 0x114c9e8a, "....." },
  [6134] = { "Raccolta di Ghost-o-plasm", "Porta 8 Ghost-o-plasm e la ⟦Crate of Ghost Magnets=Cassa di Magneti Fantasma⟧ a ⟦Hornizz Brimbuzzle=Hornizz Scoppiachiavi⟧ a ⟦Desolace=Desolanda⟧.", "C'è una valle a sud-est, la ⟦Valley of Bones=Valle delle Ossa⟧, infestata dai fantasmi Magram. Fa paura, eh? Beh, pensa quanta paura fa ai Magram! Se catturassimo l'energia spettrale di quel posto, scommetto che varrebbe un bel po' per quei centauri.\n\nEcco, prendi questa Cassa di Magneti Fantasma. Se ne piazzi uno tra i due grandi scheletri nella valle, i Dead Goliaths, i fantasmi ci si raduneranno attorno. Allontanati, fai fuori i fantasmi e prendi il loro ghost-o-plasm: è quello che venderemo ai Magram.", "Dov'è il mio ghost-o-plasm, {name}?", "Eccolo! Pare che un po' ti sia finito addosso. Un po' viscido, eh?\n\nBeh, grazie mille per tutto il disturbo, {name}. Questa roba varrà una fortuna... se riesco a convincere i centauri di cosa si tratta!", 0x417173f4, 0x0fee26ad, 0x25e62823, 0x5e12b43b, 0x7fb9819e, "....." },
  [6135] = { "⟦Duskwing=Alascura⟧, quanto ti odio...", "Trova ⟦Duskwing=Alascura⟧ e uccidilo. Dal cadavere recupera una ⟦Patch of Duskwing's Fur=Pezza di Pelliccia di Alascura⟧ e portala a ⟦Nathanos Blightcaller=Nathanos Selvamorta⟧.\n\nSi dice che ⟦Duskwing=Alascura⟧ si aggiri per le campagne a nord della Cascina dei Marris.", "Finora hai portato a termine le missioni che ti ho assegnato, anche se non con la massima puntualità.\n\nSuppongo che tu ti senta <pronto/pronta> per una sfida. Sì... Sì, imbecille, forse sei <pronto/pronta> per una serie di missioni più impegnative.\n\nIl pipistrello demoniaco albino, ⟦Duskwing=Alascura⟧, si aggira per le campagne appena a nord di qui. Rintraccialo e distruggilo. Torna da me con un pezzo della sua pelliccia bianca e sarai ricompensat<o/a>.", "Non ti consiglierei di affrontare questa sfida da sol<o/a>, {class}.", "Ottimo lavoro, imbecille. Ricaverò da questa pelliccia qualcosa che potrai usare.", 0x9ac167a0, 0x957f29e6, 0x227e225a, 0x4d2de6ae, 0x34730165, "....." },
  [6136] = { "Il corpulento", "Trova ⟦Borelgore=Sangueboreo⟧ nelle lande settentrionali delle ⟦Eastern Plaguelands=Terre Infette Orientali⟧ e distruggilo. Torna da ⟦Nathanos Blightcaller=Nathanos Selvamorta⟧ quando avrai compiuto la missione.", "Oltre l'accampamento dell'⟦Argent Dawn=Alba d'Argento⟧ alla Cappella della Luce, a ovest di ⟦Northdale=Valnordia⟧, troverai il corpulento mostro larvale ⟦Borelgore=Sangueboreo⟧.\n\nHo perso interi reggimenti per colpa di quel mostro. La sua mole non conosce limiti! Più mangia, più il suo girovita cresce...\n\nAnche se non soffrirei affatto se la bestia ti divorasse, preferirei che a vincere fossi tu. Ti consiglio di farti aiutare da altri per questa missione. Si sa che ⟦Borelgore=Sangueboreo⟧ ha divorato piccoli battaglioni tanto stolti da attaccarlo.", "Ti ho detto di recente che ti odio?", "Continua così e potrei doverti promuovere da imbecille a deficiente mentale di prima classe.", 0x75acd1d0, 0x19dcc77a, 0x0c44002a, 0x6650e59d, 0xdde03616, "....." },
  [6141] = { "⟦Brother Anton=Fratello Anton⟧", "Parla con il fratello Anton a ⟦Desolace=Desolanda⟧.", "Il mio confratello, fratello Anton, ha sentito voci di un'infestazione di non morti nella lontana Kalimdor, in una terra chiamata ⟦Desolace=Desolanda⟧. Anton si è subito imbarcato per quel luogo, per cercare e distruggere la minaccia dei non morti!\n\nCerca persone con il coraggio e la determinazione per aiutarlo. Se il tuo cuore è sincero, parla con Anton. Si trova a ⟦Desolace=Desolanda⟧, nella città dell'⟦Alliance=Alleanza⟧ del ⟦Nijel's Point=Presidio di Nijel⟧.", nil, "Ho saputo che stanno arrivando aiuti da est. Sei tu la fonte di queste voci? Sei <venuto/venuta> qui per aiutare la Scarlet Brotherhood nella sua crociata?\n\nSe è così, ascolta bene...", 0x43a2f68d, 0x56ae9363, 0x614b91fc, nil, 0xdede434a, "...m." },
  [6142] = { "Esca di molluschi", "Trova 10 pezzi di ⟦Soft-shelled Clam Meat=Mollusco dal Guscio Molle⟧ e riportali a ⟦Mai'Lahii=Mai'lahii⟧ a ⟦Shadowprey Village=Predombra⟧.", "Hai l'aria di <un/una> <pescatore/pescatrice>, {class}! Adoro pescare: pesco da tutta la vita. L'esca migliore è la carne di mollusco dal guscio molle; i pesci proprio non resistono, capisci cosa intendo?\n\nA nord troverai una nave naufragata al largo della costa. Tutta la zona è piena di molluschi dal guscio molle. Se mi porti 10 pezzi di carne di mollusco dal guscio molle, ti darò qualcosa in cambio.", "Non vedo l'ora di andare a pescare con della carne fresca di mollusco dal guscio molle; mi hai portato i 10 pezzi che mi servono?", "Perfetto, amico, è proprio quello che il santone mi ha detto di fare per il mal di testa. Lui dice: «⟦Mai'Lahii=Mai'lahii⟧, va' a pescare. Ti farà sentire meglio»\n\nBe', mi sento già meglio, grazie amico!", 0x50517e58, 0x968616fc, 0x0f7c78d9, 0xa9eaf0ae, 0x430ca444, "....." },
  [6143] = { "Altri pesci da friggere", "Uccidi 7 ⟦Slitherblade Myrmidon=Mirmidone Lamasalmastra⟧, 7 ⟦Slitherblade Naga=Naga Lamasalmastra⟧ e 5 Slitherblade Sorceress, poi parla con Drulzegar a Predombra, in ⟦Desolace=Desolanda⟧.", "Forse l'hai sentito o forse no... io e la mia ciurma eravamo a pescare vicino all'⟦Ranazjar Isle=Isola di Ranazjar⟧, a nord della nave naufragata al largo della costa settentrionale. Ci pescavamo sempre; ora non faccio che pensare a come vendicare i miei compagni caduti.\n\nI naga ci hanno attaccati una mattina e hanno ucciso tutti tranne me.\n\nLa mia coscienza non regge il senso di colpa, {class}; ho bisogno che tu vada a friggere quei naga per me. Ne varrà la pena, te lo assicuro; pensi di potermi aiutare?", "Sento ancora le loro voci che gridavano aiuto quando i naga ci hanno scatenato addosso il caos. Se non avessi questo ginocchio malandato, verrei ad aiutarti a uccidere quei maledetti naga!\n\nDi solito li trovi in fondo alle barriere coralline, sotto la superficie... in agguato... a tramare...", "Per quanto sia dolce sentire che i naga sono stati sconfitti, il mio cuore si sente ancora vuoto. Per il resto della mia vita mi dedicherò a farli uccidere tutti.\n\nEcco, amico, la tua ricompensa come promesso. È poca cosa in confronto alla soddisfazione di sapere che i naga sono finiti fritti per l'odioso atto contro la mia ciurma.", 0xfc3e7576, 0x61ced3a6, 0x01c155be, 0xba7a3190, 0xdf51b5e5, "....." },
  [6144] = { "La chiamata al comando", "Raggiungi ⟦Undercity=Sepulcra⟧ e parla con Varimathras.", "L'ordine è arrivato, {class}. Varimathras in persona mi ha chiesto di rimandare a ⟦Undercity=Sepulcra⟧ i miei agenti più 'capaci' per un'operazione tattica estremamente delicata.\n\nPurtroppo i miei agenti più capaci sono stati uccisi più di tre anni fa. Al loro posto ho una collezione di plebaglia senza cervello.\n\n<Nathanos ti fissa con freddezza.>\n\nRaggiungi subito ⟦Undercity=Sepulcra⟧ e fai rapporto a Varimathras. Non farmi fare brutta figura, {class}!", nil, "Il Gran Crociato siede al sicuro nello Scarlet Bastion mentre le sue forze dilagano nelle tue terre, profanano i tuoi edifici e i tuoi monumenti e massacrano la tua gente.\n\nLa Dama Oscura mi ha ordinato di occuparmi di questo insetto una volta per tutte. Sarai tu lo strumento della resa dei conti dei Reietti.", 0x6dfc8040, 0x73acbf95, 0x804bd992, nil, 0xd1fdc659, "...m." },
  [6145] = { "Il ⟦Crimson Courier=Corriere Cremisi⟧", "Torna nelle ⟦Eastern Plaguelands=Terre Infette Orientali⟧ e rintraccia il ⟦Crimson Courier=Corriere Cremisi⟧. Uccidilo e recupera il Comando del Gran Crociato.\n\nPorta il comando a ⟦Nathanos Blightcaller=Nathanos Selvamorta⟧ per ricevere altre istruzioni.", "Come il corpo non può sopravvivere senza la testa, la testa non può sopravvivere senza il corpo. Le difese del comando della Crociata Scarlatta dentro Stratholme sono quasi impenetrabili. Dobbiamo invece tagliare via il corpo da sotto la testa.\n\nI miei ⟦Deathstalkers=Inseguitori della Morte⟧ raccolgono informazioni sulle attività della Crociata fuori da Stratholme. Ogni giorno il loro comando centrale invia un rapporto alla ⟦Tyr's Hand=Mano di Tyr⟧. Quel rapporto è la chiave, {race}! Trova il ⟦Crimson Courier=Corriere Cremisi⟧ e recupera il rapporto. Portalo a Nathanos.", "Riesci ora e ti sarai quasi guadagnat<o/a> il mio rispetto, {class}.", "<Nathanos ride.>\n\nEccellente! Finalmente! L'occasione di distruggere l'Oracolo Scarlatto!", 0xa3d0e449, 0x6a108010, 0x2b17abae, 0xb5ecff12, 0x91191c74, "....." },
  [6146] = { "Lo stratagemma di Nathanos", "Raggiungi la ⟦Tyr's Hand=Mano di Tyr⟧, a sud-est della Cascina dei Marris. Una volta lì, da' un morso alla ⟦Rotten Apple=Mela Marcia⟧. Sotto le sembianze di un membro della ⟦Scarlet Crusade=Crociata Scarlatta⟧, consegna il Comando del Gran Crociato al signore dei crociati Valdelmar.", "Ho apportato qualche modifica a questo ordine. Se il nostro piccolo stratagemma funziona, faranno uscire allo scoperto l'Oracolo Scarlatto e noi colpiremo!\n\nOra presta attenzione, {class}. Devi consegnare questo ordine al signore crociato Valdelmar.\n\nCome? Glielo metterai in mano, imbecille.\n\nPorta l'ordine e questa mela marcia alla ⟦Tyr's Hand=Mano di Tyr⟧. Quando entrerai in città, mangia la mela. Ti trasformerai in qualcosa di più... gradito agli umani. Prendi l'ordine e consegnalo al signore crociato Valdelmar.", "È inaccettabile, soldato!", "Dov'eri finit<o/a>? Pensavamo che il Flagello ti avesse catturat<o/a>.", 0x92ee3d1e, 0x4b5e8476, 0xe3d73292, 0x448f001a, 0xdc91379b, "....." },
  [6147] = { "Ritorno da Nathanos", "Torna da ⟦Nathanos Blightcaller=Nathanos Selvamorta⟧ con le nuove informazioni.", "Il Gran Crociato fa una richiesta insolita. Mm, comunque sia... ciò che chiede sarà fatto. Torna allo Scarlet Bastion e comunicagli che l'Oracolo sarà presto in viaggio.\n\nPrenderemo ogni precauzione perché arrivi a Stratholme sana e salva.", nil, "Che sciocchi! Il mio inganno è passato inosservato! Preparati, {class}. Dobbiamo colpire con fredda astuzia!", 0xea97ce6a, 0xe2026b1f, 0x2954b5af, nil, 0x44f34480, "...m." },
  [6148] = { "L'Oracolo Scarlatto, Demetria", "La ⟦Scarlet Crusade=Crociata Scarlatta⟧ è in movimento. Da qualche parte lungo la strada tra la ⟦Tyr's Hand=Mano di Tyr⟧ e Stratholme troverai l'Oracolo, Demetria, con il suo seguito. Dalle la caccia e uccidila. Se ci riesci, torna da ⟦Nathanos Blightcaller=Nathanos Selvamorta⟧.", "Demetria è la prima consigliera del Gran Crociato. La chiamano l'Oracolo per i suoi sensi 'ultraterreni'. Ha aiutato la Crociata a ottenere diverse vittorie contro il Flagello.\n\nAnche se questo stratagemma è riuscito a farla uscire allo scoperto, se possiede davvero poteri psichici si aspetterà senza dubbio qualche guaio. Quel 'guaio' sarai tu.\n\nRintraccia l'Oracolo ed eliminala. Dovrebbero lasciare la ⟦Tyr's Hand=Mano di Tyr⟧ proprio in questo momento. Rendimi fiero, verme.", "Qual è la situazione, {name}?", "Ci vorranno anni perché si riprendano da questo colpo! Ben fatto, {name}! Ti sei guadagnat<o/a> non solo il mio rispetto, ma anche questa ricompensa.", 0x8bbb1750, 0x0e0bfa77, 0x521dd337, 0x099381a6, 0x6dd61f23, "....." },
  [6161] = { "Reclama il tesoro di Rackmore!", "Trova la ⟦Rackmore's Silver Key=Chiave d'Argento di Rackmore⟧. Trova la ⟦Rackmore's Golden Key=Chiave d'Oro di Rackmore⟧. Trova e apri Rackmore's Chest.", "Il diario di bordo di Rackmore racconta che la sua nave era diretta alla Roccaforte di Piumaluna quando fu attaccata da creature marine. Per evitare che il tesoro cadesse in mani nemiche, nascose il suo forziere sull'⟦Ranazjar Isle=Isola di Ranazjar⟧.\n\nPer aprire il forziere servono due chiavi, una d'argento e una d'oro. Le chiavi sono andate perdute, ma se si trovano le chiavi e il forziere, un tesoro attende!", "Questo scrigno è chiuso saldamente a chiave.", "Il forziere si apre e rivela il tesoro di Rackmore!", 0x9e9779af, 0x0255b29e, 0xb6b2aff5, 0x24ee971a, 0xa231516f, "....." },
  [6162] = { "L'ultima battaglia di un marito", "Uccidi ⟦Overlord Ror=Supremo Ror⟧ e porta il suo artiglio a ⟦Dreka'Sur=Dreka'sur⟧ all'⟦Bloodvenom Post=Accampamento di Sanguemarcio⟧, nel ⟦Felwood=Vilbosco⟧.", "Mio marito ha percorso il ⟦Felwood=Vilbosco⟧ per l'onore del nostro clan, combattendo contro il ⟦Shadow Council=Concilio dell'Ombra⟧ e altre atrocità corrotte!\n\nDopo essere sfuggito alla morte innumerevoli volte, mi ha scritto una lettera in cui diceva che un druido gli aveva chiesto aiuto contro un grande mezzorso corrotto chiamato il signore supremo Ror. Di loro due non si è più saputo nulla.\n\nVoglio la mano artigliata di questo Ror, {name}. Voglio che paghi per avermi lasciata vedova! Credo che la creatura si trovi a sud... vicino al confine con ⟦Ashenvale=Valtetra⟧.", "Hai già l'artiglio della bestia, {name}? Pagherà per i suoi crimini. Non m'importa se è corrotta o solo furiosa perché vive in una foresta così desolata. Nessun mezzorso vivrà a lungo dopo aver commesso crimini simili contro la mia famiglia!", "Mi fai onore tenendo fede alla tua parola. Mio marito è morto in battaglia, e ne sarebbe stato fiero. Ma non potevo trovare pace finché non avessi saputo che la creatura che mi ha costretta a vivere da sola aveva pagato per ciò che aveva fatto.\n\nGrazie ancora, {name}.", 0x2a69edfc, 0x470d8aae, 0x2040c5d3, 0x44d759ff, 0x889e236c, "....." },
  [6163] = { nil, "Raggiungi Stratholme e uccidi ⟦Ramstein the Gorger=Ramstein il Bramacarne⟧. Prendi la sua testa come ricordo per Nathanos.", "Fui sopraffatto. Proprio in questa cascina resistetti... tenni la posizione in difesa di Lordaeron. La fattoria e tutto ciò che c'era furono travolti da un'immensa ondata del Flagello.\n\nQuel miserabile. Quella lordura. Mi sovrastava, con le viscere che pendevano dalla cavità squarciata del petto.\n\nMi risvegliai come parte del Flagello. Per tanto tempo fui impotente. La mia mente si era fusa con quella del Re dei Lich.\n\nLei venne a prendermi... in qualche luogo, in qualche modo, sapevo che sarebbe venuta. Libero.\n\nE ora devo avere la mia vendetta, la vendetta su ciò che mi tolse la vita. Distruggilo.", "Dopo che Sylvanas mi liberò, diedi la caccia alla bestia per mesi in queste lande desolate. Fuggì al sicuro a Stratholme. Il bastardo...", "Mi chiedo... avrà implorato pietà? Poteva sapere cosa sia la pietà?\n\n<Nathanos sputa.>\n\nAppenderò la testa di questa bestia alla mia parete.\n\nTi sei guadagnat<o/a> un posto tra i miei campioni, {name}.\n\n<Nathanos fa il saluto militare.>", 0xc3b49104, 0xeac63321, 0xfc251360, 0x0daee5b8, 0x2c45f03c, "e...." },
  [6164] = { "⟦Augustus' Receipt Book=Libro Mastro di Augustus⟧", "Porta il ⟦Augustus' Receipt Book=Libro Mastro di Augustus⟧ ad ⟦Augustus the Touched=Augustus lo Svitato⟧, a ⟦Terrordale=Valterrore⟧.", "Sono pronto a fare affari! Che cosa vuoi?\n\nOh, aspetta... Non posso aprire bottega senza il mio libro mastro. Come faccio a tenere i conti senza il mio libro mastro?\n\nDevo averlo lasciato da qualche parte in città. Avevo una stanza alla locanda... il libro dev'essere lì.\n\nPortami il mio libro. Ti prego, portamelo! Portami il mio libro e vedrai! Aprirò bottega e vedrai che i miei prezzi sono DA PAZZI!", "Hai il mio libro mastro? Non vedo l'ora di tornare agli affari!", "Eccolo! E, oh, cielo! Avevo dimenticato quanto fosse pieno!\n\nÈ un giorno glorioso, {name}! Stupendo! Bello da impazzire, dico io!", 0xfeff3f27, 0xe6301b68, 0x4e549251, 0x6cf97626, 0xbfcf70e2, "....." },
  [6181] = { "Un messaggio rapido", "Porta la ⟦Lewis' Note=Nota di Lewis⟧ a Thor, il maestro dei grifoni.", "Anche se da ⟦Stormwind=Roccavento⟧ non riceviamo molti aiuti diretti, in città ho un contatto che ci rifornisce di armature. Si chiama Osric Strang. La sua bottega, Limited Immunity, è nella Città Vecchia di ⟦Stormwind=Roccavento⟧.\n\nLe nostre scorte di armature si stanno esaurendo e devo chiederne altre a Osric. Puoi portargli questa nota?\n\nIl modo più rapido per arrivare a ⟦Stormwind=Roccavento⟧ è tramite Thor, il nostro maestro dei grifoni. Sta giù in fondo alla collina: portagli la mia nota, poi prendi un grifone per ⟦Stormwind=Roccavento⟧.", "Sembri di fretta. Be', allora sei nel posto giusto!", "Devi portare questa nota a ⟦Stormwind=Roccavento⟧? Nessun problema, puoi prendere uno dei miei grifoni!", 0xd0027ff1, 0xacee0705, 0x971b5160, 0x5c4d4ffe, 0x13821bcd, "....." },
  [6182] = { "Il primo e l'ultimo", "Parla con Mathias Shaw nella Città Vecchia di ⟦Stormwind=Roccavento⟧. Risiede nella caserma.", "Nathanos Marris fu il primo e l'ultimo dei signori dei ranger umani. Un discepolo di Sylvanas Windrunner, ora Regina delle Banshee dei Reietti.\n\nCredevamo che Nathanos fosse caduto in azione nella difesa di Lordaeron, cinque anni fa. Anche se il suo corpo non fu mai ritrovato, si pensava che non fosse uscito vivo dalle ⟦Eastern Plaguelands=Terre Infette Orientali⟧.\n\nMathias Shaw indaga sulla scomparsa e potrebbe avere nuove informazioni. Fai subito rapporto a lui. Risiede nella Città Vecchia, nella caserma.", nil, "Dopo alcune segnalazioni di insolite attività dei Reietti nelle ⟦Eastern Plaguelands=Terre Infette Orientali⟧, furono inviati degli agenti dell'⟦SI:7=IR:7⟧ a indagare. I risultati di quell'indagine sono inquietanti.", 0x79d07d7d, 0x896b2154, 0xf98d351b, nil, 0xe83b7f3e, "...m." },
  [6183] = { "Onorare i caduti", "Parla di nuovo con Mathias Shaw se vuoi accettare il suo incarico.", "Cinque dei miei migliori agenti sul campo furono assegnati al caso Marris. Uno solo tornò, per poi morire nel sonno tre giorni dopo.\n\nLe poche informazioni che riuscimmo a cavargli erano farneticazioni incoerenti. Distinguemmo due parole: \"Nathanos\" e \"Blightcaller\".\n\nNon ho uomini disponibili per proseguire questa indagine e ⟦Ravenholdt=Corvolesto⟧ non ci aiuterà. Dobbiamo andare a fondo della faccenda, se non altro per dare pace alle famiglie dei caduti. Mi aiuterai?", nil, "<Mathias annuisce.>\n\nEro certo che Bolvar mi avrebbe mandato uomini e donne d'onore: i soldati più devoti dell'⟦Alliance=Alleanza⟧.", 0xabd1351c, 0x4ac23430, 0x0f11aa78, nil, 0x4bc4d491, "...m." },
  [6184] = { "⟦Flint Shadowmore=Flint Ombraviva⟧", "Raggiungi l'⟦Chillwind Camp=Accampamento di Ventofreddo⟧, nelle ⟦Western Plaguelands=Terre Infette Occidentali⟧, e incontra il tuo contatto, ⟦Flint Shadowmore=Flint Ombraviva⟧.", "L'unica informazione che abbiamo finora, dunque, è che Nathanos Marris potrebbe essere stato ucciso da questo Blightcaller. Supponiamo che il Blightcaller sia lo stesso demonio che ha eliminato i miei agenti.\n\nFlint Shadowmore, un altro agente dell'⟦SI:7=IR:7⟧, è di stanza all'accampamento dell'⟦Alliance=Alleanza⟧ alla ⟦Chillwind Point=Gola di Ventofreddo⟧, nelle ⟦Western Plaguelands=Terre Infette Occidentali⟧. Cercalo: ti aggiornerà sulla situazione attuale nelle Terre Infette e ti affiderà un incarico.\n\nBuona fortuna, {name}.", nil, "La prima missione sarà semplice, {name}. Entri, esci. Ricognizione...", 0x065813ab, 0xe649a5a0, 0xe08ff202, nil, 0x227d8a04, "...m." },
  [6185] = { "Le Terre Infette Orientali", "Perlustra le ⟦Eastern Plaguelands=Terre Infette Orientali⟧ in cerca di indizi sul \"Blightcaller\" e sugli agenti scomparsi dell'⟦SI:7=IR:7⟧. Se trovi delle SI:7 Insignia, portale a ⟦Flint Shadowmore=Flint Ombraviva⟧ all'⟦Chillwind Camp=Accampamento di Ventofreddo⟧.", "Come ho detto, la tua prima missione è di ricognizione. Niente di complicato, {name}. Devi raggiungere le ⟦Eastern Plaguelands=Terre Infette Orientali⟧ e cercare qualsiasi indizio su questo Blightcaller.\n\nTieni gli occhi aperti per qualsiasi informazione sui nostri agenti scomparsi. Dobbiamo supporre che siano morti e, se sono morti, ci sarà un cadavere... da qualche parte.\n\n<Flint deglutisce a fatica.>\n\nTutti gli agenti dell'⟦SI:7=IR:7⟧ portano questa insegna.\n\n<Flint ti mostra la sua insegna dell'⟦SI:7=IR:7⟧.>\n\nPortami tutte quelle che riesci a trovare.", "Qu... Qualche novità??", "Rutger. Fredo. Turyen. Tutti... morti...\n\n<Flint stringe forte le insegne.>\n\nDove si trovavano? Hai scoperto altro su questo bastardo, il Blightcaller?", 0x4c499f21, 0xa40c5ce3, 0x80c06b69, 0x098a41c8, 0xc319792f, "....." },
  [6186] = { "Arriva il Blightcaller", "Torna a ⟦Stormwind=Roccavento⟧ e informa il gran signore Bolvar Domadraghi della sorte di Nathanos Marris.", "<Il volto di Flint sembra aver perso ogni colore.>\n\nNa... Nathanos ha fatto questo? Nathanos è il Blightcaller?\n\nPerché? Era... era così nobile, un signore dei ranger rispettato da tutti. L'unico umano a cui sia mai stato permesso di addestrarsi con gli alti elfi. E ora è uno spietato agente dei Reietti?\n\nMi... mi dispiace chiedertelo, {name}, ma il gran signore Fordragon deve essere informato subito di questa svolta. Ti prego, torna a ⟦Stormwind=Roccavento⟧ e porta la notizia.", nil, "No. Non... NO! Come? Un agente dei Reietti? Il CAMPIONE della Regina delle Banshee???\n\n<Il gran signore Bolvar Domadraghi si accascia, sconfitto.>", 0xa9ba516f, 0xbd9e3e1d, 0x189b32d7, nil, 0x7872b9fb, "...m." },
  [6187] = { "L'ordine va ristabilito", "Raduna un esercito e raggiungi le ⟦Eastern Plaguelands=Terre Infette Orientali⟧. Lancia un assalto in forze contro ⟦Nathanos Blightcaller=Nathanos Selvamorta⟧ e contro tutta la feccia dell'⟦Horde=Orda⟧ che tenterà di proteggerlo.\n\nTieni gli occhi aperti, {name}. L'⟦Horde=Orda⟧ difenderà il signore dei ranger a costo della vita.", "Sai quanti signori dei ranger esistono in questo mondo? Quanti signori dei ranger umani siano mai esistiti?\n\nLe imprese di Nathanos non avevano precedenti. Era un genio della tattica, artefice di vittorie dell'⟦Alliance=Alleanza⟧ in un decennio di conflitti.\n\nE ora... il campione dei Reietti.\n\nNo. Non può essere. L'ordine va ristabilito.\n\nRaduna un esercito, {name}. Torna nelle Terre Infette con il tuo esercito e distruggi il Blightcaller.\n\nTi auguro buona fortuna, {name}. Davvero, ne avrai bisogno in questa battaglia.", "<Il gran signore Bolvar Domadraghi è perso nei suoi pensieri.>", "È una tragedia. Penso... credo che la nostra stirpe sia maledetta, {name}. Siamo condannati a perdere i nostri più grandi guerrieri, i nostri eroi più nobili, i nostri studiosi più dotati.\n\nTi siamo debitori e ti assicuro, {name}, che ovunque si trovi ora Nathanos Marris, ti sorride dall'alto.", 0xa805e50b, 0xc706a84e, 0x37c61b0a, 0x3462e28c, 0x86761e86, "....." },
  [6261] = { "⟦Dungar Longdrink=Dungar Voloteso⟧", "Porta la ⟦Osric's Crate=Cassa di Osric⟧ a ⟦Dungar Longdrink=Dungar Voloteso⟧, il maestro dei grifoni.", "{name}, ho messo in questa cassa tutto ciò che Lewis ha chiesto. Puoi portargliela?\n\nSe hai già parlato con Thor nelle ⟦Westfall=Marche Occidentali⟧, puoi prendere un grifone per tornare da lui. ⟦Dungar Longdrink=Dungar Voloteso⟧ è il nostro maestro dei grifoni, laggiù nel Quartiere del Commercio.\n\nParla con Dungar, poi porta questa cassa a Lewis il più in fretta possibile. Non vogliamo che i nostri uomini e le nostre donne al fronte nelle ⟦Westfall=Marche Occidentali⟧ restino senza equipaggiamento nuovo!", "È sudore quello sulla tua fronte, <ragazzo/signora>? Hai corso troppo. La prossima volta prendi un grifone!", "Una cassa per le ⟦Westfall=Marche Occidentali⟧, eh? Ci sei già stat<o/a>, nelle ⟦Westfall=Marche Occidentali⟧? Se sì, nessun problema, <amico/amica>. Ho un sacco di grifoni addestrati per quella rotta!", 0x99cf1567, 0x7f71eb16, 0x150a7f07, 0xd7a18628, 0xfce80486, ".....", nil, nil, nil, 0x276c0f6b, nil },
  [6281] = { "Verso ⟦Stormwind=Roccavento⟧", "Paga un volo in grifone al maestro dei grifoni Thor, poi porta la ⟦Lewis' Note=Nota di Lewis⟧ a Osric Strang, nella bottega Limited Immunity, nella Città Vecchia di ⟦Stormwind=Roccavento⟧.", "Per una piccola somma puoi prendere un grifone per ⟦Stormwind=Roccavento⟧ e consegnare la nota di Lewis a Osric. Non ci arriverai più in fretta in nessun altro modo.\n\nSe ti va bene, parla di nuovo con me quando sei pront<o/a> per il volo. Ti chiederò qualcosa, ma fidati: ne varrà la pena!", "Sei stat<o/a> in viaggio, eh? Sei andat<o/a> da qualche parte di interessante?", "Ah, una nota del quartiermastro Lewis? Non mi sorprende che gli serva altro equipaggiamento. ⟦Sentinel Hill=Guardiacolle⟧ è lontana, in una terra che ⟦Stormwind=Roccavento⟧ ha quasi dimenticato.\n\nBe', grazie, {name}. Ecco un po' di denaro per coprire le spese di viaggio.", 0x950eaddd, 0x9a2be79a, 0xd7241ffb, 0xd55888b8, 0x83dfa7ed, "....." },
  [6282] = { "La minaccia delle arpie", "⟦Maggran Earthbinder=Maggran Plasma Terra⟧, al ⟦Sun Rock Retreat=Rifugio Roccia del Sole⟧, vuole che tu uccida 7 Bloodfury Harpy, 7 Bloodfury Ambusher, 7 Bloodfury Slayer e 7 Bloodfury Roguefeather.", "I tauren sono fieri di essere i protettori di queste terre. Di certo puoi immaginare perché mi allarma il numero di arpie che vivono qui a ⟦Stonetalon=Petrartiglio⟧.\n\nLe Furie Rosse sono la causa del numero crescente di arpie a Kalimdor; invadono ogni forma di vita, impedendo agli innocenti di uscire dai loro confini.\n\nDevi sfoltire le arpie, {name}!", "Non temere la ⟦Charred Vale=Valle Bruciata⟧; molte creature malvagie dimorano su quelle colline. Resta forte, {name}, e avrai la meglio su questa minaccia per il nostro popolo. Ora va' e colpisci duro: i nostri figli non dovranno mai conoscere il male che è stato.", "Questa sì che è un'ottima notizia! Raccontami di nuovo come hai seminato il terrore nei cuori gelidi di quelle arpie maledette. Le Furie Rosse hanno subito un duro colpo!", 0x1341afda, 0x40e68446, 0xf4114034, 0x2cd50b9f, 0x85595902, "....." },
  [6283] = { "La stirpe delle Furie Rosse", "Maggran, al ⟦Sun Rock Retreat=Rifugio Roccia del Sole⟧, vuole che tu uccida ⟦Bloodfury Ripper=Squartatrice delle Furie Rosse⟧ e ne porti i resti come prova della tua impresa.", "Limitare il numero delle arpie delle Furie Rosse non basterà. L'unica vera cura per il loro morbo sarebbe uccidere la loro guida, ⟦Bloodfury Ripper=Squartatrice delle Furie Rosse⟧!\n\nPer quelle sudice creature è quasi una regina. Uccidila e il loro numero calerà di sicuro.\n\nTorna nella ⟦Charred Vale=Valle Bruciata⟧ e la troverai lungo le colline occidentali. Non sarà facile sconfiggerla, ma la ricompensa sarà grande.", "⟦Bloodfury Ripper=Squartatrice delle Furie Rosse⟧ è una creatura malvagia! La troverai lungo la linea delle colline occidentali, nella ⟦Charred Vale=Valle Bruciata⟧.\n\nSenza di lei le Furie Rosse saranno indifese... di certo potremo sconfiggerle per sempre!", "Già sento la rabbia abbandonarmi. Cosa farò del mio tempo? Sapere che il male si muoveva vicino alla mia terra teneva vivi i miei pensieri, ma ora tacciono. Forse è un bene... forse ora posso concentrarmi sul bene, come dovrebbe fare ogni tauren.\n\nTi prego, accetta questo come ricompensa per il tuo disturbo.", 0x6c41a89f, 0x8b79db61, 0x4c64b1d5, 0x056fd9cb, 0x6796f8ca, "....." },
  [6284] = { "Aracnofobia", "Uccidi Besseleth e porta la ⟦Besseleth's Fang=Zanna di Besseleth⟧ a Maggran al ⟦Sun Rock Retreat=Rifugio Roccia del Sole⟧.", "Attenzione: chi si addentra nel ⟦Sishir Canyon=Canyon di Sishir⟧, a ovest di qui, lo fa a proprio rischio.\n\nBesseleth e i suoi figli a otto zampe della foresta hanno fatto di questo canyon la loro tana di ragnatele.\n\nMaggran Earthbinder, al ⟦Sun Rock Retreat=Rifugio Roccia del Sole⟧, ha messo una taglia su Besseleth. Uccidila e porta a Maggran la prova dell'uccisione: lì riceverai la ricompensa per aver eliminato questa minaccia a otto zampe.", "Besseleth è una predatrice spietata... temo per chi percorre il ⟦Webwinder Path=Sentiero Passocurvo⟧ di notte. È allora che lei e i suoi figli si avventano sui viaggiatori innocenti. Anch'io sono finito preda della sua zanna mortale lunga due piedi, ma per fortuna sono riuscito a respingerla e a mettermi in salvo. Darei qualsiasi cosa per vedere distrutto quel mostro.", "Buona caccia, {name}! Besseleth è una vecchia predatrice da queste parti... non ne sentirò la mancanza. Prendi questa ricompensa in segno di riconoscimento come <campione/campionessa> della foresta.\n\n<Maggran si massaggia la ferita inflitta da Besseleth.>\n\nForse ora molti altri verranno al ⟦Sun Rock Retreat=Rifugio Roccia del Sole⟧ senza temere ciò che si cela nel buio.", 0x1171fcc5, 0xcbae1752, 0xa1f2522d, 0x85b0f7df, 0x7e895fb4, "....." },
  [6285] = { "Ritorno da Lewis", "Paga un volo in grifone per ⟦Sentinel Hill=Guardiacolle⟧ al maestro dei grifoni ⟦Dungar Longdrink=Dungar Voloteso⟧, poi porta la ⟦Osric's Crate=Cassa di Osric⟧ a Lewis a ⟦Sentinel Hill=Guardiacolle⟧.", "Il maestro dei grifoni nelle ⟦Westfall=Marche Occidentali⟧ è Thor. Se ci hai già parlato, puoi prendere uno dei miei grifoni per raggiungerlo.\n\nÈ una buona lezione da imparare: i grifoni sono sempre addestrati a volare verso la loro capitale, ma ti porteranno da un maestro dei grifoni lontano solo dopo che ci sei già stat<o/a>.\n\nSei già stat<o/a> da Thor, quindi parla di nuovo con me quando sei pront<o/a> a prendere un grifone per le ⟦Westfall=Marche Occidentali⟧. Una volta lì, potrai consegnare la ⟦Osric's Crate=Cassa di Osric⟧ al quartiermastro Lewis.", "Sei tornat<o/a> da ⟦Stormwind=Roccavento⟧? Osric ha mandato le armature?", "Ottimo, hai portato le armature! Le distribuiremo subito a chi ne ha bisogno.\n\nGrazie, {name}. I tuoi sforzi ci sono stati di grande aiuto. E ora che i grifoni non sono più una novità per te, spero che verrai spesso a dare una mano a ⟦Sentinel Hill=Guardiacolle⟧!", 0x96f66445, 0x1c7c566e, 0xb428ac6f, 0x54a54947, 0xb877172b, "....." },
  [6301] = { "Il ciclo della rinascita", "⟦Tammra Windfield=Tammra Vento Piatto⟧, al ⟦Sun Rock Retreat=Rifugio Roccia del Sole⟧, vuole che tu raccolga 10 Seme di Gaea.", "L'avidità industriale e la guerra continua hanno devastato le terre di ⟦Stonetalon=Petrartiglio⟧. Solo le benedizioni della Madre Terra possono guarire una simile ferita.\n\n{name}, ti chiederò di cercare un seme speciale, il seme di Gaea. Si trova solo qui, a ⟦Stonetalon=Petrartiglio⟧, a nord del ⟦Sun Rock Retreat=Rifugio Roccia del Sole⟧, presso il ⟦Mirkfallon Lake=Lago Mirkfallon⟧, vicino alla riva.\n\nQuando mi porterai i semi, li infonderò di potere sciamanico per accelerarne la crescita.", "La distruzione continua causata dalla guerra e da chi cerca profitto dal legname mi addolora profondamente. Per aiutare il ciclo della rinascita e rinvigorire le terre mi servono semi di Gaea. Li hai, {class}?", "Ah, {name}, hai i semi di Gaea. Guarda come la benedizione della Madre Terra può far sbocciare e fiorire perfino questi piccoli chicchi di vita.\n\n<Tammra comincia a cantilenare.>", 0x1ee45c42, 0x412fe15f, 0x8cfd01f8, 0x5760b342, 0xb389c0fe, "....." },
  [6321] = { "Rifornimenti per la ⟦Sepulcher=Mausolea⟧", "Porta Podrig's Order a Karos Razok.", "L'esecutore Hadrec mi ha chiesto di fare l'inventario del nostro equipaggiamento alla ⟦Sepulcher=Mausolea⟧. Con il Flagello, e di peggio, in agguato nei boschi, non vuole che ai guardiamorte manchi l'equipaggiamento di cui potrebbero aver bisogno.\n\nHo scoperto che, in generale, siamo ben riforniti, ma ci servono altre armi per sostituire quelle perse sul campo.\n\nEcco un ordine di requisizione con ciò che serve, per il mercante d'armi Gordon Wendham a ⟦Undercity=Sepulcra⟧. Porta l'ordine al nostro maestro dei pipistrelli, Karos Razok, e parla con lui del trasporto fino a ⟦Undercity=Sepulcra⟧.", "Hai l'aria di chi è qui per affari ufficiali...", "Ah, un ordine di rifornimenti. Vorrai portarlo a ⟦Undercity=Sepulcra⟧, senza dubbio. E in fretta, perché la ⟦Sepulcher=Mausolea⟧ non deve restare a corto di scorte.", 0xcfcc9350, 0xe5b2c631, 0x954541ad, 0x048ed251, 0x09aef9bb, "....." },
  [6322] = { nil, "Porta la ⟦Gordon's Crate=Cassa di Gordon⟧ a Michael Garrett.", "Ho messo le provviste per la ⟦Sepulcher=Mausolea⟧ in questa cassa. Se hai già visitato la ⟦Sepulcher=Mausolea⟧ e parlato con il loro maestro dei pipistrelli, puoi tornare da lui in pipistrello.\n\nParla con il maestro dei pipistrelli di Sepulcra, Michael Garrett. Può darti un pipistrello per la ⟦Sepulcher=Mausolea⟧.", "Se devi percorrere una lunga distanza, il pipistrello è la scelta migliore.", "Questa cassa deve arrivare alla ⟦Sepulcher=Mausolea⟧, a ⟦Silverpine=Pinargento⟧? È facile: i nostri pipistrelli ci volano ogni giorno.", 0x30ec3f6a, 0x230e74d9, 0xc7c7a93c, 0xd08ea5ce, 0x0dfb1564, "e...." },
  [6323] = { "In volo verso ⟦Undercity=Sepulcra⟧", "Paga un volo in pipistrello per ⟦Undercity=Sepulcra⟧ al maestro dei pipistrelli Karos Razok, poi porta ⟦Podrig's Order=Ordine di Podrig⟧ a Gordon Wendham a ⟦Undercity=Sepulcra⟧.", "Uno dei miei pipistrelli può portarti a ⟦Undercity=Sepulcra⟧, per una piccola somma. Parla di nuovo con me quando sei pront<o/a>, così potremo organizzare il tuo trasporto.\n\nTroverai Gordon Wendham nel ⟦Trade Quarter=Quartiere del Commercio⟧ di ⟦Undercity=Sepulcra⟧. È lo stesso quartiere dove atterrerà il mio pipistrello.", "Tengo le mie armi in perfette condizioni. Sono pulite e pronte all'uso.", "Un ordine dalla ⟦Sepulcher=Mausolea⟧? Molto bene. È un onore servire chi serve la nostra Dama Oscura.", 0x5760d29a, 0x3400fc7c, 0x02b18c1a, 0xf820d1e4, 0x2b5a74f3, "....." },
  [6324] = { "Ritorno da Podrig", "Paga un volo in pipistrello per la ⟦Sepulcher=Mausolea⟧ al maestro dei pipistrelli Michael Garrett, poi porta la ⟦Gordon's Crate=Cassa di Gordon⟧ al guardiamorte Podrig alla ⟦Sepulcher=Mausolea⟧.", "Il maestro dei pipistrelli della ⟦Sepulcher=Mausolea⟧ è Karos Razok. Se l'hai già incontrato, posso darti un pipistrello per tornare da lui.\n\nI nostri pipistrelli voleranno sempre verso ⟦Undercity=Sepulcra⟧, ma per raggiungere località più remote chi li cavalca deve prima visitare la zona e parlare con il suo maestro dei pipistrelli.\n\nHai incontrato Karos alla ⟦Sepulcher=Mausolea⟧, quindi ora puoi volarci in pipistrello. Parla di nuovo con me quando sei pront<o/a>.", "{name}, sei tornat<o/a>. Hai le nostre provviste da ⟦Undercity=Sepulcra⟧?", "Buon lavoro, {name}. Queste armi faranno sì che i nostri guardiamorte non vengano colti impreparati.\n\nHai reso un prezioso servizio alla nostra Dama Oscura.", 0xdb263293, 0x62f053a2, 0x2d4da181, 0x34df7e4c, 0x61e021f3, "....." },
  [6341] = { "L'abbondanza di Teldrassil", "Porta Nessa's Collection a Vesprystus.", "I pescatori del villaggio di Rut'theran se la passano molto bene, perché qui i pesci sono enormi e abbondanti. Vorrei confrontare l'abbondanza di qui con quella del continente.\n\nHo una raccolta di lische e squame che vorrei far arrivare a un mio collega a ⟦Darkshore=Rivafosca⟧. Si chiama Laird ed è un pescivendolo nel villaggio di Auberdine.\n\nPorta la mia raccolta al nostro maestro degli ippogrifi, Vesprystus, e parla con lui del viaggio fino ad Auberdine.", "Come posso aiutarti? Ti serve un passaggio?", "Ah, vuoi portare questa ad Auberdine? Molto bene...", 0xfdaa45cb, 0x849cfb5d, 0xeffe6b5d, 0x2fd3c26c, 0x82c592b4, "....." },
  [6342] = { "Volo per Auberdine", "Vola in ippogrifo fino ad Auberdine con il maestro degli ippogrifi Vesprystus, poi porta ⟦Nessa's Collection=Collezione di Nessa⟧ a Laird.", "Da Rut'theran ci sono due modi per raggiungere Auberdine: il traghetto e l'ippogrifo. Entrambi sono rapidi e affidabili, ma se non hai ancora volato fino ad Auberdine in ippogrifo, ti consiglio di farlo.\n\nÈ un buon consiglio parlare con il maestro degli ippogrifi di ogni città che ne ha uno. Una volta che avrai parlato con il maestro, potrai volare lì dalle altre città.\n\nEcco la raccolta di Nessa. Parla di nuovo con me quando sei pront<o/a> a volare fino ad Auberdine per consegnare la raccolta di Nessa a Laird.", "Vieni da Teldrassil? Dimmi, com'è la pesca laggiù?", "Un pacco da Nessa? Grazie, {name}! Mi aveva detto che mi avrebbe mandato dei campioni dei pesci pescati vicino al villaggio di Rut'theran. Pensa che possano essere molto diversi dai pesci pescati qui...\n\nPerbacco! Questa mandibola è grande quasi il doppio di quella dello stesso pesce trovato qui. E queste squame sono grandi come un pugno chiuso! Incredibile!", 0xdcb4055c, 0xedfc0608, 0xf7020ff1, 0x289d443c, 0xa33b905a, "....." },
  [6343] = { "Ritorno da Nessa", "Porta Laird's Response a ⟦Nessa Shadowsong=Nessa Cantombroso⟧.", "Devo mandare una risposta a Nessa. Sarà molto interessata a sapere quanto sono diversi i pesci di qui da quelli lungo le coste di Teldrassil. Possiamo solo fare ipotesi sulla causa, ma sospetto che sia l'Albero del Mondo stesso a influire sulla fauna che lo circonda!\n\nTi prego, porta questa risposta a Nessa. Se vuoi prendere un ippogrifo per tornare a Rut'theran, parla con il maestro degli ippogrifi ⟦Caylais Moonfeather=Caylais Lunapiuma⟧. Se preferisci il traghetto, ne parte regolarmente uno dal molo a nord-ovest.", "{name}, sei tornat<o/a> da Auberdine? Hai parlato con Laird?", "È molto interessante. I pesci qui sono grandi, ma non pensavo che la differenza di abbondanza tra qui e il continente fosse così marcata. Dev'esserci una ragione...\n\nBe', grazie, {name}. Discuterò con gli abitanti del villaggio delle notizie che hai portato. Forse, un giorno, scopriremo la radice di questa stranezza. Ma fino ad allora, ne godremo i frutti!", 0xba10c9cf, 0x9efa6697, 0x2381f0ae, 0x47a9c3c4, 0x4e30b81a, "....." },
  [6344] = { "⟦Nessa Shadowsong=Nessa Cantombroso⟧", "Parla con ⟦Nessa Shadowsong=Nessa Cantombroso⟧.", "Una mia amica, ⟦Nessa Shadowsong=Nessa Cantombroso⟧, è una mercante di pesce a ⟦Rut'theran Village=Rut'theran⟧. Ha bisogno che qualcuno porti un pacco a ⟦Darkshore=Rivafosca⟧ e cerca chi possa aiutarla.\n\nSe ti interessa, per raggiungere Nessa devi prendere il portale di Darnassus che porta a ⟦Rut'theran Village=Rut'theran⟧. Troverai il portale a ovest dei Temple Gardens.", nil, "Sì, ho bisogno di un corriere che porti un pacco a ⟦Darkshore=Rivafosca⟧. Mi aiuterai?", 0x1cde2001, 0x0db93fa5, 0x3d0373e4, nil, 0xaae17e8e, "...m." },
  [6361] = { "Un ⟦Bundle of Hides=Mucchio di Pelli⟧", "Porta il ⟦Bundle of Hides=Mucchio di Pelli⟧ al maestro delle viverne Devrak a ⟦Crossroads=Crocevia⟧.", "Ho un mucchio di pelli degli animali delle ⟦Barrens=Savane⟧ e devo farle arrivare a ⟦Thunder Bluff=Picco del Tuono⟧. Un collega laggiù, Ahanu, userà le pelli per creare articoli di cuoio.\n\nPorteresti le pelli a lui per me?\n\nIl modo più rapido per arrivare a ⟦Thunder Bluff=Picco del Tuono⟧ è in groppa a una viverna. Porta il mucchio di pelli a Devrak, il nostro maestro delle viverne a ⟦Crossroads=Crocevia⟧, e parla con lui del trasporto fino a ⟦Thunder Bluff=Picco del Tuono⟧.", "Sei qui per una viverna? Hai qualcosa da trasportare?", "Se devi portare queste pelli a ⟦Thunder Bluff=Picco del Tuono⟧, stai parlando con l'orco giusto!", 0x5629a678, 0x83576182, 0x83c7dd76, 0xc0c44b7a, 0x5fdeeba3, "....." },
  [6362] = { "In volo verso ⟦Thunder Bluff=Picco del Tuono⟧", "Paga una viverna per ⟦Thunder Bluff=Picco del Tuono⟧ al maestro delle viverne Devrak, poi porta il ⟦Bundle of Hides=Mucchio di Pelli⟧ ad Ahanu a ⟦Thunder Bluff=Picco del Tuono⟧.", "Per una piccola somma ti darò una viverna per ⟦Thunder Bluff=Picco del Tuono⟧. Non c'è modo più rapido per raggiungere la città!\n\nSe ti va bene, parla di nuovo con me quando sei pront<o/a> a partire.\n\nSe porti quelle pelli ad Ahanu, credo che sia alla Hewa's Armory, ai piedi della torre delle viverne di ⟦Thunder Bluff=Picco del Tuono⟧. Ed è proprio lì che atterrerai!", "Hai sulle spalle della polvere che deve venire dalle ⟦Barrens=Savane⟧. Hai parlato con il mio amico Jahan?", "Ah, un nuovo mucchio di pelli. Mi ci metto subito al lavoro!\n\nGrazie, <fratello/sorella>. Mi hai reso un grande servizio. Ecco qualche moneta per il tuo tempo e le spese di viaggio.", 0x17e56cf3, 0xdb3baab4, 0xa2c8ef96, 0x26fbf800, 0x24706f90, ".....", nil, nil, nil, nil, 0x6bd5e885 },
  [6363] = { "Tal, maestro delle viverne", "Porta le ⟦Ahanu's Leather Goods=Mercanzie di Pelle di Ahanu⟧ a Tal a ⟦Thunder Bluff=Picco del Tuono⟧.", "Ho preparato degli articoli di cuoio che Jahan venderà a ⟦Crossroads=Crocevia⟧. Glieli porteresti?\n\nSe sei già stat<o/a> a ⟦Crossroads=Crocevia⟧ e hai parlato con il loro maestro delle viverne, puoi tornare da lui con una delle nostre viverne di ⟦Thunder Bluff=Picco del Tuono⟧.\n\nPorta gli articoli di cuoio a Tal, il nostro maestro delle viverne a ⟦Thunder Bluff=Picco del Tuono⟧, e parla con lui per organizzare il trasporto fino a ⟦Crossroads=Crocevia⟧.", "Salve, {class}. Cosa posso fare per te?", "Devi portare questa roba a ⟦Crossroads=Crocevia⟧, eh? Nessun problema. Se ci sei già stat<o/a> e hai parlato con Devrak, puoi prendere una delle mie viverne per tornare da lui.", 0xf7fcbd33, 0xf87319fc, 0x14bf81fc, 0xaf415926, 0xd7505c5d, "....." },
  [6364] = { "Ritorno da Jahan", "Paga una viverna per ⟦Crossroads=Crocevia⟧ al maestro delle viverne Tal, poi porta le ⟦Ahanu's Leather Goods=Mercanzie di Pelle di Ahanu⟧ a ⟦Jahan Hawkwing=Jahan Pelle Fine⟧.", "Per volare verso una città devi esserci già stat<o/a> e aver parlato con il suo maestro delle viverne. Sei stat<o/a> a ⟦Crossroads=Crocevia⟧ e hai parlato con il loro maestro delle viverne, Devrak, quindi per una piccola somma puoi prendere una viverna da qui per raggiungerlo.\n\nParla di nuovo con me quando sei pront<o/a>. Una volta a ⟦Crossroads=Crocevia⟧, potrai consegnare gli articoli di cuoio a ⟦Jahan Hawkwing=Jahan Pelle Fine⟧.", "{name}, sei tornat<o/a> da ⟦Thunder Bluff=Picco del Tuono⟧? Hai consegnato le pelli ad Ahanu?", "Ahanu mi ha mandato i prodotti finiti? Molto bene. Ci sono molti cacciatori e avventurieri a ⟦Crossroads=Crocevia⟧ adesso, e gli affari vanno a gonfie vele. Sono sicuro che venderò questa merce molto presto.\n\nGrazie per tutti i tuoi sforzi, {name}. Ti sono debitore.", 0x734dcf93, 0x7a7dc803, 0xca30143e, 0xfdd2709f, 0x30c7484a, "....." },
  [6365] = { "Carne per Orgrimmar", "Porta Zargh's Meats a Devrak a ⟦Crossroads=Crocevia⟧.", "Ho dei tagli di carne scelti da mandare a un'amica. Si chiama Gryshka, è la locandiera di Orgrimmar. Me la consegni tu la carne?\n\nIl modo più rapido per arrivare a Orgrimmar è in viverna. Porta la carne al maestro delle viverne di ⟦Crossroads=Crocevia⟧, Devrak, e parla con lui del trasporto fino a Orgrimmar.", "Devi arrivare da qualche parte in fretta? Allora stai parlando con l'orco giusto!", "Devi portare questa carne a Orgrimmar? Nessun problema. Per una piccola somma, la mia viverna può portartici.", 0x192a86fc, 0x81387def, 0xb0f8daee, 0xb3f83d0e, 0x16ed8259, "....." },
  [6381] = { "Nuova vita", "Pianta 10 Seme di Gaea nei Gaea Dirt Mound, poi riporta i ⟦Enchanted Gaea Seeds=Semi di Gaea Incantati⟧ rimasti a Tammra al ⟦Sun Rock Retreat=Rifugio Roccia del Sole⟧.", "Come hai visto, {class}, anche se la terra soffre, il ciclo della vita è una forza potente. Ora dobbiamo fare la nostra parte per aiutarlo. Devi piantare questi semi al centro della distruzione, a ovest, nella ⟦Charred Vale=Valle Bruciata⟧. <Attento/Attenta> però: arpie ed elementali del fuoco infuriati infestano ancora quella terra sfregiata.\n\n{name}, prendi questi semi di Gaea incantati e piantali nei cumuli di terra fertile. Il ciclo della vita deve continuare!", "Questi semi che pianti sono forti, resistono alla corruzione e aprono la strada ad altra vita. Cresceranno e cresceranno, prima fermando la corruzione e guarendo la terra sfregiata, e poi un giorno riportando ⟦Stonetalon=Petrartiglio⟧ a essere una foresta rigogliosa, come un tempo.\n\nHai piantato tutti i semi di Gaea?", "È una grande vittoria per la terra. Col tempo accadranno altre cose: la S.P.R. & Co. impacchetterà le sue seghe circolari e le sue asce, gli spiriti del fuoco infuriati si placheranno e le arpie saranno scacciate dalla terra stessa.\n\nSolo allora, {name}, ⟦Stonetalon=Petrartiglio⟧ sarà davvero in pace.\n\nHai fatto bene, {class}; prendi uno di questi oggetti come ringraziamento per la nuova vita che hai creato qui oggi.", 0xd597138a, 0xe3c1961a, 0x8d150759, 0x14e0ce13, 0xf0f6254d, "....." },
  [6382] = { "La caccia di ⟦Ashenvale=Valtetra⟧", "Parla con ⟦Senani Thunderheart=Senani Cuore Tonante⟧ all'⟦Splintertree Post=Avamposto di Troncorotto⟧, a ⟦Ashenvale=Valtetra⟧.", "La tua forza mi colpisce, {class}. La tua disponibilità ad abbracciare la caccia mi dà fiducia che potresti passare a prede più grosse... e a sfide più grandi.\n\nLe foreste di ⟦Ashenvale=Valtetra⟧ sono una vasta terra selvaggia e indomita su cui l'⟦Horde=Orda⟧ cerca di imporre la propria volontà, sia politica che spirituale. Se vuoi dimostrare il tuo valore in una terra ancora da conquistare, cerca la guida di ⟦Senani Thunderheart=Senani Cuore Tonante⟧ all'⟦Splintertree Post=Avamposto di Troncorotto⟧. L'avamposto si trova dritto a nord del sentiero che arriva dalle ⟦Barrens=Savane⟧.", nil, "Benvenut<o/a> nella nuova frontiera, {name}. ⟦Ashenvale=Valtetra⟧ è una terra di opportunità, dove un giovane {class} come te può trovare infinite occasioni per dimostrare il proprio valore. Dai un'occhiata all'avamposto e non mancare di spingerti fino alla ⟦Zoram Strand=Spiaggia di Zoram⟧, dove l'⟦Horde=Orda⟧ ha un altro avamposto.\n\nLa tua presenza qui mi dice che sei <venuto/venuta> per saperne di più sulla caccia. Ascolta bene, e ti dirò volentieri ciò che devi sapere.", 0x1bf465b8, 0x0a003978, 0xe968293f, nil, 0xedbc036b, "...m." },
  [6383] = { "La caccia di ⟦Ashenvale=Valtetra⟧", nil, nil, nil, "Sono tre le creature leggendarie che compongono la caccia di ⟦Ashenvale=Valtetra⟧; puoi cercarle e misurarti con la loro astuzia e la loro forza. Così facendo, spero, imparerai qualcosa su te stess<o/a>. Le creature sono: l'orso Ursangous, il felino notturno Shadumbra e l'ippogrifo ⟦Sharptalon=Grinfiafina⟧.\n\nLe creature della caccia di ⟦Ashenvale=Valtetra⟧ sono potenti, e potresti scoprire di aver bisogno di aiuto per abbatterle. Se riuscirai a sconfiggerle, portami la prova della tua impresa.", 0x1bf465b8, nil, nil, nil, 0x91a48cae, ".mmm." },
  [6384] = { "In volo verso Orgrimmar", "Paga una viverna per Orgrimmar al maestro delle viverne Devrak, poi porta ⟦Zargh's Meats=Carni di Zargh⟧ a Gryshka a Orgrimmar.", "Per poche monete farò in modo che una viverna ti porti a Orgrimmar. Quando arrivi, puoi consegnare la carne di Zargh a Gryshka. La sua locanda è nella ⟦Valley of Strength=Valle della Forza⟧, non lontano dalla Skytower, dove ti lascerà la mia viverna.\n\nParla di nuovo con me quando sei pront<o/a> per il viaggio.", "Che buon profumo! Non avrai mica della carne cruda addosso, vero?", "Oh, meraviglioso! Che tagli pregiati! Vengono da Zargh, vero? Quell'orco sa proprio come conquistare il cuore di una signora...\n\nOh, non vedo l'ora di cucinarla. Ma non troppo! La carne va servita al sangue, non credi?", 0x09e2c4f0, 0x68c9187c, 0x8879a481, 0x94e76fb4, 0x7fe221c3, "....." },
  [6385] = { "Doras, maestro delle viverne", "Porta la ⟦Gryshka's Letter=Lettera di Gryshka⟧ a Doras a Orgrimmar.", "Ho scritto una lettera di ringraziamento per Zargh. Me la consegneresti? Se sei già stat<o/a> a ⟦Crossroads=Crocevia⟧ e hai parlato con il loro maestro delle viverne, puoi tornarci in viverna.\n\nPorta la mia lettera a Doras, il maestro delle viverne di Orgrimmar, e parla con lui del trasporto fino a ⟦Crossroads=Crocevia⟧.", "Ti serve una delle mie viverne?", "Devi portare questa a ⟦Crossroads=Crocevia⟧, nelle ⟦Barrens=Savane⟧? Sì, posso portartici...", 0x9897a748, 0x9e96cb95, 0x96a2b1e4, 0x4b572cc6, 0xf84cda5f, "....." },
  [6386] = { "Ritorno a ⟦Crossroads=Crocevia⟧", "Paga una viverna per ⟦Crossroads=Crocevia⟧ al maestro delle viverne Doras, poi porta la ⟦Gryshka's Letter=Lettera di Gryshka⟧ a Zargh a ⟦Crossroads=Crocevia⟧.", "Le mie viverne sono addestrate a volare in molti luoghi diversi, purché tu ci sia già stat<o/a> e abbia parlato con il maestro delle viverne del posto.\n\nSei stat<o/a> a ⟦Crossroads=Crocevia⟧ e hai parlato con il loro maestro delle viverne, Devrak, quindi ora puoi volare direttamente da lui da qui. Una volta a ⟦Crossroads=Crocevia⟧, potrai consegnare la Lettera di Gryshka a Zargh.\n\nParla con me quando sei pront<o/a> a partire.", "Sei tornat<o/a> da Orgrimmar? A Gryshka è piaciuta la carne che le ho mandato?", "Ah! Direi che le è piaciuta! Niente fa arrossire le guance di una signora come una bella bistecca succosa!\n\nGrazie, {name}. Mi hai reso un grande servizio. Ecco un po' di denaro per il disturbo, e non stupirti se ti inviterò al mio matrimonio!", 0xb7e37b1d, 0xd651c4fc, 0x3d58c10b, 0x46394cd6, 0x69eb2cba, "....." },
  [6387] = { "Studenti meritevoli", "Porta Brock's List a Thorgrum Borrelson a Thelsamar.", "Vedo un sacco di giovani nani alla mia porta, ansiosi di imparare il mestiere del minatore. E se c'è una cosa di cui un minatore ha bisogno più di ogni altra, è un piccone!\n\nHo una lista di studenti di estrazione mineraria che hanno preso voti alti alle lezioni e si sono guadagnati un piccone d'onore. Porta la mia lista a ⟦Golnir Bouldertoe=Golnir Granditone⟧ a ⟦Ironforge=Forgiardente⟧. Lui preparerà i picconi.\n\nIl modo più rapido per arrivare a ⟦Ironforge=Forgiardente⟧ è in grifone, quindi porta la lista al nostro maestro dei grifoni, Thorgrum Borrelson, e parla con lui del trasporto fino a ⟦Ironforge=Forgiardente⟧.", "Ne hai già abbastanza di Thelsamar? Sei pront<o/a> a partire per un'altra città?", "Devi portare questa a ⟦Ironforge=Forgiardente⟧, eh? Per una piccola somma posso metterti in groppa a uno dei miei grifoni, e ti porterà lì. Che ne dici?", 0x24e749d7, 0xf62403c1, 0x57e23adf, 0x093769d9, 0xedf1dc2f, "....." },
  [6388] = { nil, "Porta i ⟦Honorary Picks=Picconi Onorari⟧ a Gryth Thurden a ⟦Ironforge=Forgiardente⟧.", "Ecco i picconi d'onore per gli studenti di Brock. Se sei già stat<o/a> a Thelsamar, dovresti tornarci in grifone!\n\nPorta i picconi al nostro maestro dei grifoni, Gryth Thurden, e parla con lui di un passaggio per tornare a Thelsamar.", "Hai l'aria di chi deve andare da qualche parte. Ti serve uno dei miei grifoni?", "Devi portare questi a Thelsamar, eh? Non sarà un problema. Se sei già stat<o/a> a Thelsamar e hai parlato con Thorgrum Borrelson, puoi prendere uno dei miei grifoni per tornare da lui.", 0x3b5086d2, 0x029c72cb, 0xc7801ddb, 0x4e09c9af, 0x721a7bfa, "e...." },
  [6389] = { "Che la piaga ti colga", "Libera le ⟦Plagueland Termites=Termiti delle Terre Infette⟧ nella ⟦Lumber Mill=Segheria⟧ di Cresta Nord, poi torna con il ⟦Barrel of Plagueland Termites=Barile di Termiti delle Terre Infette⟧ da Nathaniel Dumah all'⟦Chillwind Camp=Accampamento di Ventofreddo⟧, nelle ⟦Western Plaguelands=Terre Infette Occidentali⟧.", "Cerchi nella segheria qualcosa di adatto per aprire il barile. Trovi un piede di porco che sembra fare al caso tuo.\n\nPunti bene i piedi e preghi di riuscire a uscire dalla segheria prima che le termiti ti raggiungano.", "Ce l'hai fatta, {name}? Hai liberato le termiti? Che la Luce ci aiuti, se la ⟦Scarlet Crusade=Crociata Scarlatta⟧ riuscisse a tenersi sia la segheria sia ⟦Hearthglen=Valsalda⟧. Non dovrebbero avere né l'una né l'altra. Stanno solo approfittando delle vittime dell'ultima guerra e andrebbero abbattuti come bestie rabbiose!", "Ahah! Grazie, {name}! Ce l'hai fatta! Lo spirito di mio padre ora può riposare e io posso vivere in pace.\n\nGrazie ancora. Se c'è qualcosa che posso fare per te, ti prego, chiedi pure.", 0x4a22873d, 0x9d77a7f5, 0xb7edccdd, 0x5d5f831c, 0x34e8f1fe, "....." },
  [6390] = { "Che la piaga ti colga", "Libera le ⟦Plagueland Termites=Termiti delle Terre Infette⟧ nella ⟦Lumber Mill=Segheria⟧ di Cresta Nord, poi torna con il ⟦Barrel of Plagueland Termites=Barile di Termiti delle Terre Infette⟧ da Mickey Levine alla Granbarricata, nelle ⟦Tirisfal Glades=Radure di Tirisfal⟧.", "Cerchi nella segheria qualcosa di adatto per aprire il barile. Trovi un piede di porco che sembra fare al caso tuo.\n\nPunti bene i piedi e preghi di riuscire a uscire dalla segheria prima che le termiti ti raggiungano.", "Ce l'hai fatta, {name}? Hai liberato le termiti nella segheria?\n\nEra già abbastanza brutto che la mia famiglia avesse perso il lavoro e la vita, ma poi vedere il posto dove ho passato l'infanzia occupato da quei disgustosi cosiddetti uomini santi... puah!!", "Grazie, {name}. Ecco, prendi questa moneta. Mi dispiace che non sia di più, ma cerca di trovare un po' di gioia nell'aver contribuito a mandare all'aria i piani della Crociata Scarlatta!", 0x4a22873d, 0x6cc35569, 0xb7edccdd, 0x34476c17, 0x1d01326c, "....." },
  [6391] = { "In volo verso ⟦Ironforge=Forgiardente⟧", "Paga un grifone per ⟦Ironforge=Forgiardente⟧ al maestro dei grifoni Thorgrum Borrelson, poi porta ⟦Brock's List=Lista di Brock⟧ a ⟦Golnir Bouldertoe=Golnir Granditone⟧ a ⟦Ironforge=Forgiardente⟧.", "Per poche monete, uno dei miei grifoni ti porterà a ⟦Ironforge=Forgiardente⟧. Da lì, consegna la lista di Brock a ⟦Golnir Bouldertoe=Golnir Granditone⟧. Lo troverai nella Deep Mountain Mining Guild. Si trova nel distretto della ⟦Great Forge=Grande Forgia⟧ di ⟦Ironforge=Forgiardente⟧, proprio dove ti lascerà il mio grifone!\n\nParla di nuovo con me quando sei pront<o/a> per il viaggio.", "Cosa posso fare per te, <signore/signora>?", "Ah, l'ultima lista dei migliori allievi di Brock. Ho una partita di picconi d'onore pronta. Devo solo incidere i nomi degli studenti...", 0xd28081ed, 0x0477c979, 0x2cfa2e26, 0x92c650dc, 0xe778e783, ".....", nil, nil, nil, 0xd6deda79, nil },
  [6392] = { "Ritorno da Brock", "Compra un volo in grifone per Thelsamar dal maestro di grifoni Gryth Thurden, poi porta i ⟦Honorary Picks=Picconi Onorari⟧ a ⟦Brock Stoneseeker=Brock Scrutarocce⟧, a Thelsamar.", "Con una piccola somma puoi comprare un volo in grifone fino a Thelsamar... sempre che tu ci sia già <stato/stata>. I grifoni ti portano solo nei posti dove sei già <stato/stata>, quindi assicurati di parlare con ogni maestro di grifoni che incontri, così potrai volare da lui in seguito.\n\nSei già <stato/stata> da Thorgrum, il maestro di grifoni di Thelsamar, quindi ora puoi tornare da lui. E una volta a Thelsamar, potrai consegnare i picconi a ⟦Brock Stoneseeker=Brock Scrutarocce⟧.\n\nParla con me quando sei <pronto/pronta> a partire.", "Ah, {name}. Sei <tornato/tornata> da ⟦Ironforge=Forgiardente⟧?", "Hai portato i picconi. Ottimo! Li darò ai miei allievi minatori. Sono sicuro che non vedono l'ora di usarli sui giacimenti di Loch Modan.\n\nGrazie per il tuo aiuto, {name}. Sono in debito con te, ma spero che questo denaro copra almeno le spese di viaggio.", 0xe9291a93, 0xd370798c, 0x72505319, 0x7b4723d5, 0xf9547062, "....." },
  [6393] = { "Guerra elementale", "Porta 10 Incendrites a Tsunaman al ⟦Sun Rock Retreat=Rifugio Roccia del Sole⟧.", "Il Tribunal of the Tides mi ha mandato a muovere guerra agli elementali del fuoco qui a ⟦Stonetalon=Petrartiglio⟧. Neptulon the Tidehunter, signore di tutti gli elementali dell'acqua, ha a cuore personalmente lo spegnimento dei nostri focosi cugini.\n\n{name}, puoi aiutarmi a guadagnare il favore del Tribunal distruggendo gli elementali del fuoco nella ⟦Charred Vale=Valle Bruciata⟧. Quando vengono distrutti, gli elementali del fuoco lasciano delle Incendrites. Riportamele e sarai <ricompensato/ricompensata>.", "Il Tribunal of the Tides si spazientisce. Vuole porre fine a questa guerra che infuria in tutte le dimensioni da eoni. I miei fratelli sono ansiosi di ricevere notizie della gloriosa vittoria sugli odiati elementali del fuoco. Hai le Incendrites che mi servono?", "Gli spiriti dell'acqua dentro di me ribollono di eccitazione. {name}, mi hai dato una vittoria gloriosa da riferire al Tribunal of the Tides.", 0x3a960821, 0xdd0e499d, 0x3bd6600f, 0xb2453512, 0xedacdfd1, "....." },
  [6394] = { "⟦Thazz'ril's Pick=Piccone di Thazz'ril⟧", "Porta il ⟦Thazz'ril's Pick=Piccone di Thazz'ril⟧ al caposquadra Thazz'ril.", "{name}, sei un {race} affidabile. Posso contare su di te per un altro compito?\n\nTempo fa stavo esplorando la grotta a nord in cerca di minerali e ho dimenticato lì il mio piccone preferito. Quando sono tornato a riprenderlo, ho trovato la grotta piena di bestie feroci! Andresti nella grotta, il ⟦Burning Blade Coven=Covo delle Lame Ardenti⟧, a recuperare il mio piccone?\n\nL'ho lasciato in una caverna con delle cascate. Sul mio piccone c'è un incantesimo che lo rende visibile al buio, quindi non dovrai preoccuparti di trovarlo... solo di ciò che lo sorveglia!", "Sei entrat<o/a> nel ⟦Burning Blade Coven=Covo delle Lame Ardenti⟧, {name}? Hai trovato il mio piccone?", "Grande, l'hai trovato! Grazie mille, {name}. È il mio piccone preferito! Ora, se i miei peoni finiranno mai di abbattere questi alberi, forse potremo trovare una bella grotta da scavare!", 0xcb16d6a3, 0x42cbea5f, 0x69e4753a, 0x8afd7942, 0x66e27461, "....." },
  [6395] = { "L'ultimo desiderio di Marla", "Porta i Samuel Fipps' Remains alla tomba di Marla, poi torna dalla novizia Elreth.", "La mia amica Marla Fipps viveva con suo marito Samuel prima della pestilenza, ma quando arrivò la pestilenza Samuel soccombette e si unì alle file del Flagello.\n\nMarla fu risparmiata dalla non morte, solo per morire per mano di suo marito, ormai senza mente. Il suo amore però era così forte che il suo ultimo desiderio fu di essere sepolta con il suo amato Samuel.\n\nSamuel Fipps vaga in un accampamento in rovina lungo la strada a nord-est di ⟦Deathknell=Albamorta⟧. Sconfiggilo ed esaudisci il desiderio di Marla: seppelliscilo nella sua tomba, nella prima fila del nostro cimitero.", "Dobbiamo rispettare i nostri morti, {name}. È uno dei modi in cui siamo diversi dal Flagello...", "Oggi hai compiuto una buona azione, {name}. Anche se la nostra lotta contro il Flagello continua, speriamo che Marla e Samuel trovino pace insieme nel loro ultimo luogo di riposo. Come segno della mia gratitudine, prendi uno di questi manuali che ho trovato.", 0x3ab505f6, 0x48105831, 0xe3b59356, 0xae4dd1f3, 0x4b279a4a, "....." },
  [6401] = { "Kaya è viva", "Porta la buona notizia a ⟦Tammra Windfield=Tammra Vento Piatto⟧, al ⟦Sun Rock Retreat=Rifugio Roccia del Sole⟧.", "Porta la buona notizia a ⟦Tammra Windfield=Tammra Vento Piatto⟧, la zia di Kaya, che si trova al ⟦Sun Rock Retreat=Rifugio Roccia del Sole⟧! Kaya è viva! La credevamo perduta dopo il brutale attacco al nostro villaggio. Segui il sentiero verso ovest per arrivare al ⟦Sun Rock Retreat=Rifugio Roccia del Sole⟧.", nil, "Santo cielo, mia nipote Kaya è viva! È davvero una bella notizia. Grazie, {name}.", 0x29fb8709, 0x1e4fb9d8, 0x9edc231d, nil, 0xce73e720, "...m." },
  [6402] = { "Appuntamento a ⟦Stormwind=Roccavento⟧", "Raggiungi ⟦Stormwind City=Roccavento⟧ e recati alle porte della città. Parla con lo scudiero Rowe, così che possa avvisare il maresciallo Windsor del tuo arrivo.", "Devi incontrare Windsor alle porte di ⟦Stormwind=Roccavento⟧.\n\nCiò che Windsor sta per svelare scuoterà le fondamenta stesse del regno!\n\nNon tentare di andarci da sol<o/a>, {name}. Devi radunare un esercito! Raccogli i tuoi compagni. Alle armi!", nil, "Prima di cominciare, ti chiedo di radunare un esercito. Dopotutto, affrontiamo un drago!", 0x1af12cc7, 0x59fa1490, 0xdcffa17a, nil, 0x9b717b87, "...m." },
  [6403] = { "La grande mascherata", "Segui Reginald Windsor attraverso ⟦Stormwind=Roccavento⟧. Proteggilo da ogni pericolo!", "È stata proprio un'avventura, amico. Ho con te un grande debito di gratitudine. Forse, quando tutto sarà finito...\n\nCome avrai certamente capito, Lady Prestor è Onyxia, Progenie di Alamorte, gemella del tiranno dei Bastioni, Nefarian.\n\nPer troppo tempo ha tenuto il nostro regno prigioniero del suo sguardo ammaliatore. Persino il gran signore è controllato dai suoi inganni: una marionetta. Oggi tutto finisce... L'incantesimo sarà spezzato.\n\nNon temere: insieme vinceremo!\n\nSei <pronto/pronta>?", "Io... io... ero impotente.", "<Bolvar tiene in mano il medaglione infranto.>\n\nLa magia racchiusa al suo interno va riaccesa. L'occhio del drago va sintonizzato.\n\nIl sacrificio di Windsor ha liberato il nostro regno, ma la minaccia di Onyxia e della sua stirpe incombe ancora.\n\nQuesto medaglione è ciò che teneva prigionieri la mia mente e il mio corpo. È anche ciò che mi ha dato accesso alla mente di Onyxia, ai suoi segreti. Anche se ora le visioni sono confuse, alcune cose le ricordo.", 0x21125223, 0x83f7ff7b, 0x5c12f001, 0x98e54ef8, 0x76253855, "....." },
  [6421] = { "⟦Boulderslide Ravine=Gola dei Franamassi⟧", "Esplora a fondo la caverna della ⟦Boulderslide Ravine=Gola dei Franamassi⟧ e riporta 10 Cristallo di Resonite a Mor'rogal, al ⟦Sun Rock Retreat=Rifugio Roccia del Sole⟧, perché possa esaminarli.", "Qualcosa non va qui a ⟦Stonetalon=Petrartiglio⟧. Senti la tensione nell'aria, {name}?\n\nA sud-est di qui, nella ⟦Boulderslide Ravine=Gola dei Franamassi⟧, c'è una caverna profonda. I coboldi là dentro stanno estraendo freneticamente un cristallo raro chiamato Resonite. Ho bisogno che tu mi porti qualche campione di minerale, così che io possa capire cosa sta succedendo in quella caverna. Devo anche sapere quanto è profonda.\n\nVa', giovane {class}: è fondamentale che io sappia quale male si annida sotto queste montagne.", "Che notizie hai scoperto nella ⟦Boulderslide Ravine=Gola dei Franamassi⟧? Ricordo una leggenda che riguarda la Resonite... ma proprio non riesco a metterci lo zoccolo sopra. Forse sapere cosa si trova in fondo alla caverna farà luce sulle loro subdole intenzioni.", "Ah... Sì! Ecco cos'è: i cristalli di Resonite contengono una traccia di magia Terrigena. I coboldi devono aver scavato in profondità e portato alla luce un Terrigeno.\n\nLa leggenda narra che i Terrigeni siano creature create dai Titani. Furono usati per plasmare la terra su cui camminiamo. Questa è senza dubbio una minaccia che non si può ignorare.\n\n<Mor'rogal scuote la testa.>\n\nForse posso incantare questi campioni di minerale per usarli contro il piano dei coboldi.", 0xafc62dde, 0x052e328b, 0x4270ef12, 0x9806d736, 0x1da30e95, "....." },
  [6441] = { "⟦Satyr Horns=Corna di Satiro⟧", "Raccogli 16 ⟦Satyr Horns=Corna di Satiro⟧ per Pixel, all'⟦Splintertree Post=Avamposto di Troncorotto⟧.", "Ehilà! Sto attraversando ⟦Ashenvale=Valtetra⟧ verso ⟦Ratchet=Porto Paranco⟧, e ho deciso di fare una sosta qui a Troncorotto. Cerco sempre buone occasioni, e pare che di questi tempi le corna di satiro siano molto richieste a ⟦Ratchet=Porto Paranco⟧.\n\nA forza di chiedere in giro, ho scoperto che i satiri di ⟦Night Run=Jorxian⟧, ⟦Satyrnaar=Satirnaar⟧ e Xavian hanno tutti il tipo di corna che cerco. Io non sono all'altezza di quei satiri... ma tu sembri esserlo!\n\nFacciamo così: tu raccogli le corna per me e io farò in modo che ne valga la pena.", "Spero che tu possa sbrigarti a prendere quelle corna, {name}. Tra poco riparto per ⟦Ratchet=Porto Paranco⟧!", "Sono perfette, {name}! Grazie dell'aiuto!\n\nOh, e questo è per il tuo tempo...", 0x13e94a31, 0xa22e7d9d, 0xe3adeab3, 0x61d72bfb, 0x68f77641, "....." },
  [6442] = { "Naga alla ⟦Zoram Strand=Spiaggia di Zoram⟧", "Porta 20 Testa di Codaguzza a Marukai, lungo la ⟦Zoram Strand=Spiaggia di Zoram⟧.", "Il male si annida qui lungo la costa, {race}.\n\nLì riposa la città perduta di Zoram, distrutta tanto tempo fa e sommersa dai mari. Perduta, e quasi dimenticata.\n\nOra i naga sono tornati, e non sappiamo per quale motivo. Ma il motivo conta poco: dobbiamo difendere la terra che abbiamo tanto faticato a conquistare.\n\nTorna da me con 20 delle loro teste! Ricaccia i naga negli abissi!", "I naga aumentano di numero, {name}. Ti prego, porta a termine questo compito per me.", "Ci servirebbero più tipi come te da queste parti, {name}. Grazie per l'aiuto.", 0x4fd49e58, 0x910e5478, 0x1629860a, 0x3e533dbd, 0x06b6f56f, "....." },
  [6461] = { "Succhiasangue", "Xen'zilla, a Malaka'Jin, ha bisogno che tu uccida 10 Deepmoss Creeper e 7 Deepmoss Venomspitter.", "Noi Troll qui a Malaka'Jin abbiamo prosperato grazie alla terra; le montagne di ⟦Stonetalon=Petrartiglio⟧ offrono ottima caccia per vivere.\n\nUltimamente però abbiamo attirato gli ospiti a cena sbagliati... i ragni di queste montagne assaltano i nostri accampamenti di notte per rubarci le prede.\n\nSe ci aiutassi a sterminare queste bestie orrende, noi di Malaka'Jin saremmo in debito con te. I ragni sono dappertutto a ⟦Stonetalon=Petrartiglio⟧: basta che vai a nord da qui e capirai di cosa parlo.", "Ehi, amico, hai fatto fuori quei pelosi succhiasangue? Io non temo niente qui a ⟦Stonetalon=Petrartiglio⟧, ma di notte non me ne vado in giro... se capisci cosa intendo, amico!\n\nFinché non finisco nel loro piatto, va tutto bene.\n\nBuona fortuna, {class}!", "Grande, amico! Buone notizie: forse stanotte avremo meno ospiti indesiderati a cena.\n\nMolte grazie, {name}. Saremo per sempre in debito con te.", 0x290dc497, 0x3dbb349e, 0x44275372, 0xf8a245cd, 0x831e4ebe, "....." },
  [6462] = { "Il ⟦Troll Charm=Talismano Troll⟧", "Porta 8 Talismano Troll a Mitsuwa, all'⟦Zoram'gar Outpost=Avamposto di Zoram'gar⟧.", "I miei parenti stavano venendo qui con molti talismani troll sacri, ma i mezzorsi Mantocardo li hanno attaccati e uccisi prima che raggiungessero Zoram'gar! Maledetti mezzorsi!\n\nMi mancano i miei fratelli e le mie sorelle uccisi, ma ci rivedremo nell'aldilà. I loro talismani troll, però, hanno un grande valore in questo mondo. È un oltraggio che ce li abbiano i mezzorsi!\n\n{name}, devi recuperare i talismani! Sono nei forzieri di Thistlefur Hold, una caverna in fondo al ⟦Thistlefur Village=Villaggio dei Mantocardo⟧, a nord di Astranaar.", "Hai trovato i talismani, {name}? Ogni momento in cui quei mezzorsi possiedono gli oggetti sacri, il sangue mi ribolle di rabbia!", "Li hai trovati! Grazie! Grazie, {name}! Non sai che grande cosa hai fatto per me.\n\nUn troll senza il suo talismano è come un orco senza le sue cicatrici di battaglia...\n\nNon vale niente.", 0x1223bf18, 0xb6fd8480, 0xca22eb96, 0x9c67b26c, 0x762ff9ab, ".....", nil, nil, nil, nil, 0x8502d612 },
  [6481] = { "Sorgi, Terrigeno", "Apri il barile di Resonite con il ⟦Enchanted Resonite Crystal=Cristallo di Resonite Incantato⟧, poi uccidi Goggeroc. Torna da Mor'rogal con la notizia e il ⟦Enchanted Resonite Crystal=Cristallo di Resonite Incantato⟧.", "Hai scoperto una minaccia oscura per questa terra, {class}. Il barile di Resonite che hai trovato in quella grotta racchiude un Terrigeno addormentato di nome Goggeroc.\n\nCon i miei poteri sciamanici ho modificato la miscela dei cristalli di Resonite che hai raccolto. Prendi il cristallo di Resonite incantato e sfonda il barile di Resonite che racchiude il Terrigeno.\n\nAl risveglio, Goggeroc sarà indebolito... Uccidilo, {name}!", "Temo che, se non eliminiamo subito questa minaccia, tutta ⟦Stonetalon=Petrartiglio⟧ sarà perduta. La potenza di un Terrigeno non può essere eguagliata in alcun modo. Al risveglio, Goggeroc sarà debole per il lungo sonno: questa è l'occasione che devi sfruttare... va', {name}!", "Porti buone notizie, {class}! Temevo ciò che un Terrigeno avrebbe potuto significare per Kalimdor.\n\nUccidere Goggeroc era un compito che solo un eroe poteva affrontare. Hai fatto bene; tutta ⟦Stonetalon=Petrartiglio⟧ e tutto Kalimdor sono in debito con te, nobile {class}.\n\nAccetta questa ricompensa, tu che sei tra i più onorati.", 0xab18846e, 0xe822594e, 0x79cb0289, 0x6c9c4921, 0x50265ed0, "....." },
  [6482] = { "Libertà per Ruul", "Scorta Ruul, poi parla con ⟦Yama Snowhoof=Yama Zoccolo Nevoso⟧ all'Avamposto di Troncorotto.", "Eh? Chi sei?\n\n{name}? Non sei un mezzorso. Sono maledetti! Mi hanno scambiato per un orso e mi hanno catturato, e ora mi lasciano morire di fame! Le forze mi abbandonano...\n\nAiutami a fuggire, poi parla con mia sorella Yama all'⟦Splintertree Post=Avamposto di Troncorotto⟧, a est.\n\n{name}! Devo fuggire!", "Hai visto mio fratello Ruul? È andato nella foresta giorni fa e non è più tornato...", "Hai trovato mio fratello! Era stato catturato dai Mantocardo? È una terribile notizia, perché sebbene molti mezzorsi siano creature nobili, i Mantocardo sono corrotti.\n\nGrazie per aver salvato mio fratello, {name}. Non voglio pensare a come hanno trattato il povero Ruul. Probabilmente dormirà a lungo dopo questa prova...", 0x07e8ff56, 0xbbd83e57, 0x2a3becff, 0x07ac7df4, 0xa4fa8915, "....." },
  [6501] = { "L'Occhio di Drago", "Devi cercare per il mondo un essere capace di ridare potere al ⟦Fragment of the Dragon's Eye=Frammento dell'Occhio di Drago⟧. L'unica cosa che sai di un tale essere è che esiste.", "Un frammento del medaglione infranto è tutto ciò che posso offrirti.\n\nDevi trovare un altro essere di sangue draconico disposto ad aiutarti a forgiare una nuova chiave. Una volta ottenuta questa chiave, dovrai raggiungere il ⟦Wyrmbog=Brago dei Dragoni⟧, ad ⟦Dustwallow Marsh=Acquemorte⟧. È lì che troverai la sua tana, {name}.\n\nDove trovare altri stormi disposti ad aiutarti? Purtroppo non lo so... Si dice che esistano. Alcuni potrebbero persino vivere e lavorare tra noi, travestiti da membri delle razze umanoidi. Ti auguro buona fortuna.", "Percepisco un'aura malvagia che si irradia da te, {race}. Cosa puoi avere con te che emani un'aura simile?", "Avrei dovuto saperlo: un pezzo della madre della covata dei draghi neri, Onyxia. Che ripugnanza...", 0x667cb580, 0xc8568b34, 0x01f50423, 0x28f8fcf6, 0xb8659b7f, "....." },
  [6502] = { "⟦Drakefire Amulet=Amuleto Fuocodraco⟧", "Devi recuperare il ⟦Blood of the Black Dragon Champion=Sangue del Campione dei Draghi Neri⟧ dal generale Drakkisath. Drakkisath si trova nella sua sala del trono, oltre le Sale dell'Ascesa, nei ⟦Blackrock Spire=Bastioni di Roccianera⟧.", "È un pezzo del drago: una scaglia, incantata e trasformata. Intera, avrebbe potuto darti accesso alla tana della bestia. Frantumata, è inutile.\n\nÈ possibile riparare l'oggetto, ma per farlo servirebbe il sangue di un campione dei draghi neri. Ce n'è uno... È noto come generale Drakkisath, signore degli eserciti di dragobestie di Nefarian. Forse ne hai sentito parlare?\n\nTorna con il suo sangue, {race}, e incanterò il frammento trasformandolo in qualcosa che ti darà accesso all'Antro di Onyxia.", "Lo scorrere del tempo non si ferma né rallenta, {race}. La mia vita è eterna, la tua no. Non sprecare il tempo che hai...", "Questo amuleto ti darà l'accesso che cerchi. L'Antro di Onyxia si trova ad ⟦Dustwallow Marsh=Acquemorte⟧. Finché avrai l'amuleto, le sue protezioni non potranno impedirti di entrare.\n\nLo Stormo dei Draghi Blu ti augura buona fortuna, {name}.", 0xd4865526, 0x0799ee5c, 0x52080e65, 0xc80f986c, 0xb1ae724c, "....." },
  [6503] = { "Staffette di ⟦Ashenvale=Valtetra⟧", "Uccidi 9 Ashenvale Outrunner, poi torna da Kuray'bin all'Avamposto di Troncorotto.", "Ci è giunta voce che delle staffette di ⟦Ashenvale=Valtetra⟧ hanno lasciato l'⟦Silverwing Outpost=Avamposto degli Alargentea⟧ non molto tempo fa e ora si aggirano vicino ai nostri territori nella foresta. Non vogliamo che raccolgano informazioni sulle nostre difese!\n\nMuoviti furtivamente nelle foreste a sud del nostro avamposto e a est dell'⟦Silverwing Outpost=Avamposto degli Alargentea⟧ dell'⟦Alliance=Alleanza⟧. Trova le staffette, uccidile e torna da me.", "Aspetto il rapporto sulle staffette che hai ucciso, {name}.", "Molto bene, {name}. Le tue doti di caccia sono notevoli...\n\nLa perdita di quelle staffette aiuta ad accecare l'⟦Alliance=Alleanza⟧, e quando le mancano informazioni è meno probabile che lanci attacchi.", 0xf39e3da0, 0x8183eec6, 0xa48ee277, 0xd2a0ba0a, 0x681f0b9e, "....." },
  [6504] = { "Le pagine perdute", "Trova le 12 pagine mancanti dello Shredder Operating Manual e riuniscile per formare i Capitoli 1, 2 e 3. Riporta le pagine a ⟦Gurda Ragescar=Gurda Sfregiarabbia⟧, vicino all'⟦Splintertree Post=Avamposto di Troncorotto⟧.", "Ho appena ritirato questo segatronchi a ⟦Ratchet=Porto Paranco⟧ e stavo tornando al ⟦Warsong Lumber Camp=Campo di Taglio dei Cantaguerra⟧, dove dovrei essere di servizio. Mi avevano dato un manuale per usare il segatronchi, ma durante il viaggio una fortissima raffica di vento me l'ha strappato di mano. Le pagine sono volate dappertutto e mi è rimasta solo la copertina.\n\nOrmai le pagine potrebbero essere ovunque, immagino... ma senza di loro non so come usare il segatronchi! Me le ritrovi tu?", "Spero che troverai presto le pagine, {name}! Devo proprio tornare al lavoro!", "Leggere non è il mio forte... ma ora potrò tornare al lavoro! Grazie, {name}!", 0x7e77aef8, 0xb708cd13, 0xda8de124, 0x72e48f8c, 0xf9144af7, "....." },
  [6521] = { "Un'empia alleanza", "Porta la ⟦Ambassador Malcin's Head=Testa dell'Ambasciatore Malcin⟧ a Varimathras a ⟦Undercity=Sepulcra⟧.", "Malcin sostiene di trovarsi fuori dai ⟦Razorfen Downs=Sotterranei di Lamaspina⟧. Questo ambasciatore deve essere ucciso: la sua missione sarà un fallimento agli occhi del Re dei Lich.\n\nLa sua presenza laggiù spiega molto di ciò che abbiamo scoperto sulla zona: alcuni verrospini sono diventati spaventosamente potenti, pur mostrando a modo loro i segni della Piaga. Dev'essere davvero il segno di una sorta di patto che hanno stretto.\n\nTrova Malcin e uccidilo, {name}. Torna da me quando l'opera sarà compiuta.", "Hai trovato l'ambasciatore, {name}? È morto?\n\nNon possiamo permetterci che il Flagello metta piede a Kalimdor. È già abbastanza minaccioso ai nostri confini senza doverlo affrontare su due fronti.\n\nL'unico segnale incoraggiante in ciò che mi hai raccontato è che la vecchia strega non sembrava corrotta. Nel profondo del suo spirito deve sapere che il Flagello può portare grande potere, ma che le ⟦Barrens=Savane⟧ non sarebbero mai davvero sue se accettasse il loro patto.", "Bene. Ben fatto, {class}.\n\nOra che Malcin è morto, almeno sappiamo che l'avanzata del Flagello sarà fermata. La Dama Oscura ti ringrazia per i tuoi sforzi e desidera ricompensarti con un dono.\n\nAnche se non conosciamo la portata dell'influenza del Flagello nei Sotterranei, sono certo che scopriremo presto i loro piani.", 0x53428ea7, 0xef1f9f41, 0xb67a641e, 0xa04317a5, 0xcfe31419, "....." },
  [6522] = { "Un'empia alleanza", "Porta la ⟦Small Scroll=Pergamena Piccola⟧ a Varimathras a ⟦Undercity=Sepulcra⟧.", "Mia Signora,\n\nSapete benissimo che cosa vi offriamo. L'occasione di prendere le ⟦Barrens=Savane⟧ e le terre più in là è grande. In cambio vogliamo soltanto il vostro aiuto. E per aiuto non intendiamo altro che la libertà di agire nella zona.\n\nVi prego, permetteteci di discuterne ancora. Abbiamo un grande potere e siamo disposti a condividerlo con chi è abbastanza saggio da unirsi a noi. Per il momento resterò fuori dai ⟦Razorfen Downs=Sotterranei di Lamaspina⟧.\n\nCordiali saluti,\n\nAmbasciatore Malcin", "Di quale faccenda vuoi parlare, {name}? Dev'essere importante, se continui a importunarmi.", "Riconosco lo stemma su questa pergamena, {name}. L'hai trovata su quella vecchia strega che regna sulle ⟦Razorfen Kraul=Gallerie di Lamaspina⟧? Interessante.\n\nA quanto pare il Flagello non si accontenta di un solo continente. Questo ambasciatore Malcin, quello che ha scritto il messaggio, è uno dei servitori appestati del Flagello, un diplomatico umano presso il regno di Lordaeron prima che le cose... cambiassero.\n\nSe il Flagello sta cercando di mettere piede a Kalimdor, allora tocca a noi agire.", 0x53428ea7, 0x6a61a5a5, 0xd95a6bbf, 0x16f8387f, 0x29ba3722, "....." },
  [6523] = { "Proteggi Kaya", "Scorta ⟦Kaya Flathoof=Kaya Zoccolo Piatto⟧ fino all'⟦Camp Aparaje=Accampamento Aparaje⟧, poi torna da ⟦Makaba Flathoof=Makaba Zoccolo Piatto⟧, vicino al margine sud-orientale di ⟦Stonetalon=Petrartiglio⟧.", "Grazie per avermi salvata! Dobbiamo andarcene in fretta, prima che scoprano che sono libera. Ti prego, scortami fino all'⟦Camp Aparaje=Accampamento Aparaje⟧. Da lì so la strada.\n\nMio padre, ⟦Makaba Flathoof=Makaba Zoccolo Piatto⟧, sarà disperato di sapere che sono al sicuro.", nil, "Kaya è viva! {name}, devo a te il suo salvataggio.", 0x15129e83, 0xe5af41d4, 0xd4cff830, nil, 0x59df4b81, "...m." },
  [6541] = { "Rapporto a Kadrak", "Fai rapporto a Kadrak, alla torre di guardia nelle ⟦Barrens=Savane⟧ settentrionali.", "Sei mai stat<o/a> a ⟦Ashenvale=Valtetra⟧, a nord? L'Orda ha da poco stabilito un avamposto sulla ⟦Zoram Strand=Spiaggia di Zoram⟧, e ci servono sempre nuove reclute per difendere i nostri nuovi fronti.\n\nSe te la senti, va' da Kadrak nelle ⟦Barrens=Savane⟧ settentrionali, alla torre di guardia. È lui a guidare la campagna di ⟦Ashenvale=Valtetra⟧ e potrà darti altri ordini.", nil, "⟦Ashenvale=Valtetra⟧ è una terra divisa, ma i nostri ultimi sforzi hanno avuto molto successo. Non solo abbiamo un avamposto sulla ⟦Zoram Strand=Spiaggia di Zoram⟧, ma anche un altro poco più a nord di qui, chiamato Troncorotto.", 0x76d74aab, 0x6b18afa9, 0xea704af2, nil, 0x79ee031c, "...m." },
  [6542] = { "Rapporto a Kadrak", "Fai rapporto a Kadrak, alla torre di guardia nelle ⟦Barrens=Savane⟧ settentrionali.", "Sei mai stat<o/a> a ⟦Ashenvale=Valtetra⟧, a nord? L'Orda ha da poco stabilito un avamposto sulla ⟦Zoram Strand=Spiaggia di Zoram⟧, e ci servono sempre nuove reclute per difendere i nostri nuovi fronti.\n\nSe te la senti, va' da Kadrak nelle ⟦Barrens=Savane⟧ settentrionali, alla torre di guardia. È lui a guidare la campagna di ⟦Ashenvale=Valtetra⟧ e potrà darti altri ordini.", nil, "⟦Ashenvale=Valtetra⟧ è una terra divisa, ma i nostri ultimi sforzi hanno avuto molto successo. Non solo abbiamo un avamposto sulla ⟦Zoram Strand=Spiaggia di Zoram⟧, ma anche un altro poco più a nord di qui, chiamato Troncorotto.", 0x76d74aab, 0x6b18afa9, 0xea704af2, nil, 0x79ee031c, "...m." },
  [6543] = { "I rapporti dei ⟦Warsong=Cantaguerra⟧", "Apri il ⟦Bundle of Reports=Fascicolo di Rapporti⟧. Porta i Rapporti dei ⟦Warsong=Cantaguerra⟧ al ⟦Warsong Scout=Esploratrice Cantaguerra⟧, al ⟦Warsong Runner=Messaggero Cantaguerra⟧ e al ⟦Warsong Outrider=Predona Cantaguerra⟧. Riporta gli aggiornamenti che ti daranno a Kadrak, alla torre di guardia settentrionale nelle Savane.", "Di recente ho mandato alcuni esploratori a ⟦Ashenvale=Valtetra⟧ e mi serve un messaggero che porti loro gli ordini e mi riporti un rapporto su ciò che hanno osservato.\n\nLa tua prima tappa dev'essere l'⟦Zoram'gar Outpost=Avamposto di Zoram'gar⟧, lungo la costa a ovest, sulla ⟦Zoram Strand=Spiaggia di Zoram⟧, per trovare il primo messaggero. Devi fermarti anche all'⟦Splintertree Post=Avamposto di Troncorotto⟧, a nord, e lungo la strada a est, vicino ad Azshara. Lì troverai un esploratore e un battistrada.\n\nDai a ciascuno un rapporto e fatti dare un aggiornamento su ciò che hanno scoperto.", "Sbrigati, {name}. Devono ricevere i loro rapporti; è urgente.", "Vedo che sei una persona su cui si può contare. Questi aggiornamenti sono cruciali per i nostri piani di rafforzare la nostra presenza a ⟦Ashenvale=Valtetra⟧. Ora possiamo pianificare la prossima mossa.", 0xf2bef2e2, 0xff13d2f5, 0x7d33a1a0, 0xe0ca1342, 0xd9ec4538, "....." },
  [6544] = { "L'assalto di Torek", "Scorta Torek nel suo attacco all'⟦Silverwing Outpost=Avamposto degli Alargentea⟧ e a ⟦Duriel Moonfire=Duriel Lunardente⟧, poi fai rapporto a ⟦Ertog Ragetusk=Ertog Zannacrudele⟧ all'⟦Splintertree Post=Avamposto di Troncorotto⟧.", "Ehi! {class}! Vieni qui!\n\nIo e i miei predoni stiamo per attaccare l'⟦Silverwing Outpost=Avamposto degli Alargentea⟧, a ovest. Il nostro obiettivo è il loro capo, ⟦Duriel Moonfire=Duriel Lunardente⟧. Gli esploratori dicono che l'avamposto è ben difeso da sentinelle e guerrieri. Sarà una battaglia gloriosa!\n\nVuoi avere la tua parte di gloria, {name}, e aiutarci? Se sì, quando sarà finita potrai riferire il nostro successo al mio superiore, ⟦Ertog Ragetusk=Ertog Zannacrudele⟧, a Troncorotto.\n\nAllora, che dici? Sei con noi?", "Torek è stato mandato in missione contro l'⟦Silverwing Outpost=Avamposto degli Alargentea⟧. L'attacco è riuscito?", "Allora l'attacco di Torek è riuscito! Ben fatto, {name}. Gli elfi della notte sono avversari degni. Un po' mingherlini, ma forti e feroci! Sono sicuro che la battaglia è stata uno spettacolo...\n\nE spero che tu ti sia guadagnat<o/a> una cicatrice o due!", 0xfb0fc804, 0xc94c7a08, 0x19b8d053, 0x6063f367, 0x83edb91d, "....." },
  [6545] = { "⟦Warsong Runner Update=Aggiornamenti dal Messaggero dei Cantaguerra⟧", nil, nil, "Quindi sei qui con i miei ordini? È sempre un piacere vedere una nuova recluta piena di entusiasmo e di forte volontà.\n\nFaresti meglio a imparare in fretta, se vuoi tenere il passo qui. La minaccia dei naga cresce, {name}. Da quando sono arrivato ho osservato e respinto diversi attacchi contro questo avamposto.\n\nMa se vuoi dare una mano in questa impresa, parla con uno degli altri qui all'avamposto.", "Bene, il mio rapporto spiegherà tutto questo a Kadrak. Devi riportarglielo il prima possibile.", 0x6770a57c, nil, nil, 0x51947fed, 0x7f206db5, ".mm.." },
  [6546] = { "⟦Warsong Outrider Update=Aggiornamenti dal Predone Cantaguerra⟧", nil, nil, "Lungo questa strada si annidano molti pericoli, {name}. Faresti bene a ricordartelo mentre viaggi per queste terre. La minaccia dell'Alleanza è molto vicina.\n\nAbbiamo nemici su tutti i fronti. I satiri sono una forza temibile e diffusa nella parte orientale di ⟦Ashenvale=Valtetra⟧. Ho anche scoperto che i naga hanno occupato una vasta area della terra di Azshara.\n\nÈ bello vedere che i nostri ranghi continuano a ingrossarsi: tieniti pront<o/a> per ciò che ci aspetta, {name}.", "Porta il mio aggiornamento a Kadrak. In fretta, {name}.", 0x1f297912, nil, nil, 0x30116780, 0x6bdc5b6a, ".mm.." },
  [6547] = { "⟦Warsong Scout Update=Aggiornamenti dall'Esploratore dei Cantaguerra⟧", nil, nil, "Tieni gli occhi aperti, {race}. Gli elfi si nascondono spesso nell'ombra...\n\nDobbiamo restare sempre all'erta. Abbiamo lavorato sodo per conquistare questa terra, e gli elfi cercano l'occasione per strapparcela.\n\nImmagino che tu abbia i miei nuovi ordini da Kadrak?", "Fai sapere a Kadrak del successo che abbiamo avuto qui nel tenere a bada gli elfi della notte. I nostri piani procedono bene.", 0x3bb2bdcc, nil, nil, 0xb90a3cda, 0x056a033a, ".mm.." },
  [6548] = { "Vendica il mio villaggio", "Uccidi 8 Grimtotem Ruffian e 6 Grimtotem Mercenary, poi torna da ⟦Makaba Flathoof=Makaba Zoccolo Piatto⟧, vicino al margine sud-orientale di ⟦Stonetalon=Petrartiglio⟧.", "Il clan dei ⟦Grimtotem=Totem Truce⟧ ha assaltato il mio villaggio e ha ucciso quasi tutti. Ne ho uccisi quanti ho potuto, ma sono scampato a malapena.\n\n{name}, ora desidero solo che altri di loro muoiano. Li troverai poco più a ovest di qui.", "Li hai già uccisi?", "{name}, ti ringrazio... ma non dimenticherò mai ciò che i ⟦Grimtotem=Totem Truce⟧ hanno fatto al mio villaggio.", 0x7672b786, 0x3188b556, 0x2e43c3b5, 0x8436fd53, 0x3876ab77, "....." },
  [6561] = { "Malvagità negli Abissi di ⟦Blackfathom=Fondocupo⟧", "Porta la testa di ⟦Twilight Lord Kelris=Signore del Crepuscolo Kelris⟧ a ⟦Bashana Runetotem=Bashana Totem Runico⟧, a ⟦Thunder Bluff=Picco del Tuono⟧.", "Le forze mi hanno abbandonato. Ho bisogno del tuo aiuto!\n\nTanto tempo fa questo luogo era un grande tempio di Elune. Ma la sventura lo portò alla rovina quando la corruzione di un Dio Antico filtrò dalle profondità della terra e contaminò il sacro Pozzo della Luna.\n\nAku'Mai, servitore del Dio Antico, emerse dalle acque.\n\nI cultisti del ⟦Twilight's Hammer=Martello del Crepuscolo⟧ si sono alleati con i naga per occupare questi luoghi. I cultisti, guidati da Kelris, sacrificano innocenti ad Aku'Mai in cambio di potere.\n\nUccidi Kelris e porta la sua testa a Bashana, a ⟦Thunder Bluff=Picco del Tuono⟧, {name}, ti prego.", "Che la Madre Terra sia con te, {name}.\n\nLa pace tra la terra e tutto il suo popolo dovrebbe essere il nostro obiettivo. Lei ha un grande disegno per la natura, e ognuno di noi ha un ruolo in quel disegno.", "Kelris è sfuggito all'⟦Argent Dawn=Alba d'Argento⟧ per parecchio tempo.\n\nPer un certo periodo lo hanno creduto morto o disperso.\n\nPonendo fine al suo regno hai risparmiato la vita di molti innocenti, {name}.\n\nSia lodata la Madre Terra! Sacrificare un altro a un servitore di un Dio Antico per il proprio tornaconto è più che disgustoso!\n\nOggi hai compiuto una grande impresa. Kelris era una creatura malvagia e cercava di riportare il mondo a un'epoca di caos venerando creature come gli Dei Antichi. Grazie, {name}.", 0x43ec82c9, 0xce4f2e26, 0x94ed4e5b, 0xb0ade819, 0x48004ea9, "....." },
  [6562] = { "Guai negli abissi", "Parla con Je'neu Sancrea a ⟦Ashenvale=Valtetra⟧.", "Je'neu Sancrea ha bisogno di aiuto. Si trova all'⟦Zoram'gar Outpost=Avamposto di Zoram'gar⟧, a ⟦Ashenvale=Valtetra⟧. La foresta degli Elfi della Notte è a nord delle Vette di ⟦Stonetalon=Petrartiglio⟧. Puoi raggiungerla attraversando la ⟦Windshear Crag=Landa di Tagliavento⟧ o dirigendoti a nord attraverso le ⟦Barrens=Savane⟧. La ⟦Zoram Strand=Spiaggia di Zoram⟧ è molto a ovest della foresta. Fa' attenzione, {name}. Lì ci sono forze che non gradiranno la tua presenza.", nil, "Ti ha mandato Tsunaman? Eccellente. Allora abbiamo questioni di cui discutere.", 0x307a4f6d, 0x9f861a77, 0x131c7400, nil, 0x87dd1bf2, "...m." },
  [6563] = { "L'essenza di Aku'Mai", "Porta 20 Zaffiro di Aku'mai a Je'neu Sancrea a ⟦Ashenvale=Valtetra⟧.", "Nei primi tunnel degli ⟦Blackfathom Deeps=Abissi di Fondocupo⟧, lungo le pareti della grotta, si trovano grandi grappoli di zaffiri. Di recente si è notato che i naga stanno raccogliendo questi cristalli. Finché non si capirà perché, sento che dovremmo impedire ai naga di riuscirci. I cristalli hanno un grande potere elementale e, se usati in modo improprio, potrebbero diventare un potente componente arcano.\n\nMi aiuterai, {name}? Gli ⟦Blackfathom Deeps=Abissi di Fondocupo⟧ si trovano lungo la ⟦Zoram Strand=Spiaggia di Zoram⟧, a nord del nostro avamposto.", "Come procede la ricerca dei cristalli, {name}? Hai visto i naga che li raccolgono? Prego i miei antenati che scopriamo perché raccolgono cose del genere.", "Ben fatto, {name}. Sono questi i cristalli di cui parlavo. Interessante...\n\nSento il potere che contengono. Gli spiriti dell'acqua vi restano aggrappati. Qualunque cosa i naga volessero farne... be', rallegriamoci che non siano più nelle loro mani.", 0xa4481d13, 0x4621729c, 0xb3c94759, 0xdbb5841e, 0x5b9d7398, "....." },
  [6564] = { "Fedeltà agli Dei Antichi", "Porta la ⟦Damp Note=Nota Bagnata⟧ a Je'neu Sancrea a ⟦Ashenvale=Valtetra⟧.", "Sul biglietto spiegazzato c'è uno scarabocchio dalla pessima calligrafia:\n\n\"Sì, di' a tutte le sacerdotesse di portarmi i cristalli. Gli spiriti degli elementali dell'acqua sono forti al loro interno e aiuteranno molto i nostri acquamanti nelle loro evocazioni.\n\nControllando il potere dei cristalli, placheremo Aku'Mai. Un giorno avremo abbastanza potere da riportare Aku'Mai tra noi, e il mondo tornerà alla sua epoca più grande! Un'epoca di dominio degli Dei Antichi!\"", "Sì, {name}? Di cosa hai bisogno? Ho ancora molto da scoprire sui cristalli che i naga stanno raccogliendo.", "È davvero interessante. Sono lieto che tu me l'abbia fatto notare.\n\nOra abbiamo un nome per i nostri guai... Lorgus Jett.", 0xf45fe9ed, 0xe0c8139f, 0x719ece7a, 0x8ad48820, 0x0561038f, "....." },
  [6565] = { "Fedeltà agli Dei Antichi", "Uccidi Lorgus Jett negli ⟦Blackfathom Deeps=Abissi di Fondocupo⟧, poi torna da Je'neu Sancrea, a ⟦Ashenvale=Valtetra⟧.", "Non si può permettere a questo seguace del ⟦Twilight's Hammer=Martello del Crepuscolo⟧ di portare a termine il suo piano. Il ⟦Twilight's Hammer=Martello del Crepuscolo⟧ non comprende gli spiriti della natura. Credono negli Dei Antichi, creature di caos e distruzione sconfitte molto tempo fa. Non si può permettere a questo Lorgus di riuscirci. Devi fermarlo, {name}. Non posso farlo io: sono troppo debole.\n\nEntra negli ⟦Blackfathom Deeps=Abissi di Fondocupo⟧, trovalo e uccidilo. Quando è fatta, torna da me qui a Zoram'gar.", "L'hai già trovato, {name}? Lorgus deve essere fermato!", "Molto bene!! Grazie, {name}. Forse non abbiamo fermato del tutto il ⟦Twilight's Hammer=Martello del Crepuscolo⟧, ma almeno hai sventato un altro dei loro piani per riportare al potere gli Dei Antichi.\n\nChissà quali altri piani stanno prendendo forma, ma per ora possiamo stare tranquilli.", 0xf45fe9ed, 0xfbcf40e9, 0x496bbaf9, 0x743f304b, 0x69b34095, "....." },
  [6566] = { "Ciò che il vento porta", "Ascolta Thrall.", "È bello rivederti, {name}. Il vento porta con sé notizie dai Regni Orientali.\n\nSiediti e ascolta.", "Pazienza, {name}. Presta attenzione!", "Sei <pronto/pronta> ad accettare questo compito?", 0x7ec308ae, 0xe453d7c1, 0xe7172974, 0xc7dd0473, 0x40959543, "....." },
  [6567] = { "Il campione dell'⟦Horde=Orda⟧", "Cerca Rexxar. Il Capoguerra ti ha detto dove trovarlo. Perlustra i sentieri di ⟦Desolace=Desolanda⟧, tra le ⟦Stonetalon Mountains=Vette di Petrartiglio⟧ e Feralas.", "Uno dei miei campioni mi ha fatto sapere che potrebbe esistere un modo per entrare nella tana del drago. Devi andare a cercarlo.\n\nRexxar vaga per le lande desertiche di ⟦Desolace=Desolanda⟧, tra ⟦Stonetalon=Petrartiglio⟧ e Feralas. Attende il tuo arrivo.", nil, "C'è un solo modo per entrare nella tana del drago, {race}.\n\nVedi, solo i più forti dello Stormo dei Draghi Neri possono entrare nella tana della madre della covata. Bisogna superare molte prove, e la chiave per entrare viene incantata con una cerimonia dallo stesso generale Drakkisath!\n\nPoiché non appartieni alla stirpe dei draghi neri, potresti avere qualche difficoltà a ottenere il passaggio.\n\n<Rexxar sogghigna.>", 0x9e62ab4c, 0x7c7eaae9, 0x53a737c9, nil, 0x643411c5, "...m." },
  [6568] = { "Il testamento di Rexxar", "Consegna Rexxar's Testament a Myranda la Megera, nelle ⟦Western Plaguelands=Terre Infette Occidentali⟧.", "Cosa sai delle illusioni, {name}? Vedi, è un'illusione che dovrai creare per aggirare le difese dello Stormo dei Draghi Neri.\n\nConosco una persona che potrebbe essere disposta ad aiutarti nel tuo inganno. In passato ha aiutato quelli come noi, quando ha ritenuto la causa degna.\n\nNelle ⟦Western Plaguelands=Terre Infette Occidentali⟧ troverai Myranda la Megera, maestra illusionista ed esule dell'Alleanza di Lordaeron. Raggiungila e portale questo messaggio.", "Non capita spesso di vedere qualcuno dell'⟦Horde=Orda⟧ da queste parti di Lordaeron. Cos'hai per Myranda?", "<Myranda prende il biglietto, si ferma, poi sorride.>\n\nCome sta? Rexxar, intendo. Oh, andiamo, non fare quella faccia confusa. La lettera è stata lasciata in bianco di proposito. Portava con sé le intenzioni e i pensieri di chi l'ha scritta. A giudicare dal contenuto, non c'è da stupirsi che Rexxar l'abbia lasciata così. Immagina se ti avessero catturat<o/a> o uccis<o/a> e queste informazioni fossero state scoperte!\n\nOh, lascia perdere! Myranda ti aiuterà, {race}. Devo al Capoguerra un favore o due.\n\n<Myranda sorride.>", 0x317e218f, 0x874610ed, 0x7eca30c4, 0x11f0f4f7, 0x9c079ebf, "....." },
  [6569] = { "Illusioni oculari", "Raggiungi i ⟦Blackrock Spire=Bastioni di Roccianera⟧ e raccogli 20 Occhio di ⟦Black Dragonspawn=Dragobestia Nero⟧. Torna da Myranda la Megera quando avrai finito.", "Dunque <il/la> {race} vuole diventare uno dello Stormo dei Draghi Neri, eh?\n\nCreare l'illusione che ti serve è una sciocchezza, ma i componenti necessari per la divinazione sono piuttosto difficili da ottenere. Rexxar e il Capoguerra ti hanno affidato questa missione, quindi Myranda deve presumere che tu sia all'altezza.\n\nRaggiungi la cittadella superiore dei ⟦Blackrock Spire=Bastioni di Roccianera⟧ e uccidi abbastanza dragobestie nere da riempire una delle tue sacche con i loro occhi.\n\nTorna da Myranda quando avrai raccolto abbastanza reagenti.", "Gli occhi di ciò che vogliamo imitare sono l'ingrediente più importante di qualsiasi illusione, {name}.\n\n<Myranda indica una sacca quasi traboccante di bulbi oculari con l'etichetta '⟦Scarlet Crusade=Crociata Scarlatta⟧'.>\n\n<Myranda ride.>", "Lascia che Myranda dia un'occhiata, {race}.\n\nOh sì, questi andranno benissimo.\n\nCon questi reagenti, Myranda creerà per te un medaglione che concederà un'illusione capace di ingannare il guardiano dei cancelli dello Stormo dei Draghi Neri.", 0x2bad6541, 0x5de63ab2, 0x4f4b0a78, 0x40106753, 0xc88c7071, "....." },
  [6570] = { "⟦Emberstrife=Braceardente⟧", "Raggiungi il ⟦Wyrmbog=Brago dei Dragoni⟧, ad ⟦Dustwallow Marsh=Acquemorte⟧, e cerca la ⟦Emberstrife's Den=Tana di Braceardente⟧. Una volta dentro, indossa l'⟦Amulet of Draconic Subversion=Amuleto della Sovversione Draconica⟧ e parla con ⟦Emberstrife=Braceardente⟧.", "Ho sintonizzato questo medaglione con la magia necessaria a creare e mantenere un'illusione entro i confini della Tana di ⟦Emberstrife=Braceardente⟧.\n\n⟦Emberstrife=Braceardente⟧ è un antico draco, un vecchio guardiano dei cancelli di Nefarian, con il compito di mettere alla prova le dragobestie che aspirano al rango di guardia scelta di Onyxia.\n\nRaggiungi il ⟦Wyrmbog=Brago dei Dragoni⟧, ad ⟦Dustwallow Marsh=Acquemorte⟧, ed entra nella tana di ⟦Emberstrife=Braceardente⟧. Una volta lì, indossa l'amuleto e segui il destino ovunque ti porti!", nil, "Siamo così a corto di soldati capaci che Nefarian mi manda dei cuccioli? Non supererai mai le mie prove, piccolo della covata.", 0x6e6c84be, 0x68462fdc, 0xeba39a80, nil, 0x9470e63e, "...m." },
  [6571] = { "Rifornimenti dei ⟦Warsong=Cantaguerra⟧", "Raccogli i rifornimenti dei ⟦Warsong=Cantaguerra⟧ (⟦Warsong Saw Blades=Lame Seghettate dei Cantaguerra⟧, ⟦Logging Rope=Corda per Campo di Taglio⟧, ⟦Warsong Oil=Olio dei Cantaguerra⟧ e ⟦Warsong Axe Shipment=Spedizione d'Asce dei Cantaguerra⟧) per Locke Okarr, all'⟦Splintertree Post=Avamposto di Troncorotto⟧.", "Al campo di taglio dei ⟦Warsong=Cantaguerra⟧ siamo a corto di alcune cose!\n\nPixel, all'⟦Splintertree Post=Avamposto di Troncorotto⟧, ha la nostra spedizione di lame per seghe. Ci vorrà un viaggio fino alla ⟦Booty Bay=Baia del Bottino⟧ per ritirare una cassa di asce dal capitano del porto Malattracco.\n\nLa spedizione di olio e corda sarà più difficile. La corda è stata rubata dai mezzorsi Mantocardo e Foulweald, e i satiri hanno intercettato la consegna dell'olio e ora lo usano per riti abominevoli a ⟦Night Run=Jorxian⟧, ⟦Satyrnaar=Satirnaar⟧ e Xavian!\n\nPuoi aiutarmi?", "Spero che tu riesca a procurarmi i rifornimenti! Sono nei guai se non li consegno presto!", "Ottimo, {name}. Mi hai risparmiato un sacco di lavoro!\n\nMa non credere che non ti sia grato!", 0xa776f6d8, 0xe0a604fd, 0x0c3cfec5, 0x658fa1ea, 0x495630c4, "....." },
  [6581] = { "⟦Warsong Saw Blades=Lame Seghettate dei Cantaguerra⟧", nil, nil, "Direttamente da ⟦Ratchet=Porto Paranco⟧, le Lame Seghettate dei ⟦Warsong=Cantaguerra⟧! Sì, le ho proprio qui.\n\n...Ma come pensi di pagarmi? Non puoi mica prenderle e basta! Il mio tempo costa!\n\nQuello che mi serve davvero è un buon fucile da portarmi dietro nei miei viaggi. Una ragazza deve sapersi difendere, no? C'è un fucile che mi piace tanto e che un ingegnere costruirebbe di sicuro senza problemi.\n\nQuindi, se mi porti un archibugio letale, ti darò la spedizione di lame. Affare fatto?", "È perfetto, proprio quello che ci voleva! Bene, ecco la spedizione.", 0x54be59fa, nil, nil, 0x6f155034, 0x53390ad0, ".mm.." },
  [6582] = { "La prova dei teschi: Alasaggia", "Devi trovare il draco campione dello Stormo dei Draghi Blu, Scryer, e ucciderlo. Strappa il teschio dal suo cadavere e portalo a ⟦Emberstrife=Braceardente⟧.\n\nSai che Scryer si trova a ⟦Winterspring=Fontefredda⟧.", "Siamo i figli di Alamorte, cucciolo. Il nostro dominio sugli Aspetti minori va imposto.\n\nSe sei davvero degn<o/a> dell'ascesa, gli stormi inferiori appassiranno al tuo cospetto.\n\nTrova i loro campioni e annientali nel nome di nostro Padre!\n\nRaggiungi ⟦Winterspring=Fontefredda⟧ e rintraccia il possente draco blu, Alasaggia. Schiaccia lui e chiunque dello Stormo dei Draghi Blu si metta sulla tua strada. Strappagli il teschio e portamelo.", "<⟦Emberstrife=Braceardente⟧ sibila.>", "Uno dei diverssssi, compiuto...", 0xd4e320f7, 0x1467aba3, 0xec99c5eb, 0x9b46d3b4, 0x6ad7b728, "....." },
  [6583] = { "La prova dei teschi: Somnus", "Distruggi Somnus, il draco campione dello Stormo dei Draghi Verdi. Prendi il suo teschio e portalo a ⟦Emberstrife=Braceardente⟧.", "Come nostro Padre schiaccia gli Aspetti stessi, così anche noi dobbiamo sforzarci di portare caos e distruzione tra i loro figli.\n\nDevi mettere alla prova la tua abilità in battaglia contro i sognatori insonni: i figli dello Stormo dei Draghi Verdi.\n\nRaggiungi la ⟦Swamp of Sorrows=Palude del Dolore⟧ e rintraccia Somnus, il draco campione dello Stormo dei Draghi Verdi. Lascia sgorgare il tuo odio; domina l'insetto... Torna da me con il suo teschio...", "Non tornare qui finché non ti sarai bagnat<o/a> nel sangue dei nostri nemici e non avrai bevuto la loro sofferenza.", "Un altro, compiuto...", 0xa6d94f8f, 0x82bcebf0, 0xd83cd2cf, 0xf12ea661, 0x5b0b6cfa, "....." },
  [6584] = { "La prova dei teschi: ⟦Chronalis=Tac⟧", "A guardia delle ⟦Caverns of Time=Caverne del Tempo⟧, nel deserto di Tanaris, c'è ⟦Chronalis=Tac⟧, figlio di Nozdormu. Distruggilo e porta il suo teschio a ⟦Emberstrife=Braceardente⟧.", "I guardiani del tempo, figli di Nozdormu, Signore dei Secolisss...\n\nSono tre a sorvegliare le ⟦Caverns of Time=Caverne del Tempo⟧, ma solo uno interessa allo Stormo dei Draghi Neri: il Time Shifter, ⟦Chronalis=Tac⟧, il draghetto prediletto di Nozdormu.\n\nColpisssci questo campione, con un colpo che faccia piangere persino le stoiche sabbie del tempo. Torna da me con il suo teschio.", "Ironia della sorte, cucciolo, il tempo è esssssenziale.", "Resssta il più odiato...", 0xc44aac34, 0x38263530, 0xfb25247f, 0xae0bd587, 0x2eb5587e, "....." },
  [6585] = { "La prova dei teschi: Axtroz", "Raggiungi Grim Batol e trova Axtroz, draco campione dello Stormo dei Draghi Rossi. Distruggilo e prendi il suo teschio. Riporta il teschio a ⟦Emberstrife=Braceardente⟧.", "Fu sulle montagne di Grim Batol che nostro Padre si scagliò contro la forza unita degli Aspetti. L'atto codardo della traditrice, Alexstrasza, diede agli altri Aspetti il tempo di sfuggire all'ira del Padre.\n\nUn gesto tanto vergognossso...\n\nOra lo Stormo dei Draghi Rossi sorveglia Grim Batol, e il suo luogotenente, Axtroz, deve essere distrutto. Portami il teschio di Axtroz. Per il Padre, cucciolo!", "Cambiamenti... li sssento avvenire in te, cucciolo. Supera questa prova e resterà solo la cerimonia.", "Avevo dubitato della tua dedizione, cucciolo. Hai perseverato, dominando i nostri nemici e portando onore al nostro stormo.\n\nOra devo preparare i teschi per la tua ascesa.", 0x96788f83, 0x48284fc4, 0xc3500aed, 0xead6876b, 0x43cbef24, "....." },
  [6601] = { "Ascesa...", "A quanto pare la farsa è finita. Sai che l'⟦Amulet of Draconic Subversion=Amuleto della Sovversione Draconica⟧ che Myranda la Megera ha creato per te non funzionerà dentro i ⟦Blackrock Spire=Bastioni di Roccianera⟧. Forse dovresti cercare Rexxar e spiegargli la tua difficoltà. Mostragli l'⟦Dull Drakefire Amulet=Amuleto Fuocodraco Smussato⟧. Con un po' di fortuna saprà cosa fare.", "Dai teschi dei nostri nemici si forgia un medaglione. Conosci questo medaglione, sssì? Di certo l'hai visto al collo dei tuoi anziani.\n\nPrendilo, cucciolo. Torna ai Bastioni e presentalo al generale Drakkisath. Il generale porrà l'ultimo incantamento sul medaglione, legando il monile al tuo spirito.\n\nIndosserai il medaglione finito come un distintivo d'onore, simbolo della tua ascesa a uno dei nostri ranghi più protetti: <Guardiano/Guardiana> della madre della covata.\n\nVa'!", "Niente panico, {name}!", "Sono solo chiacchiere da draghi, {name}: più aria calda che informazioni di sostanza. Dalla loro specie c'è da aspettarsi un comportamento borioso e aggressivo.", 0x1b907c01, 0x74690080, 0x18fae3e7, 0x4ca8f04e, 0x53a0d258, "....." },
  [6602] = { "⟦Blood of the Black Dragon Champion=Sangue del Campione dei Draghi Neri⟧", "Raggiungi i ⟦Blackrock Spire=Bastioni di Roccianera⟧ e uccidi ⟦General Drakkisath=Generale Drakkisath⟧. Raccogli il suo sangue e portalo a Rexxar.", "Farai visita al generale, sì, ma non come membro dello Stormo dei Draghi Neri.\n\nVedi, per lo Stormo dei Draghi Neri una cerimonia non è che un altro modo di dire salasso.\n\nL'amuleto latente ha solo bisogno del sangue del generale per attivarsi. Uno dei loro rozzi meccanismi di sicurezza.\n\nTorna ai ⟦Blackrock Spire=Bastioni di Roccianera⟧ e distruggi Drakkisath. Riporta qui il suo sangue e attiverò la chiave dell'Antro di Onyxia.", "Non credo di doverti dire che Drakkisath non va preso alla leggera.\n\nLascio parlare le migliaia di morti per mano sua.", "Una vittoria che sarà ricordata per molti anni, {name}. L'⟦Drakefire Amulet=Amuleto Fuocodraco⟧ aprirà l'Antro di Onyxia. Raduna i tuoi alleati e porta la vittoria all'⟦Horde=Orda⟧.", 0x9d1c3849, 0x5a67aea8, 0xa400dac9, 0x1b4339bd, 0x86d61907, "....." },
  [6603] = { "Guai a ⟦Winterspring=Fontefredda⟧!", "Trova ⟦Donova Snowden=Donova Pestaneve⟧ vicino alle sorgenti calde di ⟦Winterspring=Fontefredda⟧.", "Ci sono guai a ⟦Winterspring=Fontefredda⟧!\n\nMa certo, passo un po' di tempo nelle terre selvagge e di queste cose me ne intendo... e ne vado sempre fiero. Le ore che passo là fuori tra le colline per me valgono oro. Ti aiutano a coltivare riflessi pronti, sangue freddo e occhio acuto...\n\nCi vogliono giudizio, cervello e maturità per apprezzare la natura selvaggia come la apprezzo io.\n\nDunque, di che stavo parlando?\n\nAh, sì, i guai. Va' da ⟦Donova Snowden=Donova Pestaneve⟧ alle sorgenti calde: lei saprà dirti di più.", nil, "Ehi, ciao! Allora Meggi ti ha parlato dei guai che ho trovato qui?", 0x44414ba6, 0x059fbcc2, 0xaea9e1fd, nil, 0x0dd5e9d1, "...m." },
  [6604] = { "Silvagufi infuriati", "Parla con ⟦Jaron Stoneshaper=Jaron Formapietre⟧ al ⟦Starfall Village=Padiglione Pioggia di Stelle⟧.", "Hai notato l'accampamento abbandonato a sud di qui? Sembra che i silvagufi siano impazziti e abbiano distrutto quasi tutto quello che hanno trovato!\n\nHo sentito dire che uno dei sopravvissuti all'attacco si sta riprendendo al ⟦Starfall Village=Padiglione Pioggia di Stelle⟧, a ovest di qui. Sono proprio curioso di sapere cos'è successo... tu no?", nil, "Sì, cosa posso fare per te?", 0x79149705, 0xb52378e8, 0x474f0700, nil, 0x40303f26, "...m." },
  [6605] = { "Un tipo strano", "Parla con Winna Hazzard nel ⟦Felwood=Vilbosco⟧.", "Vengo proprio ora dal ⟦Felwood=Vilbosco⟧, {name}. Lungo la strada ho fatto tappa all'⟦Bloodvenom Post=Accampamento di Sanguemarcio⟧ e ho incontrato un personaggio molto strano... Sembrava avere in mente una cosa sola, e immagino che potrei dirti di cosa si tratta, ma credo che preferirebbe spiegartelo lei stessa.\n\nSe ti interessa, va' all'⟦Bloodvenom Post=Accampamento di Sanguemarcio⟧, nel ⟦Felwood=Vilbosco⟧ occidentale, e cerca Winna Hazzard.\n\nChissà, potrebbe aver bisogno del tuo aiuto...", nil, "Ah, {class}. Vedo che c'è ancora speranza. Sei qui per aiutarmi?", 0xbfd601ab, 0x658a1b4a, 0xd570b6ad, nil, 0xd546ad0d, "...m." },
  [6606] = { "Un po' di fortuna", "Parla con la taumaturga Mau'ari a Orgrimmar.", "Un po' di fortuna fa sempre comodo, eh? Basta un piccolo vantaggio per girare le cose a tuo favore...\n\nTempo fa mi è capitato di fare la conoscenza di una santona piuttosto eccentrica. Mi ha fatto un portafortuna... a pagamento. Ma credimi, ne è valsa davvero la pena!\n\nForse ne vorresti uno anche tu? Va' dalla taumaturga Mau'ari a Orgrimmar. Il mio non lo cedo!", nil, "Ah, allora è Harlo che ti manda, eh? Be', e tu chi saresti? Scommetto che vuoi il mio aiuto, no?", 0x01480ede, 0x36ee0ee3, 0xfb04d024, nil, 0x7da942c3, "...m." },
  [6607] = { "Nat Pagle, pescatore estremo", "Nat Pagle vuole che tu peschi questi pesci:\n\nLampuga di Cannamarcia dalla ⟦Misty Reed Strand=Riva di Cannamarcia⟧, nella ⟦Swamp of Sorrows=Palude del Dolore⟧.\n\nUn ⟦Sar'theris Striker=Siluro di Sar'theris⟧ dalla ⟦Sar'theris Strand=Riva di Sar'theris⟧, in ⟦Desolace=Desolanda⟧.\n\nTonno di Feralas dal ⟦Verdantis River=Fiume Verdantis⟧, a Feralas.\n\nPescevela della Costa Selvaggia dalla Costa Selvaggia, nella Valle di Rovotorto.\n\nTorna da Nat Pagle quando li avrai tirati su tutti!", "Non posso dire che la pesca mi piaccia granché. A conti fatti ci sto dietro da una ventina o una trentina d'anni.\n\nMi sa che ognuno fa quel che fa per ragioni diverse.\n\nOra, non dico che devi pescare per 30 anni o prendere ogni pesce del mare per diventare un maestro pescatore. Mi sa che basta essere determinati, abbastanza determinati da startene seduto sul sedere per ore e ore, senza far niente.\n\nFacciamo così: pescami qualche pesce raro e ti insegnerò un paio di cose. Ecco la lista:", "Abboccato niente oggi?", "Questa sì che è una bella pesca!\n\nVieni qua, che ti faccio vedere come si calano un paio di lenze.", 0xac59e2e5, 0x36b6358f, 0x5aa64309, 0xd57a7a65, 0x3941c747, "....." },
  [6608] = { "Tu troppo forte", "Ti pare che Lumak stia cercando di dirti che non può più aiutarti a migliorare la tua abilità nella pesca. Forse dovresti cercare il suo amico Nat Pagle, un umano che pesca al largo di una delle isole a sud di Theramore (almeno, così ti pare di aver capito da Lumak).", "Lumak non può più insegnare a {name}. Tu troppo forte! Trova amico di Lumak, Nat Pagle. È umano ma non mangiare! È amico di Lumak! Nat insegna te pescare più meglio.\n\nTrovi Nat ad ⟦Dustwallow Marsh=Acquemorte⟧, a sud di città di umi, Theramoroqualcosacosì. Nat forse pesca. Va' ora!", nil, "Ma certo, devi essere tra gli amici di Lumak.\n\nLa pesca? Della pesca ti posso dire tutto.", 0x369612ab, 0x6f08769c, 0x21ec23cf, nil, 0xab959ea7, "...m." },
  [6609] = { "Non mi è rimasto niente!", "Va' a Kalimdor, nella città costiera di Theramore. Da lì devi cercare un'isola a sud della città principale. Nat Pagle ti aspetta!", "Sono un nano, santo cielo, <ragazzo/signorina>! Non son fatto per pescare! Voglio dire, guardami! Son praticamente fatto di pietra.\n\nNon m'è rimasto niente: m'hai prosciugato. T'ho insegnato tutto quel che so, pesciolino!\n\nNon ci arrivi? Ah, va bene. Ho un vecchio amico su Kalimdor che può darti una mano. Si chiama Nat Pagle, un bravo ragazzo. Lo trovi sulle isole a sud di Theramore. Fila!", nil, "Sulla mia isola c'è sempre posto per i visitatori... mi sa...", 0x7469ef5c, 0x359ead0c, 0x3456ca82, nil, 0xf4e96883, "...m.", nil, nil, 0x7b35d4f4, nil, nil },
  [6610] = { "⟦Clamlette Surprise=Bivalve a Sorpresa⟧", "⟦Dirge Quikcleave=Dirge Pestacarne⟧ vuole che tu gli procuri questi ingredienti:\n\n12 Uovo Gigante. Li troverai sui Roc che vagano per Tanaris o su qualsiasi altra specie di grosso uccello.\n\n10 pezzi di ⟦Zesty Clam Meat=Mollusco Gustoso⟧. Li trovi nei molluschi, naturalmente!\n\n20 pezzi di ⟦Alterac Swiss=Emmental d'Alterac⟧. Fila in un caseificio!\n\nRaccogli tutto e torna da Dirge.", "Hai mai sentito parlare del bivalve a sorpresa? Certo che no! È il mio ultimo e più grande capolavoro culinario. Oh, {name}, solo a pensare a un bivalve a sorpresa mi viene l'acquolina in bocca.\n\nPurtroppo ho finito tutti gli ingredienti per prepararlo! Che ne dici di un accordo? Tu raccogli gli ingredienti che mi servono per il bivalve a sorpresa e io ti insegno i segreti della cucina esotica, e ci aggiungo pure un paio di bivalvi a sorpresa! Affare fatto??\n\nEcco cosa mi serve:", "Le mie voglie saranno la mia rovina! Sbrigati, {name}, prima che metta mano alle mie scorte.", "Ti aspetta una vera prelibatezza, {name}. Guarda e impara!\n\n<Dirge comincia a preparare il bivalve a sorpresa.>", 0xed5328d0, 0xd4e9b30a, 0x337c0659, 0x2d9a164d, 0x177f9dfe, "....." },
  [6611] = { "A ⟦Gadgetzan=Meccania⟧ devi andare!", "Va' a ⟦Gadgetzan=Meccania⟧, nel deserto di Tanaris, e parla con ⟦Dirge Quikcleave=Dirge Pestacarne⟧ per far progredire la tua carriera di cuoco.", "Come pensi che Zamja ti insegna qualcosa? Hai preso tutto il mojo di cucina di Zamja e vuoi ancora di più!\n\nZamja non può aiutare. {race} ciccion<e/a> deve andare a ⟦Gadgetzan=Meccania⟧. Là trovi piccolo goblin di nome Dirge: lui ti aiuta, ciccion<e/a>.\n\nQuando diventi grande cuoco del quartiere, torni e insegni a Zamja, va bene? Ora va'!", nil, "<Dirge sputa qualche pezzo di sandalo di cuoio.>\n\nPfftooey...\n\n<Dirge tossisce rumorosamente.>\n\nChe c'è? Sappi che il cuoio è sorprendentemente ricco di proteine e povero di carboidrati.", 0x287c6197, 0x103eb5ec, 0x3bc2d5e9, nil, 0xeebeedd7, "...m." },
  [6612] = { "Conosco un tipo...", "Va' a ⟦Gadgetzan=Meccania⟧, nel deserto di Tanaris, e parla con ⟦Dirge Quikcleave=Dirge Pestacarne⟧ per far progredire la tua carriera di cuoco.", "Dal tuo cucchiaio da cuoco vedo che sai il fatto tuo. Purtroppo non posso insegnarti niente.\n\nPer tua fortuna, conosco un tipo. È un goblin, e forse il miglior cuoco di Kalimdor.\n\nGià, e questa è la brutta notizia, <ragazzo/signorina>: devi andare fino a Kalimdor. Va' a ⟦Gadgetzan=Meccania⟧ e cerca ⟦Dirge Quikcleave=Dirge Pestacarne⟧. Lui ti rimetterà in riga.", nil, "<Dirge sputa del cuoio.>\n\nPfftey...\n\n<Dirge tossisce rumorosamente.>\n\nChe c'è? Sappi che il cuoio è sorprendentemente ricco di proteine e povero di carboidrati, {race}.", 0x805c2ee8, 0x103eb5ec, 0xd2dad20c, nil, 0xf54e38b8, "...m.", nil, nil, 0xd7c7d16a, nil, nil },
  [6621] = { "Il re dei Foulweald", "Pianta lo ⟦Karang's Banner=Stendardo di Karang⟧ sul Foulweald Totem Mound. Non lasciare che i mezzorsi distruggano lo stendardo. Sconfiggi il capo Murgut e porta il ⟦Murgut's Totem=Totem di Murgut⟧ a Karang Amakkar, a Zoram'gar.", "{name}, un'altra tribù di mezzorsi, i Foulweald, vive a sud-est di Astranaar. Non sono numerosi quanto i Mantocardo, ma la loro ferocia sarà una minaccia in futuro. Con una dimostrazione di forza possiamo eliminare questa minaccia.\n\nPrendi questo stendardo, va' al villaggio dei Foulweald e piantalo sul loro tumulo del totem. Cercheranno di distruggere lo stendardo, ma resisti finché il loro capo, Murgut, non comparirà per salvare l'onore della tribù. Portami il totem che porta con sé.\n\nRaduna i tuoi alleati, {name}. Questo non è un compito per <un/una> {class} da sol<o/a>.", "Hai sconfitto il capo Murgut, {name}? Hai recuperato il suo totem dei Foulweald?", "Ottimo lavoro, {name}. Lanciare quella sfida ai Foulweald e sconfiggere il loro capo manda un messaggio chiaro:\n\nCon l'⟦Horde=Orda⟧ non si scherza.\n\nNon credo che quella tribù ci darà molti problemi per un bel pezzo.", 0x72c799c0, 0x7662f59e, 0x2ca45fcc, 0x6f018d4b, 0x73b4797f, "....." },
  [6622] = { "Il triage dei feriti", "Salva i pazienti curando le loro ferite con le Bende da Triage. Devi salvare 15 pazienti prima che 6 di loro muoiano per le ferite.\n\nRicorda l'ordine del triage! I Critically Injured Soldier muoiono più in fretta, seguiti dai Badly Injured Soldier. Gli Injured Soldier impiegano più tempo a morire e vanno salvati DOPO aver trattato i Critically Injured Soldier e i Badly Injured Soldier.", "Buongiorno, <dottore/dottoressa>. Oggi pomeriggio sarai mess<o/a> alla prova sulla tua capacità di smistare i pazienti secondo il triage. Se supererai l'esame, entrerai nei prestigiosi ranghi della Traumatologia dell'⟦Horde=Orda⟧.\n\nOra fa' attenzione! I feriti in modo critico vanno curati per primi. Dopo i critici vengono i feriti gravi. I feriti lievi vanno curati per ultimi. Devi salvare 15 pazienti per superare l'esame. Sarai bocciat<o/a> se 6 dei tuoi pazienti moriranno durante il triage.\n\nLe bende da triage ti saranno fornite.\n\nBuona fortuna, <dottore/dottoressa>.", "Un lavoro miracoloso, <dottore/dottoressa>. Semplicemente miracoloso.", "<Dottor/Dottoressa> {name}, benvenut<o/a> nella Traumatologia dell'⟦Horde=Orda⟧.", 0x66af70c6, 0x24b63d90, 0x2c30b239, 0xe7bd87ac, 0x63620819, "....." },
  [6623] = { "Traumatologia dell'⟦Horde=Orda⟧", "Va' a ⟦Hammerfall=Requie del Martello⟧, negli ⟦Arathi Highlands=Altopiani d'Arathi⟧, e parla con il dottor Gregory Victor per entrare nei ranghi della Traumatologia dell'⟦Horde=Orda⟧.", "<Dottor/Dottoressa> {name}, presumo. È un piacere rivederti.\n\nHo notizie meravigliose per te! Il dottor Gregory Victor, primario della Traumatologia dell'⟦Horde=Orda⟧, ti ha chiesto personalmente di raggiungerlo a ⟦Hammerfall=Requie del Martello⟧. Potrebbe essere l'occasione di una vita! Darei qualsiasi cosa per avere la possibilità di studiare sotto il grande dottor Gregory Victor! Non sprecare questa occasione!", nil, "Meraviglioso. Indossa il camice, cominciamo subito!", 0x800e34de, 0x827dcf0e, 0x0849290c, nil, 0xd23a5cab, "...m." },
  [6624] = { "Il triage dei feriti", "Salva i pazienti curando le loro ferite con le Bende da Triage. Devi salvare 15 pazienti prima che 6 di loro muoiano per le ferite.\n\nRicorda l'ordine del triage! I Critically Injured Soldier muoiono più in fretta, seguiti dai Badly Injured Soldier. Gli Injured Soldier impiegano più tempo a morire e vanno salvati DOPO aver trattato i Critically Injured Soldier e i Badly Injured Soldier.", "Buongiorno, <dottore/dottoressa>. Oggi pomeriggio sarai mess<o/a> alla prova sulla tua capacità di smistare i pazienti secondo il triage. Se supererai l'esame, entrerai nei prestigiosi ranghi della Traumatologia dell'⟦Alliance=Alleanza⟧.\n\nOra fa' attenzione! I feriti in modo critico vanno curati per primi. Dopo i critici vengono i feriti gravi. I feriti lievi vanno curati per ultimi. Devi salvare 15 pazienti per superare l'esame. Sarai bocciat<o/a> se 6 dei tuoi pazienti moriranno durante il triage.\n\nBuona fortuna, <dottore/dottoressa>.", "Un lavoro miracoloso, <dottore/dottoressa>. Semplicemente miracoloso.", "<Dottor/Dottoressa> {name}, benvenut<o/a> nella Traumatologia dell'⟦Alliance=Alleanza⟧.", 0x66af70c6, 0x24b63d90, 0xa3779d84, 0xe7bd87ac, 0xd31dbaee, "....." },
  [6625] = { "Traumatologia dell'⟦Alliance=Alleanza⟧", "Va' a Theramore, ad ⟦Dustwallow Marsh=Acquemorte⟧, e parla con il dottor Gustaf VanHowzen per entrare nei ranghi della Traumatologia dell'⟦Alliance=Alleanza⟧.", "<Dottor/Dottoressa> {name}, presumo. È un piacere vederti.\n\nHo notizie meravigliose per te! Gustaf VanHowzen, primario della Traumatologia dell'⟦Alliance=Alleanza⟧, ti ha chiesto personalmente di raggiungerlo a Theramore. Potrebbe essere l'occasione di una vita! Darei qualsiasi cosa per avere la possibilità di studiare sotto il grande dottor Gustaf VanHowzen! Non sprecare questa occasione, <dottore/dottoressa>!", nil, "Meraviglioso. Indossa il camice, cominciamo subito!", 0x3640cfdf, 0x8c4e1cd1, 0x64adb09e, nil, 0xd23a5cab, "...m." },
  [6626] = { "Un esercito del male", "Uccidi 8 ⟦Razorfen Battleguard=Guardia da Battaglia Lamaspina⟧, 8 Razorfen Thornweaver e 8 Death's Head Cultist, poi torna da ⟦Myriam Moonsinger=Myriam Cantaluna⟧ vicino all'ingresso dei ⟦Razorfen Downs=Sotterranei di Lamaspina⟧.", "I Reietti non trasmettono la loro... malattia... da quel che ho visto. Questo diplomatico sembra concedere la non morte ai suoi aspiranti seguaci. Comincio a pensare che sia uno del Flagello.\n\nPer ora, però, non è lui a preoccuparmi, ma le file sempre più numerose intorno a lui. Strisciano fuori dall'ombra ogni giorno, quasi implorandolo di dar loro più potere.\n\nNon sono abbastanza potente per affrontarli da sola, {name}. Che ne dici? Te la senti di andare a caccia?", "Come va la caccia, {name}? Mi basta vedere questo piccolo assaggio del potere del diplomatico per togliermi ogni dubbio: il Flagello è una delle minacce più grandi che questo mondo abbia mai visto.", "Grazie, {name}! Il lavoro che hai fatto sarà di grande aiuto, ne sono certa.\n\nContinuerò a studiare questo diplomatico e il resto dei verrospini qui. Se cerchi avventure più grandi, ti consiglio di trovare qualche amico e di entrare nella caverna che sembra un'enorme bocca di cinghiale, proprio laggiù. Sono sicura che una volta dentro troverai sfide più grandi da affrontare.", 0xa6ad637c, 0x78151438, 0x50ddd7c3, 0x416675bc, 0x196700d7, "....." },
  [6627] = { "⟦Test of Lore=Prova di Conoscenza⟧", "Rispondi correttamente alla domanda di Braug Dimspirit, poi parlagli di nuovo. Resterà nelle ⟦Stonetalon Mountains=Vette di Petrartiglio⟧ finché non sarai pront<o/a>.", "Mi hai portato il libro, e ora è il momento della tua domanda. Sei pront<o/a>?\n\nIl tempo non è un problema, {class}, quindi non sentirti sotto pressione. Puoi prenderti tutto il tempo che vuoi per rispondere.", "La vita è piena di domande, {class}. Non riuscirai mai a rispondere a tutte, ma con un po' di tempo e di studio forse diventerai un po' più sapiente.", "Ben fatto, {class}. Hai studiato il testo che ti avevo chiesto, e ora hai superato un'altra delle nostre prove.", 0xdf27dbbd, 0xf6917aca, 0xec0ad382, 0x516e97bd, 0x80548961, "....." },
  [6628] = { "⟦Test of Lore=Prova di Conoscenza⟧", "Rispondi correttamente alla domanda di Parqual Fintallas, poi parlagli di nuovo. Resterà a ⟦Undercity=Sepulcra⟧ finché non sarai pront<o/a>.", "Dunque il momento è di nuovo giunto. Da studios<o/a> del sapere, hai dimostrato grande tenacia accettando il mio compito.\n\nE ora ti pongo la tua domanda. Se sei pront<o/a>, parlami di nuovo, e prenditi tutto il tempo che ti serve, {name}: non c'è alcuna fretta di rispondere.", "C'è una sola regola che secondo me devi conoscere, se vuoi sopravvivere in questo mondo: più sai, più vedrai.\n\nSe studi, se osservi, comincerai a vedere nel mondo cose che nessun altro {race} vedrà.", "Ben fatto, {name}. Avevo i miei dubbi che avessi studiato il testo che ti avevo chiesto di procurarti, ma hai risposto correttamente.", 0xdf27dbbd, 0xb665516e, 0x01337379, 0xa493f15e, 0x242f01c9, "....." },
  [6629] = { "Uccidi ⟦Grundig Darkcloud=Grundig Nube Oscura⟧", "Uccidi ⟦Grundig Darkcloud=Grundig Nube Oscura⟧ e 6 Grimtotem Brute, poi torna da ⟦Makaba Flathoof=Makaba Zoccolo Piatto⟧, vicino al margine sud-orientale di ⟦Stonetalon=Petrartiglio⟧.", "{name}, hai fatto un ottimo lavoro contro i ⟦Grimtotem=Totem Truce⟧. Se osi, ⟦Grundig Darkcloud=Grundig Nube Oscura⟧ e la sua banda personale di bruti sono di gran lunga i peggiori. È stato lui a guidare il brutale attacco al mio villaggio.\n\nLo troverai all'⟦Grimtotem Post=Avamposto dei Totem Truce⟧, poco più avanti lungo il sentiero verso ovest. Uccidilo e te ne sarò grato per sempre.", "Hai ucciso ⟦Grundig Darkcloud=Grundig Nube Oscura⟧ e la sua banda personale di bruti?", "⟦Grundig Darkcloud=Grundig Nube Oscura⟧ è morto! {name}, ti sarò sempre grato per ciò che hai fatto qui oggi.", 0x9168fe63, 0x410c3d4d, 0x726195b3, 0x20857c13, 0xa13011e8, "....." },
  [6641] = { "⟦Vorsha the Lasher=Vorsha la Sferzatrice⟧", "Proteggi ⟦Muglash=Spaccamusi⟧ mentre si dirige verso il braciere. Aiutalo spegnendo il braciere, poi difendilo mentre combatti contro i naga.\n\nSe ci riesci, torna all'⟦Zoram'gar Outpost=Avamposto di Zoram'gar⟧ e informa il messaggero dei ⟦Warsong=Cantaguerra⟧ della morte di ⟦Vorsha the Lasher=Vorsha la Sferzatrice⟧.", "⟦Vorsha the Lasher=Vorsha la Sferzatrice⟧... l'idra demoniaca che vaga per i mari...\n\nHa attaccato il nostro avamposto, ogni volta senza provocazione, devastando tutto ciò che le capita a tiro.\n\nMa io sono pronto, {name}. Mi sono preparato a sconfiggere l'idra e a porre fine a questi attacchi a Zoram'gar.\n\nI naga onorano la natura malvagia di questa bestia con un braciere che resta acceso su un'isola appena al largo della costa. Credo che, se lo spegniamo, Vorsha comparirà infuriata.\n\nCi servirà aiuto, quindi assicurati di portare con te alleati forti.", nil, "Ho visto molti attacchi dei naga da quando sono qui. Mi tranquillizza sapere che Vorsha non vagherà più libera.\n\nSiamo in debito con te, {name}.", 0x3efe9ea2, 0x8d14a546, 0xf9fcb52d, nil, 0xec24fd21, "...m." },
  [6661] = { "Retata di ratti degli Abissi", "Cattura 5 Deeprun Rat usando il ⟦Rat Catcher's Flute=Piffero Acchiapparatti⟧. Riporta i ratti da Monty. Non dimenticare di restituire il piffero quando hai finito.", "Avast, marrano. Arrrr... Arrrr, cerchi lavoro? Abbiamo un serio problema di ratti quaggiù, e troppe poche braccia sul ponte di poppa.\n\nChe ne dici? Devi solo prendere questo piffero acchiapparatti e suonare la melodia vicino ai topacci. Ti seguiranno fino ai confini del mondo!\n\nCattura cinque di quelle bestiacce e riportale qui. Ci servono vive.\n\nArrrrr...", "Yarrr... Mozzo, che ci metti tanto?", "Questi andranno benone, compare. A mi' fratello servono ancora vivi e scalcianti, sennò vanno a male... E tu non vuoi assaggiare uno spiedino di ratto andato a male.", 0x058b4f5c, 0xc9e92c7d, 0x5a7d2f9f, 0x43339737, 0xa19d5900, "....." },
  [6662] = { "Mi' fratello, Nipsy", "Porta la ⟦Carton of Mystery Meat=Cassa di Carne Misteriosa⟧ a Nipsy, alla stazione del ⟦Deeprun Tram=Tram degli Abissi⟧ di ⟦Stormwind=Roccavento⟧.", "Mi' fratello, Nipsy, gestisce un'attività di spiedini di ratto dall'altra parte del tram degli Abissi. Devi portargli questa cassa di ratti prima che vadano a male. Muoviti!\n\nSei già salit<o/a> su un tram, eh? È facile. Monta a bordo quando arriva e goditi il viaggio. E tieni braccia e gambe dentro durante la corsa, se non vuoi ritrovarti con una gamba di legno a vita.", "<Nipsy infila l'indice in uno dei buchi per l'aria della cassa.>\n\nVivi e vegeti... e giusto in tempo!", "Povero Monty. Dall'incidente di Gnomeregan non è più lo stesso. Quel ragazzo non ha mai visto un oceano in vita sua, figurarsi fare il pirata.\n\n<Nipsy sospira.>\n\nAlmeno continua a mandarmi un bel flusso di bestiole che si dimenano.", 0xfb9ecfec, 0x87d7d034, 0xb75e7e9d, 0x3088e5a6, 0x9f0f0959, "....." },
  [6681] = { "Il Maniero dei ⟦Ravenholdt=Corvolesto⟧", "Porta il ⟦Seal of Ravenholdt=Sigillo di Corvolesto⟧ a Fahrad, al ⟦Ravenholdt Manor=Maniero dei Corvolesto⟧, nascosto tra le colline di ⟦Hillsbrad=Colletorto⟧.\n\nLungo la strada la tua astuzia sarà messa alla prova. Preparati.", "{name},\n\n⟦Ravenholdt=Corvolesto⟧ si è interessato a te, giovane ladro. Ti abbiamo osservato. Il tuo stile è un po' goffo, ma niente che non si possa correggere.\n\nSe sei pront<o/a> a intraprendere la carriera di discepolo di mastro ⟦Ravenholdt=Corvolesto⟧ e di membro della Assassin's League, non devi far altro che portare il ⟦Seal of Ravenholdt=Sigillo di Corvolesto⟧ (allegato a questa lettera) al ⟦Ravenholdt Manor=Maniero dei Corvolesto⟧.\n\nIl tuo primo compito è trovare il maniero, nascosto tra le colline di ⟦Hillsbrad=Colletorto⟧, e dimostrare la tua astuzia.\n\nCordiali saluti,\n\nFahrad", "Hai incontrato Milton?\n\n<Fahrad ride.>", "Eccellente, giovane ladro.\n\nSembri un po' malconci<o/a>, ma niente di grave.\n\nTi attende un lungo viaggio, lungo e ricco di ricompense. Sei pront<o/a> ad abbracciare finalmente il tuo destino tra i maestri di ⟦Ravenholdt=Corvolesto⟧?\n\nParla con le guardie qui fuori. Ti faranno cominciare.", 0x0b732c16, 0xad30c642, 0x8b5efb3f, 0x86bc2b9c, 0x29310286, "....." },
  [6721] = { "La via del cacciatore", "Parla con Dazalar a Dolanaar.", "Salve, giovane <cacciatore/cacciatrice>. Mi sembri abbastanza abile da gestire una bestia e addestrarla come tua compagna.\n\nDevi andare da Dazalar a Dolanaar. Può avviarti sulla strada per ottenere un famiglio tutto tuo.", nil, "Sì, è il momento, {class}.", 0xe59cef47, 0xacb77771, 0x57c4b6af, nil, 0xca92f25f, "...m." },
  [6722] = { "La via del cacciatore", "Parla con Dazalar a Dolanaar.", "Salve, giovane <cacciatore/cacciatrice>. Mi sembri abbastanza abile da gestire una bestia e addestrarla come tua compagna.\n\nDevi andare da Dazalar a Dolanaar. Può avviarti sulla strada per ottenere un famiglio tutto tuo.", nil, "Sì, è il momento di addestrarti...", 0xe59cef47, 0xacb77771, 0x57c4b6af, nil, 0x6d03693e, "...m." },
  [6761] = { "La nuova frontiera", "Parla con ⟦Mathrengyl Bearwalker=Mathrengyl Domaorsi⟧ all'⟦Cenarion Enclave=Enclave Cenariana⟧ di Darnassus.", "Ho affidato al mio secondo, ⟦Mathrengyl Bearwalker=Mathrengyl Domaorsi⟧, il compito di occuparsi della richiesta d'aiuto di ⟦Moonglade=Radaluna⟧. Parla con lui di questa faccenda, NON con me.\n\nLascia che ti dia un consiglio... amichevole. Sono stato io a guidarci fuori dalle tenebre, NON il ⟦Cenarion Circle=Circolo Cenariano⟧ di ⟦Moonglade=Radaluna⟧, quando tutto sembrava perduto per la nostra razza. Teldrassil dà a tutti noi una nuova vita! Loro vorrebbero farti credere il contrario, e credere alla loro propaganda sarebbe da stolti.\n\nLascio a te decidere se sei <uno/una> stolt<o/a> o no.", nil, "Sì, {class}, grazie di essere <venuto/venuta>. Mi scuso per il malinteso... tra l'arcidruido di qui e il custode Remulos a ⟦Moonglade=Radaluna⟧ l'aria è carica di sfiducia. Ciascuno sospetta l'altro di imbrogli, e il fatto che le strane corruzioni di Teldrassil continuino senza sosta resta un problema qui. Non aiuta certo a placare la sfiducia.\n\nIn ogni caso, il nostro dovere verso il ⟦Cenarion Circle=Circolo Cenariano⟧ rimane... anche se chi lo guida non è d'accordo.", 0x980efd04, 0xc843270f, 0x3b0ebeda, nil, 0x1a73fafa, "...m." },
  [6762] = { nil, "Parla con Rabine Saturna nel villaggio di ⟦Nighthaven=Nottequieta⟧, a ⟦Moonglade=Radaluna⟧. ⟦Moonglade=Radaluna⟧ si trova tra il ⟦Felwood=Vilbosco⟧ e ⟦Winterspring=Fontefredda⟧ ed è raggiungibile da un sentiero che parte dal ⟦Timbermaw Hold=Rifugio dei Mordilegno⟧.", "Per questo compito, il maggiordomo del custode Remulos a ⟦Moonglade=Radaluna⟧, Rabine Saturna, cerca aiuto per esplorare le vaste lande desolate molto a ovest di Tanaris... e ancora più a ovest di Un'Goro. Dovresti trovarlo a ⟦Nighthaven=Nottequieta⟧, il villaggio principale di ⟦Moonglade=Radaluna⟧.\n\nAnche se il tuo lavoro sarà senza dubbio di enorme beneficio per tutti noi, ti consiglio di muoverti con cautela. Ci sono tensioni tra Darnassus e ⟦Moonglade=Radaluna⟧... tensioni che col tempo potrebbero crescere.", nil, "Sono Rabine Saturna e, a nome del custode Remulos e di tutti gli abitanti di questa radura sacra, ti do il benvenuto.\n\nApprezzo il tuo interesse e la tua voglia di aiutare il ⟦Cenarion Circle=Circolo Cenariano⟧. So anche che l'arcidruido di Darnassus ti ha espresso il suo disappunto per l'aiuto che ci presti. Ti assicuro che è per un bene più grande, e che sarai al sicuro da qualunque sconsiderata ritorsione di cui potresti essere bersaglio.\n\nQui sei tra amici, {name}.", 0x53da4216, 0x2d1faec5, 0xf45142aa, nil, 0xbe6728af, "e..m." },
  [6804] = { "Acqua avvelenata", "Usa l'⟦Aspect of Neptulon=Aspetto di Neptulon⟧ sugli elementali avvelenati delle ⟦Eastern Plaguelands=Terre Infette Orientali⟧. Porta 12 ⟦Discordant Bracers=Bracciali Discordanti⟧ e l'⟦Aspect of Neptulon=Aspetto di Neptulon⟧ al duca Idraxis, ad Azshara.", "Un gruppo di esploratori elementali fu mandato nelle terre infette orientali di Lordaeron, e il morbo di quel luogo li ha distorti e contagiati. I Seguaci di Idraxis non possono tollerare questo affronto alla nostra purezza!\n\nPrendi questa fiala. Contiene una quantità di un aspetto di Neptulon. Se lo userai sugli elementali appestati, combatterà il veleno nei loro corpi e li curerà! Ma il conflitto interiore li getterà in una follia travolgente.\n\nSconfiggi le ondate discordanti e portami i loro bracciali di vincolo.", "Hai i bracciali?", "Hai agito bene, {class}. Gli elementali corrotti che hai curato erano un oltraggio per tutte le acque. La nostra forza sta nella nostra purezza, e se vogliamo vincere la guerra contro gli altri dobbiamo restare forti.", 0x8166e516, 0x9d1b8697, 0x2a5ec42b, 0x9a94795d, 0xdcea2c7a, "....." },
  [6805] = { "Stormer e Rumbler", "Uccidi 15 Dust Stormer e 15 Desert Rumbler, poi torna dal duca Idraxis ad Azshara.", "Noi, gli elementali dell'acqua, siamo in guerra con gli esseri degli elementi inferiori. Se sei davvero nostr<o/a> alleat<o/a> in questo conflitto, dimostrami la tua convinzione!\n\nLontano, a sud, nella terra desertica di ⟦Silithus=Silitus⟧, i servitori dell'aria e della terra si affannano in un angolo di roccia chiamato Valle di Cristallo. Proteggono oggetti di potere dagli esseri più piccoli, i mortali, e anche se non so perché lo facciano, voglio mandare a monte i loro sforzi.\n\nVa' nella Valle di Cristallo a ⟦Silithus=Silitus⟧ e sconfiggi i nostri nemici, poi torna da me.", "La codardia non è una cosa che teniamo in considerazione, {class}. Va' a ⟦Silithus=Silitus⟧ e dimostra il tuo coraggio.", "Il tuo coraggio è dimostrato, come il tuo valore per noi. Forse avrò altri compiti per te in futuro, compiti più degni di <un/una> alleat<o/a> <prezioso/preziosa> dei Seguaci di Idraxis.", 0x05d4b511, 0xc7106a5a, 0x85ab9517, 0x893965e3, 0xd9b082da, "....." },
  [6821] = { "L'⟦Eye of the Emberseer=Occhio del Veggente Ardente⟧", "Porta l'⟦Eye of the Emberseer=Occhio del Veggente Ardente⟧ al duca Idraxis, ad Azshara.", "Mi hai dimostrato di saper sconfiggere i nostri nemici e di saper portare a termine missioni per la causa dei Seguaci di Idraxis. Ma finora hai affrontato solo nemici minori... messo di fronte a un nemico potente, riusciresti a prevalere?\n\nQuesto è il tuo nuovo compito.\n\nIn alto nei ⟦Blackrock Spire=Bastioni di Roccianera⟧ gli orchi hanno catturato un servitore del fuoco, il ⟦Pyroguard Emberseer=Piroguardia Mirabraci⟧. Trova il luogo della sua prigionia, uccidi i suoi carcerieri e poi uccidi il Veggente Ardente. Portami il suo occhio e mi mostrerà il tuo valore.", "Hai l'Occhio, {class}? Hai la forza di entrare nei ⟦Blackrock Spire=Bastioni di Roccianera⟧?", "Ah, dunque hai la forza. E anche l'astuzia, perché i ⟦Blackrock Spire=Bastioni di Roccianera⟧ sono troppo per la sola forza bruta.\n\nIn verità, {name}, potresti ancora rivelarti <un/una> <alleato/alleata> <prezioso/preziosa> per noi...", 0x8318aac6, 0x6e3b7202, 0x4bc3b5c3, 0xf8a387b0, 0xe9a520af, "....." },
  [6822] = { "Il ⟦Molten Core=Nucleo Ardente⟧", "Uccidi 1 Fire Lord, 1 ⟦Molten Giant=Gigante Fuso⟧, 1 ⟦Ancient Core Hound=Segugio del Nucleo Antico⟧ e 1 ⟦Lava Surger=Elementale Dirompente di Lava⟧, poi torna dal duca Idraxis, ad Azshara.", "{name}, forse è tempo di metterti davvero alla prova. Sei pront<o/a>?\n\nIn fondo ai ⟦Blackrock Depths=Sotterranei di Roccianera⟧ c'è un passaggio verso il ⟦Molten Core=Nucleo Ardente⟧. È una roccaforte del nostro nemico, tenuta dai più potenti servitori del fuoco di questo mondo.\n\nVa' al ⟦Molten Core=Nucleo Ardente⟧, {name}. Mostrami che hai la forza e la volontà di sconfiggere ciò che vi troverai.\n\nE se hai alleati fra la tua gente, radunali. Solo un esercito può sperare di entrare nel ⟦Molten Core=Nucleo Ardente⟧ e uscirne vivo.", "Il tuo successo ti attende nel ⟦Molten Core=Nucleo Ardente⟧, {name}.", "Hai fatto ciò che quasi tutti quelli della tua specie riterrebbero impossibile. Hai affrontato gli esseri del ⟦Molten Core=Nucleo Ardente⟧ e hai trionfato!\n\nPer una creatura così piccola, hai mostrato grandi risorse.\n\nUn giorno, forse, potremo stringere una vera alleanza tra la tua specie e i Seguaci di Idraxis.", 0x65404883, 0xb78c36a3, 0x20707849, 0xc50496a5, 0x1cf1aca1, "....." },
  [6823] = { "Agente di Idraxis", "Raggiungi la reputazione Onorato con i ⟦Hydraxian Waterlords=Seguaci di Idraxis⟧, poi parla con il duca Idraxis, ad Azshara.", "Se desideri davvero allearti con noi, ti invito a muovere guerra ai nostri nemici, i servitori dell'aria, della terra e del fuoco. Ogni sconfitta che infliggerai loro indebolirà la loro presa su questo mondo e dimostrerà ancor più la tua fedeltà alla nostra causa.\n\nLa campagna sarà lunga, ma se perseveri la tua gloria e il tuo onore saranno grandi.", "La tua campagna non è ancora finita, {name}. Va' a sconfiggere i nostri nemici, i servitori dell'aria, della terra e del fuoco, e forse un giorno ti guadagnerai un posto nella sala dei Seguaci di Idraxis.", "Le tue imprese contro i nostri nemici risuonano nelle sale dei Seguaci di Idraxis, {name}. Alcuni pensavano che la tua forma fosse troppo piccola e fragile per combattere nella nostra guerra, ma hai ottenuto grandi risultati. Ti sei guadagnat<o/a> il nostro rispetto: un'impresa incredibile.", 0xf0c62cfa, 0xa57d2952, 0xba6762ec, 0xa7b43f6f, 0xe468742e, "....." },
  [6824] = { "Le mani del nemico", "Porta le Mani di Lucifron, Sulfuron, Gehennas e Shazzrah al duca Idraxis, ad Azshara.", "{name}, i tuoi servigi hanno un grande valore per noi, perciò siamo restii a mandarti in quest'ultima missione: non vogliamo perdere un agente tanto utile.\n\nMa il suo successo darebbe un impulso enorme al nostro sforzo bellico e... si è deciso che valesse la pena rischiare.\n\nVogliamo che questi capitani del ⟦Molten Core=Nucleo Ardente⟧ siano distrutti: Lucifron, Sulfuron, Gehennas e Shazzrah. Uccidili e portami le loro mani!\n\nQuesto compito richiederà ogni risorsa che possiedi, {name}, ma se ci riuscirai i Signori del Fuoco subiranno un colpo terribile.", "Hai sconfitto Lucifron e gli altri, {name}? Hai le mani del nemico?", "Hai le mani! Hai sconfitto i capitani del fuoco! Non l'avrei creduto possibile, se non avessi conosciuto te e ciò di cui sei capace.\n\n{name}, le tue imprese sono innumerevoli, ma la notizia di quest'ultima farà scalpore tra i Seguaci di Idraxis. Un giorno il tuo nome potrebbe diventare leggenda per noi.\n\nParlami di nuovo, {name}. Potrei avere un altro compito...", 0x6ed69526, 0x1128609f, 0x77ece8a4, 0x9200e18f, 0x143ecfe9, "....." },
  [6843] = { nil, nil, nil, nil, nil, 0x7a326c5c, nil, nil, nil, nil, "emmmm" },
  [6844] = { "Umber, archivista", "Porta l'⟦Encrusted Silithid Object=Oggetto di Silitide Incrostato⟧ a Umber, l'archivista del Circolo Cenariano, nel villaggio di ⟦Nighthaven=Nottequieta⟧, a ⟦Moonglade=Radaluna⟧.", "Qui c'è ancora molto da fare, ma credo che riportare questo al Circolo per farlo analizzare sia fondamentale. Fidati: il lavoro sarà ancora qui quando tutto sarà finito. Se dentro questa chitina appiccicosa c'è un diario, il Circolo avrebbe finalmente una finestra sul passato!\n\nPortalo all'archivista del Circolo a ⟦Nighthaven=Nottequieta⟧. Si chiama Umber, ed è un genio. Un po' toccato, certo, ma pur sempre un genio! Umber ha salvato tomi ridotti molto peggio di così. Se si può recuperare, ci riuscirà lui.", "Ma salve! Hrmm...\n\nLascia che sia un po' sincero con te, amico... hai un odorino piuttosto forte. Puzzolente, si potrebbe dire. Non è un attacco alla tua persona, eh. Dico solo che... in futuro, magari, potresti darti una rinfrescata quando torni dal lavoro sul campo. Le prime impressioni ne verrebbero impressionate un po' più positivamente!\n\nComunque... cosa posso fare per te?", "Per mille rospi scimmia! Cos'hai qui? Ha più o meno la forma di un libro, direi... Proverò a rompere questo guscio.\n\nTi manda Layo da ⟦Silithus=Silitus⟧? Ho sentito solo voci sommesse, che poi a pensarci tanto sommesse non sono, sugli orrori che succedono laggiù. Aggiungici che gli insetti e tutto ciò che ci somiglia non mi vanno proprio a genio, ed ecco la ricetta perfetta per restarmene qui con i miei libri!", 0xc0c48fe8, 0x110cbec8, 0xe16f6b67, 0x757645c2, 0xcd6bf57e, "....." },
  [6845] = { "Svelare i segreti del passato", "Parla con Rabine Saturna nel villaggio di ⟦Nighthaven=Nottequieta⟧, a ⟦Moonglade=Radaluna⟧.", "Comunque, dovresti ripassare da me piuttosto presto... sempre che tu voglia sapere cosa c'era qui dentro. Appena scopro di che si tratta, e se è davvero un libro, sarò felice di dirtelo.\n\nNel frattempo, io andrei a farmi vedere dalla chioccia di questo piccolo accampamento di orsi, Rabine. Di sicuro vorrà sapere in quali follie ti sei cacciat<o/a>. Non far mai aspettare la chioccia, {name}... a meno che tu non voglia ritrovarti copert<o/a> di miele.\n\nÈ già successo, fidati.", nil, "Ah, {name}, speravo che passassi. Sono lieto di vederti in salute.\n\nMi è giunta voce che saresti tornat<o/a> dal campo, e volevo esprimerti di persona la gratitudine del Circolo Cenariano per l'aiuto che ci hai dato finora. Di certo ⟦Silithus=Silitus⟧ nasconde altri segreti da svelare; ciò che hai consegnato a Umber dovrebbe rivelarsi molto interessante, una volta portato alla luce. Ti prego, accetta questo come segno del nostro costante apprezzamento per il tuo aiuto.\n\nGrazie, {class} generos<o/a>.", 0xeabb3200, 0x5071bbe4, 0x9bb68a79, nil, 0xa03acc7f, "...m." },
  [6846] = { "Inizia l'attacco!", nil, nil, "Le mie truppe sono rifornite e pronte all'assalto. Ci servono solo gli ordini di Noreg Stormpike e le manderò nella mischia!", "Ah, gli ordini! Dicono di attaccare quando voglio, e io voglio... adesso!", 0x80850fde, nil, nil, 0x1801510b, 0x3ee75b62, ".mm.." },
  [6901] = { "Lancia l'attacco!", nil, nil, "Le mie truppe sono rifornite e pronte all'assalto. Ci servono solo gli ordini del quartiermastro dei Lupi Bianchi e le manderò nella mischia!", "Era ora! Adesso possiamo mostrare all'⟦Alliance=Alleanza⟧ che follia è stata venire nella ⟦Alterac Valley=Valle d'Alterac⟧!", 0x6ce8c6de, nil, nil, 0x2a18344c, 0x48b87d80, ".mm.." },
  [6921] = { "Tra le rovine", "Porta il ⟦Fathom Core=Nucleo Profondo⟧ a Je'neu Sancrea, all'⟦Zoram'gar Outpost=Avamposto di Zoram'gar⟧, a ⟦Ashenvale=Valtetra⟧.", "Il ⟦Twilight's Hammer=Martello del Crepuscolo⟧ si è insediato nelle Moonshrine Ruins degli ⟦Blackfathom Deeps=Abissi di Fondocupo⟧. La loro presenza può servire solo a costringere gli elementi ad agire contro di noi. Se nessuno li ferma, questa regione sarà loro per sempre.\n\n{name}, entra a ⟦Blackfathom=Fondocupo⟧ e trova la pietra profonda delle rovine; dovrebbe essere da qualche parte nell'acqua, lì vicino. Al suo interno c'è un Nucleo Profondo, un congegno che, se letto correttamente, rivela la storia di tutta l'attività elementale. Se l'avessi, io e il Circolo della Terra potremmo forse fare qualcosa per fermarli!", "Sei riuscit<o/a> a trovare il Nucleo Profondo? Senza, non avremo idea di cosa stia tramando esattamente il ⟦Twilight's Hammer=Martello del Crepuscolo⟧ laggiù.", "È proprio quello che mi serve! Un Nucleo Profondo è un'incredibile fonte di informazioni da cui potremo trarre molto di buono. Qualunque cosa stia tramando là dentro il ⟦Twilight's Hammer=Martello del Crepuscolo⟧, e credimi se ti dico che non è niente di buono, ora i miei compagni e io lo scopriremo.\n\nOggi hai fatto un buon lavoro; il Circolo della Terra ti guarda con favore per averci aiutato. Hai aiutato anche l'⟦Horde=Orda⟧ intera, e per questo dovresti andarne fier<o/a>.", 0x09596e4f, 0xedf98535, 0x8b83bfb4, 0x55331311, 0x22dfd3c7, "....." },
  [6922] = { "Il barone Aquanis", "Porta il ⟦Strange Water Globe=Globo d'Acqua Strano⟧ a Je'neu Sancrea all'⟦Zoram'gar Outpost=Avamposto di Zoram'gar⟧, nella ⟦Ashenvale=Valtetra⟧.", "L'elementale d'acqua sconfitto ha lasciato dietro di sé uno strano globo d'acqua. Intuisci che l'oggetto, in qualche modo, nutriva di energia la creatura. Dentro il globo si agita un'acqua dall'aspetto putrido. Il globo stesso sembra immune a qualsiasi forza fisica.\n\nSe qualcuno può capire qualcosa di questo oggetto, è Je'neu Sancrea del Circolo della Terra. Si trova all'⟦Zoram'gar Outpost=Avamposto di Zoram'gar⟧ dell'Orda, nella ⟦Ashenvale=Valtetra⟧.", "Ah, eccoti di nuovo, {name}. Stavo leggendo le onde del mare, come faccio sempre. Che cosa ti porta all'avamposto?", "Questa... questa è una bella scoperta, {name}.\n\nDici di averla presa al barone Aquanis, negli Abissi di ⟦Blackfathom=Fondocupo⟧? Da tempo si pensa che il barone Aquanis sia un potere elementale corrotto; questo globo dimostrerà che cosa esattamente l'abbia corrotto. Non sarebbe una sorpresa se si rivelasse opera del ⟦Twilight's Hammer=Martello del Crepuscolo⟧, ma i nostri studi mostreranno anche come ci siano riusciti.\n\nHai fatto bene a portarmelo. Ti prego, prendi questo, insieme ai più calorosi saluti del Circolo della Terra.", 0x6317c3fa, 0x5afab460, 0xeafedd21, 0xd1397112, 0x5fa18944, "....." },
  [6961] = { "⟦Great-father Winter=Babbo Inverno⟧ è arrivato!", "Parla con ⟦Greatfather Winter=Babbo Inverno⟧: si trova vicino all'area dei venditori della Masseria Buongusto, a Orgrimmar.", "Buon Grande Inverno, amico! Non dimenticare di salutare ⟦Greatfather Winter=Babbo Inverno⟧! Se quest'anno sei stat<o/a> buon<o/a>, riceverai doni meravigliosi il giorno della Festa del Grande Inverno. Non dimenticare di dirgli cosa speri di ricevere quest'anno!\n\nE non dimenticare di fare scorta di dolcetti da regalare a chi è stato buono quest'anno. Abbiamo un'ampia scelta. Dalla nostra fattoria alla tua tavola: è la bontà genuina della Masseria Buongusto!", nil, "Oh oh oh, salve. Sono ⟦Greatfather Winter=Babbo Inverno⟧ e, per gentile concessione della brava gente della Masseria Buongusto... \"Dalla nostra fattoria alla tua tavola: è la bontà genuina della Masseria Buongusto\"... ti auguro una fantastica Festa del Grande Inverno.\n\nSe quest'anno sei stat<o/a> buon<o/a>, forse riceverai dei dolcetti dalla Masseria Buongusto come regalo per la Festa del Grande Inverno. Urrà.", 0x9a9ce503, 0x591cc909, 0xba4aa7ab, nil, 0x296b27e3, "...m." },
  [6962] = { "Dolcetti per ⟦Great-father Winter=Babbo Inverno⟧", "Porta 5 Pan di Zenzero e un ⟦Ice Cold Milk=Latte Ghiacciato⟧ a ⟦Greatfather Winter=Babbo Inverno⟧, a Orgrimmar.", "Ehi, puoi fare un favore a ⟦Greatfather Winter=Babbo Inverno⟧, ehm, <bimbo/bimba>?\n\nNon per parlare di me in terza persona senza motivo, ma ⟦Greatfather Winter=Babbo Inverno⟧ è all'opera da tutto il giorno e un dolcetto gli farebbe proprio comodo. Qualche biscotto di pan di zenzero e del latte ghiacciato per mandarli giù sarebbero proprio l'ideale. Credi di poter dare una mano a ⟦Greatfather Winter=Babbo Inverno⟧ e andarmene a prendere un po'?", "Tutto questo parlare di dolcetti mi ha fatto venire voglia di mangiarne qualcuno. Mmmm... biscotti di pan di zenzero e latte...", "Sei proprio un bell'aiutante per il vecchio ⟦Greatfather Winter=Babbo Inverno⟧, {name}. Buona Festa del Grande Inverno.\n\nEcco un pensierino... sai, per il disturbo.", 0xf3a28acd, 0xf01a51da, 0xd3822e00, 0x11c73f24, 0x004980cd, ".....", nil, nil, 0xcc6e16c8, nil, nil },
  [6963] = { "Dolci rubati del Grande Inverno", "Trova l'investigatore della Masseria Buongusto scomparso nelle regioni innevate delle ⟦Alterac Mountains=Montagne d'Alterac⟧.", "Senti... non voglio rovinare la magia della stagione, ma la Masseria Buongusto avrebbe bisogno di un po' di aiuto, del tipo che voi avventurieri siete famosi per dare.\n\nCi manca un'importante spedizione di dolci che doveva rifornirci per la stagione, e ora ci manca anche l'agente della Masseria Buongusto che avevamo mandato sul campo a cercarla! Ti prego: secondo l'ultima notizia, la spedizione era nelle ⟦Alterac Mountains=Montagne d'Alterac⟧, ed è lì che il nostro uomo è andato a cercarla.\n\nVedi se sono lì, sani e salvi!", nil, "M-m-mi senti! Sia l-l-lodato il b-b-bilancio!\n\nNon sono davvero un p-p-pupazzo di neve: mi c-c-chiamo Sacks e l-l-lavoro per la f-f-filiale di Orgrimmar della Masseria Buongusto... Mi hanno m-m-mandato qui a cercare un p-p-pacco scomparso, quando sono stato attaccato da una c-c-creatura che non avevo mai visto p-p-prima!\n\nChe f-f-freddo...", 0x3874de93, 0xfed7fa48, 0x497a89c9, nil, 0x377efbe5, "...m." },
  [6964] = { "Il senso della festa", "Parla con ⟦Sagorne Creststrider=Cardoza Marcia Creste⟧, nella Valle della Saggezza di Orgrimmar, della Festa del Grande Inverno.", "Regali, dolcetti, doni... bah, dico io!\n\nQuei goblin inquinano il vero significato di questa stagione: la Festa del Grande Inverno. È un tempo di rinnovamento; la terra dorme sotto una coltre di neve portata da ⟦Greatfather Winter=Babbo Inverno⟧, che NON è quel buffone impacciato vestito di rosso laggiù!\n\nSe vuoi scoprire da te che cosa sia davvero la Festa, chiedi a ⟦Sagorne Creststrider=Cardoza Marcia Creste⟧. Sono sicuro che si stupirà che a qualcuno importi della storia più che dei regali.", nil, "La Festa del Grande Inverno, dici? Ahimè, un tempo aveva un significato più profondo per noi tauren. Oggi sembra che altri abbiano trasformato la leggenda di questa stagione di rinnovamento in qualcosa che aiuta a vendere dolciumi e regali.\n\nNon c'è da stupirsi che Furmund sia amareggiato per un cambiamento del genere. Lui e altri tauren come lui si aggrappano al nostro passato come a uno stendardo di guerra. Anche se credo che un po' di festa faccia sempre bene, è importante ricordare le origini della Festa.", 0x64e6e152, 0x9b2211a9, 0x0a5d9d35, nil, 0x100c2eb2, "...m." },
  [6981] = { "La ⟦Glowing Shard=Scheggia Brillante⟧", "Va' a ⟦Ratchet=Porto Paranco⟧ e trova qualcuno che possa dirti di più sulla scheggia brillante.\n\nPoi consegna la scheggia come ti verrà indicato.", "Il frammento è di un verde brillante e, benché solido, appena sotto la superficie sembra vorticare del fumo. Non riesci a smettere di fissare le profondità del cristallo; al tempo stesso, sai che c'è qualcosa di molto inquietante in esso.\n\nForse dovresti vedere se qualcuno a ⟦Ratchet=Porto Paranco⟧ sa dirti di più su questo strano frammento.", "Salve, {race}. Cosa posso fare per te?", "Oh... non ho mai visto niente del genere...", 0x855951c0, 0x9db6d7f4, 0xf1eddfb4, 0x60aba222, 0xcb5cd7b9, "....." },
  [6983] = { "Sei proprio cattivo...", "Trova il ⟦Stolen Treats=Dolce Rubato⟧ e riportalo a ⟦Kaymard Copperpinch=Kaymard Pinzarame⟧ a Orgrimmar. Si crede che l'ultimo ad averlo avuto sia l'Abominable Greench, che si trova da qualche parte nelle regioni innevate delle ⟦Alterac Mountains=Montagne d'Alterac⟧.", "Una c-c-creatura chiamata «⟦The Abominable Greench=L'Abominevole Greench⟧» è quella c-c-che ha rubato la nostra spedizione di d-d-dolci, {name}. Ma s-s-sta' attent<o/a>! È lui c-c-che mi ha ridotto in questo s-s-stato, tutto coperto di neve!\n\nTi s-s-servirà un po' d'aiuto per a-a-affrontarlo. L'ho visto g-g-girare dappertutto dove ci sono gli y-y-yeti; di s-s-sicuro è qui da qualche p-p-parte! T-t-trova i dolci, {name}, r-r-riportali alla Masseria Buongusto a Orgrimmar e d-d-di' loro che ho b-b-bisogno di essere s-s-scongelato!", "{name}, la nostra Festa del Grande Inverno sarà rovinata senza quei dolci per rifornirci! Persino Graccu non potrà condividere i suoi deliziosi pasticci di carne con tutti i bravi bambini e le brave bambine in questa stagione...", "L'hai trovato! Hai salvato la Festa del Grande Inverno della Masseria Buongusto!\n\nPovero Sacks... manderemo di sicuro una squadra lassù a trovare un modo per scongelarlo. Speriamo che torni in tempo per il giorno della Festa; dovrà però recuperare le ore di lavoro perse. Comunque, niente di tutto questo sarebbe stato possibile senza di te!", 0xdc4f5e6e, 0x02350e7e, 0x390e1fd2, 0x5cb087ef, 0x84619c0c, "....." },
  [6984] = { "Un grazie dalla Masseria Buongusto!", "Parla con ⟦Great-father Winter=Babbo Inverno⟧ a Orgrimmar.", "Noi della Masseria Buongusto ti siamo grati per aver recuperato i dolci rubati, {name}. Per questo vorremmo offrirti un regalo speciale... consegnato nientemeno che da ⟦Great-father Winter=Babbo Inverno⟧ in persona!\n\nTi prego, parla con ⟦Great-father Winter=Babbo Inverno⟧: ti darà il tuo regalo della Festa del Grande Inverno da parte di tutti noi della Masseria Buongusto. Dalla nostra fattoria alla tua tavola, è sempre la bontà genuina della Masseria Buongusto... grazie a te, naturalmente!", nil, "Oh oh oh, salve, avventurier<o/a>!\n\nI goblin mi hanno detto che ti sei guadagnat<o/a> un regalo speciale in queste feste, e sono lieto di dartelo. Ecco qua: buona Festa del Grande Inverno, quest'anno e in tutte le stagioni a venire.", 0xfdb1c16f, 0xd0fa8c0a, 0x37044edc, nil, 0xc8c04af1, "...m." },
})
